/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240122-6","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"区民委員会","time":"午後 １時００分～午後 ４時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"品川区再犯防止推進計画（素案）に係るパブリックコメントの結果","agenda":"品川区再犯防止推進計画（素案）に係るパブリックコメントの結果","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"区民としては今後何をどうということもあると思うのですが、この人数的なことを区としてどう考えているのかということ。課題というか、何かもう少しこうしたほうがいいのではないかなど、今の時点であればお伺いできればと思います。","respondent":"宮澤地域活動課長","answer":"区民の方からのご意見は１０件ではございましたけれども、保護司の方々であったり、そういったところを総合的に踏まえて検討していくところです。５年後には改定をする予定でもありますので、今後計画が動き出してから、状況等を踏まえながら検討していきたいなというところです。","id":"exchange-001"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そのような若い人たちの犯罪というところでいうと、児童相談所などと、計画との関わりで何か連携していく部分というのはあるのか尋ねました。","respondent":"宮澤地域活動課長","answer":"全庁的に、横断的に検討していくという中で、この計画になっております。それは福祉部門にしても、子育て部門にしても同じようなところです。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問・要望","question":"昨年刑務所にも視察に行ってお話を伺ったところ、やはり高齢者が多い、障害者も多いと。こちらは一つ要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"なぜこの再犯防止推進計画を地域活動課でやることになったのですかということが１点と、例えば民生委員などが入っていらっしゃるのでしたか。〔「地域活動課」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"地域活動課ですか。これ、現場を知っている方が見てどのように感じられるか、教えていただけますか。","respondent":"宮澤地域活動課長、河合生活安全担当課長","answer":"犯罪を犯した方とまさに対話をして直面する保護司の方々というところがございまして、地域活動課でこの計画を所管させていただきました。犯罪を犯してしまった方への支援は様々な部署で行っておりますので、計画を策定… 行政等で連携しながら関与していく必要があるという、やはりこの計画が策定されるということはいいことだと、現場としても感じるところです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問・要望","question":"今日のこれは素案ですから、被害者ということで分けるならば、被害者もいるわけです。そのような流れというものは、今答えられる範囲でどのような形になっているのか尋ねました。","respondent":"宮澤地域活動課長、河合生活安全担当課長","answer":"犯罪被害者支援というところで、また、区内の４警察署と合同でのキャンペーンを実施しているというところです。犯罪被害者支援に関しても、やはり様々な部署で取組を行っておりまして、庁内横断的な検討の会議も行っているところです。 関係部署が連携してということで、ニーズへの対応等はそれぞれが担当して、個別具体的に丁寧に取り扱うというところで連携しています。","id":"exchange-006"},{"speaker":"横山委員","kind":"確認","question":"１点確認なのです。パブリックコメントは今回５名の方から１０件いただいたということで、ご意見としてどのように伝わっているのかなというところを確認させてください。","respondent":"宮澤地域活動課長","answer":"該当する担当部署に、ご意見の内容とともに区の考え方という部分に関しても、作成に協力いただきながらやっているところです。再犯防止推進委員会で、改めてパブリックコメントの内容も踏まえた形で、再度意見聴取をしています。","id":"exchange-007"},{"speaker":"横山委員","kind":"意見","question":"この１のご意見に対する区の考え方のところにもあるかと思うのですけれども、このパブリックコメントを見ていても感じたところです。区民全体の理解を深めていただくということが第一、この５年では大変重要なのかなと思うのですけれども、区のお考えを説明を求めました。","respondent":"宮澤地域活動課長","answer":"委員ご指摘のとおり、今回こういった形で事業の体系化、また見える化ということで、これまで取り組んでいる支援を一つ総合的に、計画に載せました。今後、それぞれの部署との横の連携は引き続き行っていきながら進めていきたいと考えているところです。","id":"exchange-008"}]},{"id":"topic-02","title":"戸籍法改正（令和６年３月１日施行）による戸籍事務の変更","agenda":"戸籍法改正（令和６年３月１日施行）による戸籍事務の変更","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"ただその場合は、そのマルチコピー機にマイナンバーカードで認識をして先方の自治体とやり取りをする。営業日で３日間とか、５日間とか置かないと取得できないというような仕組みになっておりますが、このようなことでよろしいのか尋ねました。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、その場で即時でオンラインでつながって、即時発行が可能になります。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"品川区の窓口に行って、個人の出生から逝去までの全ての戸籍謄本が欲しいのですけれどもとお願いをした場合には、それは今後はやっていただけるのか尋ねました。","respondent":"吉野戸籍住民課長","answer":"出生から死亡まで全部調べて、その場で交付します。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"今までだったら郵送で、印紙等を何千円分か入れて送って調べてください、と。その１回の手続きで、利用者が来ればそれは終わるという認識でよいか、最後にこれだけお伺いします。","respondent":"吉野戸籍住民課長","answer":"ただ、やはりデータの持ち方というのが、昔の戸籍はＰＤＦの形になっているのです。ですから、ちょっと中を見なければいけないということもありますので、すぐにではないのですけれども、お時間をいただいて、全部の発行は可能です。","id":"exchange-011"},{"speaker":"横山委員","kind":"確認","question":"今のところで少し確認なのですけれども、ＰＤＦ化されていればコンピュータ化されているという認識でよろしいのでしょうか。その辺りを説明を求めました。","respondent":"吉野戸籍住民課長","answer":"それ以外の、それ以前のもの、縦書きになっている戸籍に関しましてもＰＤＦになっています。一応法務省のほうでは今そのような形になっているのですけれども、令和２年に大体データ化できたというような話を伺っております。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"すみません、もう１点だけ。今までの手続きどおりで変わらないということでよろしいのか尋ねました。","respondent":"吉野戸籍住民課長","answer":"今までは本籍地であれば、いわゆる第三者請求などといったものができました。これに関しては、直系尊属、直系卑属のみが対象になります。","id":"exchange-013"}]},{"id":"topic-03","title":"本日は、昨年７月４日の委員会において決定いたしました所管事務調査項目のうち、町会・自治会支援","agenda":"本日は、昨年７月４日の委員会において決定いたしました所管事務調査項目のうち、町会・自治会支援","exchanges":[{"speaker":"せらく委員","kind":"質問","question":"やはり町会に若者、その建設時から、ファミリー層とワンルームマンションとのバランスというものを取っていらっしゃるのかどうか。地域活動課としても関係の所管に地域のことを伝えているのかなど、そういった点をお聞かせほしいと求めました。","respondent":"宮澤地域活動課長","answer":"なかなか確実な解決方法というのは難しい分野だとは認識しているのですが、町会のＰＲを含めて、アンケートをデジタル的な回答でできるような形で。いわゆる売買の際の重要事項説明の際に、同じように条例のリーフレットを説明してもらっていたりというところはお願いしています。","id":"exchange-014"},{"speaker":"せらく委員","kind":"質問","question":"もう１点、ＩＣＴ活用促進補助金についてなのですけれども、ここが予算に対してなかなか執行が少ないという状況なのです。５町会に派遣されていて、利用できるものなのか、利用回数制限などがあるのかを教えていただけますか尋ねました。","respondent":"宮澤地域活動課長","answer":"必要があれば継続的に支援をしていきたいというところです。今年度行っている５町会に対しても、７月ぐらいから、支援を進めているというような形です。","id":"exchange-015"},{"speaker":"せらく委員","kind":"確認","question":"今、町会へ利用するかどうか聞いているというところで、やはり役員の高齢化がある中で、こういう支援がありますよと出しておくだけではなかなか利用が進まないと思ったので、そのように町会に確認していただいているということで安心いたしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"えのした委員","kind":"質問・要望","question":"その辺が分かれば教えていただきたいということと、区内、実際にきちんと選任されているのかということを教えていただきたい。これは要望です。","respondent":"宮澤地域活動課長","answer":"地域連絡調整員ですけれども、この条例制定以降から、通算で１１７件の届出をいただいております。それとは別に、その建設予定地の各町会・自治会に、直接説明やコンタクトを取っているというようにもお聞きしています。","id":"exchange-017"},{"speaker":"えのした委員","kind":"質問","question":"条例制定されてから８年、これから様々取組をしていただいて、加入率が増えるように願っております。今の地域連絡調整員ですか、規約というのですか、マンション入居者の方も町会に入れるような進め方をしていただけるとありがたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのうち１５万円は区から助成が出たということなのですが、できれば少し助成額を増やしていただきたいという、ちょっと個別の具体的な要望です。３つ伺います。","respondent":"宮澤地域活動課長","answer":"平成２６年から始めておりますけれども、複数の相談はあって、それに対応しているという状況です。最後の掲示板設置補助に関しましては、ご意見として伺います。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"提案","question":"８割という中で百十数件という、地域連絡調整員の確認ができている数ですから、町会・自治会の方が分かるようなものをぜひ。これは一部、代表的なものの列挙と、このようなことでよろしいのか尋ねました。","respondent":"宮澤地域活動課長","answer":"他課でも町会・自治会に対して支援している、各地区の町会長・自治会長会議にお邪魔して、説明も毎年しています。見える化して横展開ができれば、各町会・自治会の助けになるのかなと考えていて、今後の方向性という形で先ほど説明させていただいたところです。","id":"exchange-020"},{"speaker":"横山委員","kind":"確認","question":"幾つか確認になるのですけれども、こちらは令和４年度のものと、令和４年は好事例集をまとめていただいています。令和５年、何かツールがあってそれをという形なのかなと思うのですが、そのイメージを教えていただけたらなと思います。","respondent":"宮澤地域活動課長","answer":"令和４年度から伴走型支援に取り組んでおりますし、そこにどこの町会にどのような支援をしたという取組と、資料として見られるようにしています。今年度もコンサルタントの支援をしておりまして、そこから…","id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"確認させていただきました。この（１）の部分に関して、ぜひ活性化を進めていただきたいなと思っているのですけれども、どのように考えていらっしゃるのか説明を求めました。","respondent":"宮澤地域活動課長","answer":"いわゆる連携強化ですけれども、スマホの取扱いの説明会というものを、強みを持っているＮＰＯと協力してやっていくというような事例がございました。マンションの管理組合と町会との連携ということを、好事例もありますので…","id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"いろいろ求めている、その質を上げていくというところからでないと、ゆっくりと丁寧にマッチングを進めてほしいと求めました。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"山本委員","kind":"確認","question":"その中で改めての確認になるのですけれども、区としては、それに対してどうしてだと思っていらっしゃいますでしょうか。説明を求めました。","respondent":"宮澤地域活動課長","answer":"イベントの参加の部分につきましては、今年度は、先ほど一覧の中で説明しましたが、町会ごとのイベントが、コロナ後非常に復活してきています。担い手が不足している背景には、やはり固定化というところ、新たなやろうとする方をなかなか見込めないというところが原因なのかなで…","id":"exchange-024"},{"speaker":"山本委員","kind":"質問","question":"ですから、品川区全体の、その辺の現状についてのお考えはいかがでしょうか。説明を求めました。","respondent":"宮澤地域活動課長","answer":"このような活動をしましたというイベントの実施報告等も含めて、お知らせしながらしているというところもあります。いわゆるアナログな掲示板という部分と、ＳＮＳ等を含めたデジタルでの発信というものを両方含めて支援していきたいと思っているところです。","id":"exchange-025"},{"speaker":"山本委員","kind":"質問・要望","question":"引っ越しでの転入の方だけではなくて、それ以外の方々にもきちんと届くような発信をしていただきたいということが一つ、これは要望です。そのようなものをぜひ実現していただきたいなと思っているのですが、これについてのお考えを説明を求めました。","respondent":"宮澤地域活動課長","answer":"なかなか難しいなと思っていることが、ＳＮＳなどですと、やはりタイムリー性を求められてくるので、そこをどう支援するか。最も身近な支援をしている地域センター等もありますので、相談等に乗りながら対応していきたいなと考えているところです。","id":"exchange-026"},{"speaker":"山本委員","kind":"質問・要望","question":"既にあるプラットフォームの中身をよくすることなども、地域センターなどと連携して効果的に進めていただくことをご検討いただきたいということで、要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"自治会支援という意味で、今八潮はどうなっているのですか。いろいろどうなっているのかということと、それと八潮地区においては、外国の方々はどのぐらいの人数いらっしゃるのか尋ねました。","respondent":"宮澤地域活動課長、川島地域振興部長、中西八潮まちづくり担当課長","answer":"やはり若い世帯に活動に参加してもらうには、任せてみるということが一つキーワードだというところが、その交流会の話合いの中で出てきたです。… ごみの収集まで町内会のほうで担っていくというような、もう生活との密着度合いが違うのかというところ、それからライフスタイルの変化です。… 今その２つの自治会の中では、自分たちが何をすべきなのかということをもう１回整理しようということで、今お話を進められております。では次のイベント…","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"１月１日に地震が起きたわけですから、１回、意識の中で参加していただくようなイベントを考えていっていただきたいと考えています。これは要望でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"何かあまり変わっていない感じが私は少ししているのですけれども、この課題の推移というのですか、変化はあるのか。町会・自治会が求めている支援、ここの変化というものもあれば教えていただきたいです。","respondent":"宮澤地域活動課長","answer":"今年度新宿区のほうで検討委員会を設けて、検討しているということは聞いている状況です。は回覧物等の精査、もしくは大きさの制限というものも設けるなりして、少しでも負担が減るような形で取り組んでいるところです。","id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはりその課題や求めている支援にどう応えていくかというところで、区としても様々支援策を打ち出して、増やしたりしてきていると思うのです。昨年度が５町会で、これは別に５町会に区切っているわけではなくて、使っていただけるならもっと使ってもらいたいというものと考えていいのか尋ねました。","respondent":"宮澤地域活動課長","answer":"伴走型支援につきましては、５町会程度という形で予算を組んでおります。その中で、手挙げ方式で町会を募らせていただいたところ、ちょうど５町会が手を挙げたです。","id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"本当に様々交流しながら、連携しながら施策を打ってきているというところでは、引き続きよろしくお願いしますという状況にはなってしまうのですが、私たち自身も様々、これを聞いた上で一緒に存続させていく、そしてさらに大きいものにしていくというところでは…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"}]},{"id":"topic-04","title":"の中小企業支援","agenda":"の中小企業支援","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"モンゴル高専は５年生制だということで、まずどのくらいの人数の方が通われているのかなというところを確認したいです。あの子たちは元気かなと心配しているというところもあるので、長続きしていればいいなという思いを込めながら、質問します。","respondent":"小林商業・ものづくり課長","answer":"その技術、その仕事に活かせる能力をきちんと身につけているかどうかというところ、二つが大事な鍵になってくると考えています。品川区の中で長く働き続けていただくための支援や、この事業でもその部分はしっかりフォローというか、サポートしていきたいと考えているところです。","id":"exchange-033"},{"speaker":"えのした委員","kind":"質問・要望","question":"モンゴルから来ているのですから、またそこで交流が広がったりして、就職後の定着につながるのかなと考えています。これは要望として終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"創業・スタートアップ支援も様々、５か所ですか、またその５か所目の五反田産業文化施設も５月にオープン予定ということで進めていただいていると。インフラ、どういった人材が特に不足しているとか、その辺りは区としてどのようにつかんでいらっしゃるのかなということをお聞きしたいと思います。","respondent":"小林商業・ものづくり課長","answer":"経営者のところを今中心的に進めておりまして、経営層がこの取組の重要性をきちんと認識することによって、専門家を呼んで進めているところです。スキルというところも広げてやっていきたいと考えていますけれども…","id":"exchange-035"},{"speaker":"横山委員","kind":"提案","question":"どういった分野でどういった人材が必要なのかというような形で提案していただいたり、そのような形でぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、創業支援・スタートアップなのですけれども、なぜ、そもそもスタートアップに関して、区は支援するのでしょうか。その辺についてはいかがか尋ねました。","respondent":"小林商業・ものづくり課長、篠田文化観光課長","answer":"そのような中で少しでも、このような事業も含めて人材の支援というものを考えていくことによって、できるだけ区内の中小企業のお役に立てればと。何かしら区も支援しているのだということが、これも一つ… 私からは、五反田バレーに関して、観光視点からどう考えるかです。これから先、今後の可能性が非常に大きいのかなと思っていますので、これから取組について考えていきたいと考えています。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう１回その辺を考えていただきたいという思いがありますし、昔、今ＳＨＩＰへ行っているではないですか。あれだけ近くにあるわけですから、いろいろな意味でやっていっていただきたいと思うのですけれども、その辺について答弁お願いします。","respondent":"小林商業・ものづくり課長","answer":"２点目、西大井創業支援センターです。私の説明にも少し入れておりましたけれども、例えば武蔵小山創業支援センターが女性ということを一つ特徴にしているように、そのことがまた地域の。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"スタートアップが、スタートアップのために創業してやられるわけではないですか。西大井創業支援センターから上場している会社が出ているのですから。","respondent":"小林商業・ものづくり課長","answer":"創業・スタートアップ支援の施設ということで、魅力というところも含めてＰＲできるような事業にしていければと考えておりますので、引き続きご支援いただければと考えています。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"もういろいろ質疑はあったので、私からお伺いしたいことは２つぐらい。全然待遇が違うので、その辺り、この２０名の方というのはどのような在留資格で現在いらっしゃるのかというところを説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"「今日電車が遅れてしまうので予定どおりに行けない」ときちんと言ってくれたことがすごくうれしかったということがあって、意欲というか。例えば技能実習生のように最長５年というような期限はなくて、その意味で…","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そちらにも非常に力を入れている、そして日本から高専の先生も行かれているわけですから、多分その辺も力を入れて教えているのかなというところです。これは要望ですけれども、二重、厚くしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"山本委員","kind":"質問・要望","question":"５年で２０名の方が区内で就職されてやってきているというところで、この状況についての認識とこれからの展望について伺いたいと思っています。これが、企業から、モンゴル高専からの採用をもっともっとしていきたいというような声が結構あるのかどうかということを教えていただきたい。","respondent":"小林商業・ものづくり課長","answer":"支援として助成金のようなものを出す中で、このような取組を、今日はモンゴルの事業に焦点を当ててご説明はしておりますけれども。そのような中では、ＤＸを会社としてきちんとやっていかなければいけないのだという認識は、この事業を継続してやっていきたいと考えています。","id":"exchange-042"},{"speaker":"山本委員","kind":"質問・要望","question":"これも要望です。ここまで成長している企業がこれだけあるですとか、そのような形での成果、実績というものがあれば教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"ただいま創業・スタートアップ支援の中で成果といいますか、西大井創業支援センターからということでいきますと、大本の。その１期生の中には、その中に２社ぐらい出てきていて、そのような取組が１つでも増えるようにということでやっていきたいと考えております。","id":"exchange-043"},{"speaker":"山本委員","kind":"質問・要望","question":"現状運営しているものは４つあるのですけれども、要は稼働率というか、利用率がどれぐらいの状況なのかということが分かれば教えていただきたいと。個室のところは個室として教えていただきたいのですけれども、そういったところの状況と、それに対するお考え等を教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"貸しオフィスが１６部屋あるのですけれども、１つ空くと、選んで入っていただいているようにしています。かなり稼働率が高い状況とは思っておりますけれども、もう少しＳＨＩＰのほうで受け入れることができるのかなと、そのように認識しています。","id":"exchange-044"},{"speaker":"山本委員","kind":"質問","question":"ちなみに、それ以外の３つの施設はどうなのでしょうか。少し気になるので説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"武蔵小山創業支援センターと西大井創業支援センターを例に出しますけれども、武蔵小山創業支援センターのほうは。西大井創業支援センターが、この西大井創業支援センターも比較的稼働率は高い状況になっていまして、巻き込むという取組も大事だと考えていますので。","id":"exchange-045"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれの施設がかなり満室に近い状況でご利用いただいているということで、また、その満室の中でも、多くの方に来ていただくような工夫をして進めていただいているということで理解しまして、そのように進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この人材確保のところで、モンゴル高専のほうは確保策の一つということでご紹介いただきました。この今の中小企業が人材確保に苦慮している理由、原因というのを、区としてどのように考えているのか説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"これから課題になっていくだろうなと考えていますものが、やはりそのようなところで魅力の差というものはどうしても出てきてしまうのだろうと。あるいは本日ご説明したような取組でやっていることは、我々はご支援しているところで、そのようなところの支援を。","id":"exchange-047"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そしてそこに人材確保が進むということになっていくので、それはぜひ求めていっていただきたいなと思うのですけれどもいかがでしょうか。そのときはなぜなくしたのだと言ったのですけれども、だから、その辺はいかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"あるいは継続的に雇用を安定的にやっていくような仕組みづくりというところが大事だと考えておりますので、区としてまずやるべきところを。そのようなところも含めた、伴走型といいますか、ある程度寄り添った支援というものをきちんとやっていきたいなと考えているところです。","id":"exchange-048"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やっていただきたいのですが、それをずっと、ずっと必要としていたのです。ですから、やはり国にしっかり物を言っていかなければいけないなと思いますので、ここはお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332921?Template=document&Id=2980#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":61779,"voices":135}},{"id":"r06-20240122-7","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"厚生委員会","time":"午後 １時００分～午後 ６時０８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を94件整理しています。","topics":[{"id":"topic-01","title":"請願・陳情審査および報告事項","agenda":"請願・陳情審査および報告事項","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"私からは２点だけお伺いいたします。続けてよろしいか尋ねました。","respondent":"榎本荏原保健センター所長、東野福祉計画課長","answer":"私からは、精神障害者の保健福祉手帳の保有者数が増えている理由ということでしょうか。様々なことが起きている中で、そういったところで、非常に負荷がかかったときになかなかうまく対応できない方が増えてきているというようなことや。 ２点目の各所管での取組数に応じた人員配置等の見直しにつきまして、まず私のほうからお答えいたします。やはりそれに携わる人員の配置としては、所管としては必要だと考えていますので…","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"やはりやってみて、意外なところにニーズがあったりとか、そういったものを柔軟に対応していってほしいと求めました。非常に期待しておりますので、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私からは１点、このパブリックコメントの実施というところですので、その点についての意見と質問をします。その計画が何についての意見を求めているのかとか、どのように検討しているのか、もしあれば教えてほしいと求めました。","respondent":"東野福祉計画課長","answer":"パブリックコメントの実施に当たりまして、現在のところ説明会については実施の予定はございません。広報、この点についてご意見をいただきたいというような形で、区民の皆様へＰＲをきちんとしていきたいというふうに考えております。","id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、区のところと、説明会というのはご意見として何名かから聞くところであるので、ぜひ検討というところは進めていただければなと思います。要望で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今の説明会ですけれど、私も毎回求めていますが、説明会をぜひやっていただきたいということで、これは本当に検討していただきたいと思っています。この区民の意見を聞いて、私からもお願いしたいと思うのですけれど、他区の状況も含めてお聞かせいただけたらと思います。","respondent":"東野福祉計画課長","answer":"説明会をほぼやっていないというような状況でございまして、これらを今後どうしていくかについては、十分検討する余地はあるかなと考えています。今回につきましては、特に説明会はする予定はございません。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この２０代とか３０代の方とかは知っていただきたいものだと思っているのですけれど、あと、子ども家庭支援センターとかも１０％前後だったし。この、区民に知られていないという状況に対しては、区としてどう考えられているかも含めて伺えたらと思います。","respondent":"東野福祉計画課長","answer":"そういったことで周知には努めているところですが、各所管共々、これまで以上に努めていく必要があると考えています。これらを説明会につなげていくという部分におきましては、所管としまして考えていきたいと考えています。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"特別力を入れていただきたいのと、こういう観点からもぜひ説明会をしていただきたいということで、改めて要望させてほしいと求めました。その点を伺いたいのと、課題がどうなのか、どこでどういうふうにまとめられたのかというところについてもお聞かせいただけたらと思います。","respondent":"東野福祉計画課長","answer":"現在取り組んでいる重層的支援体制の強化の中で、次、そういったようなところでの取組を今後強化していきたいというふうに考えているところです。主立ったものにつきまして整理した形で、こちらのほうに掲載をしているものです。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひ１年ごとの評価の課題というところで、ご報告いただきたいなと思いますが、その点伺いたいと思います。概要版では５ページのところに、２０２２年度から移行準備事業を開始していて、具体的な中身も教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"アウトリーチの継続的支援、庁内での検討、検討している段階です。令和６年度、来年度の検討期間を経まして、令和７年度本格実施に向けて、現在取り組んでいるところです。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"されていると伺ったのですけれど、その重層的支援体制の核となるところはどういう部署なのか、その点についても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"その辺については一度ご説明させていただいておりまして、それから固定したほうがいいのではないかというようなところのご要望もいただいております。多機関連携の中でどういったところが必要かという部分については、十分考えていきたいというふうに思っているところです。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２０２５年から本格実施になるということで考えていいのでしょうかということと、そこの部署から、その点についても伺いたいと思います。やはり地域包括支援にしていっていただきたいなと思っているのですけれど、その点はどうなのか、その点についても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"地域包括支援につきましては、これまでも説明してまいりましたが、在宅介護支援センターそれから支え愛・ほっとステーションなどとの連携の上で。地域包括支援に向けての課題を区として十分捉えた上で、地域福祉計画として取り組んでいきたいというふうに考えているところです。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点でも、３職種の専門職が一緒に検討するというふうなことが、本当にとにかく保健師がいないのです。そこのところを３職種で検討できる、区としても検討いただきたいということを強く要望して、取りあえず一旦終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"この中で、確認というかお考えをお聞きしたいのは、例えば２つ目の矢印「身近な地域におけるゆるやかな見守り活動を支援します。この担い手というか寄り添っていく人、築いていく人、こういう人をどう確保していくかというところの考え方を確認させてください。","respondent":"東野福祉計画課長","answer":"現在２４企業、実は今年度中に皆さんが顔合わせをして、ふだんどういった活動しているかというようなものも行っていく予定で計画をしています。具体的なという部分では、それぞれ所管のところでＰＲなどを行いまして、確保に努めているというようなことで聞いているところです。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"このアンケートの中にも、いわゆる、どの程度の人間関係ですかという設問がありました。その担い手は、そういったところまで広げる必要が今後あるのではないかなというふうに私は考えるところなのですけれども、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"そういったところが皆さん連携をした形で、地域へ広げていければ、少しでも顔見知った活動というのができるかなと考えています。その方々は、どういった形でつなげられるかというものを今後考えていければというふうに思っております。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問なのですが、広報広聴課もこれ関わるのでしょうか、こういうのを掲載してくださいというふうにつくるのでしょうか。１つでもその質問があれば、この計画がより区民の皆さんにもご協力いただけるような、そうした発信をぜひしていただきたい。","respondent":"東野福祉計画課長","answer":"区としては、そういったところも含めて検討を進めてまいりたい。様々な場づくりというのをこれまでも区としては進めてきたところですが、これからも検討していきたいと考えています。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"今進めてくださっているという考えも伺いましたので、具体性のある、そうしたものに進めてほしいと求めました。こうした計画をより周知、知っていただきたいというのが一つの狙いだと思いますので、そうしたことの発信の工夫をお願いしたいといったところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"筒井委員","kind":"質問・要望","question":"２点ほど確認させていただきたいのですけれど、今４回まで開催されたと思うのですけれど、今回２０日間ぐらいになったのはどういった理由なのか。６年間かける計画なので、今回、この期間に設定した理由を説明を求めました。","respondent":"東野福祉計画課長","answer":"計画につきましては、他の計画等とも合わせまして、パブリックコメント期間が可能な３週間としています。掲載を３週間として、その後の取りまとめの時期につきましても、十分な期間を取っていきたいというふうに思っているところです。","id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"パブリックコメントも３週間ということなのですけれども、積極的に周知していただいて、様々な区民のご意見を知っていただきたいと考えております。この地域福祉計画概要版の２０ページによりますと、評価の結果というのは品川区のホームページなどで公表されるのかということの確認と、また。","respondent":"東野福祉計画課長","answer":"推進委員会ですが、これまでは具体的な内容についての公表は行ってきていないというふうに聞いております。あくまでも推進委員会としまして区の状況を把握して、それを次年度につなげていくための委員会というふうな位置づけです。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"そしてそれに対して区民の意見を吸い上げて、区民とともに地域福祉というのをつくっていくという姿勢がいいのかなと考えているのですけれど、その点いかがお考えか尋ねました。","respondent":"東野福祉計画課長","answer":"ただ、推進委員会自体は公開をしているものですので、こちらについて傍聴などもできるような仕組みを取っているところです。こちらのまとめにつきましては、次期計画にどう反映させられるかという部分を含めて、毎年委員との意見交換を行っているものです。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"いろいろな各種団体とか区民の方からのご意見を伺っていると思いますけれども、ぜひ、地域福祉の状況をしっかりと諮ってほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これは区としての受け止めをお伺いしたいのですけれども、認定者数は５年前の２０１８年と比べてほぼ横ばいという中で、要支援の方が増えていると。これについて、どういった理由といいますか、区として分析というか受け止めがあれば、お答えほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"私のほうからは、６８ページの要介護認定者数の推移についてのご説明をします。令和４年については、要支援などが多いという部分につきましては、その結果が数字として表れているというふうに認識しております。","id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そのコロナの特例は２０２０年から始まったということだと思うのですけれど、その中でも結構変動があると思うのです。要支援２の方が結構増えていたり、逆に要介護１の方が減っていたり、何か受け止めがあればお願いしたいのですけれどもとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"要支援の方が増えているというのは、それとしか言えない、適正に審査した結果ですというふうにしか申し上げられません。そのときには要介護４だった方が、要支援２ぐらいに回復しているのかなという方とか、だんだん精緻になっていくのかなと捉えております。","id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"確認","question":"次の２０２３年の調査で、ある意味、よりリアルな数字というのが上がってくるというような解釈でよろしいでしょうか。確認です。","respondent":"菅野高齢者福祉課長","answer":"今年度が２０２３年度なので、自動延長がなくなるのが来年度、２０２４年度ということになるので、その結果が自動延長なく、調査を全てするということになりますので、大分変わってくるのかなというふうに捉えております。","id":"exchange-022"},{"speaker":"やなぎさわ委員","kind":"質問","question":"かしこまりました。要介護の割合とかというのは、どのような推移をたどるというような予測をされているのか、もし数字があれば説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"予測なので何とも言えないところはあるのですが、人口の傾向としまして、２０２５年には団塊の世代の方が全て７５歳以上になる。国も大体進めている次第なのですけれども、８５歳以上の方が、より重い方が増えていく傾向になるのではないかというのは予想しているところです。","id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"意見","question":"要支援の方を自立になるような、ということをぜひ一緒に続けていければと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"もっとあってほしい、今後どういう方向でしていこうと考えられているのか、その点についても伺いたいと思います。区として国に対しても求めていくことが必要なのではないかなとも私は思ったりもしていますが、その３点、伺いたいと思います。","respondent":"東野福祉計画課長","answer":"区としては、令和６年度、地域協議会の設立に向けて取り組んでいきたいというふうに考えております。先ほど来話をしている、どういった形が福祉的な分野として取り組んでいけるのかについては、十分な検討を重ねてまいりたいと考えています。","id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これも、そういうところも増えているということでも伺っていまして、サービスそのものが継続できるかというところにかかっていると思うのです。やはり、人材がしっかりと確保できるための国の処遇改善というふうなところで求めていただきたいということで要望しておきたいと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"これ６年間見ますので、２５年に本格実施しますよという文章のほうがいいのかなと思ったところなのですけれども、細かいことで恐縮です。ただ、６年間の計画なので、いつ実施をしたかということが最後分かる文言のほうがいいのかなと思うところなのですが、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"ご意見いただきましてありがとうあります。ここにつきましては訂正させていただきたいと思います。","id":"exchange-027"}]},{"id":"topic-02","title":"障害者相談支援事業等に係る消費税の取扱い","agenda":"障害者相談支援事業等に係る消費税の取扱い","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"平成２４年の改正のときに、そういうふうに消費税がかかるということになったということなのでしょうか。それは、何でこの相談支援のところだけ消費税がかかるということになってしまったのでしょうかということを教えていただきたいのです。","respondent":"松山障害者支援課長","answer":"平成２４年度に相談支援体制が見直されまして、計画相談がそこから開始されることになりました。昨年７月に中国地方で障害者相談支援事業等に係る消費税についての新聞報道がされまして、昨年の１０月に通知を発出したというのが発端です。","id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問","question":"その時点で来てしかるべきなのかなと思うのですが、指定特定相談支援事業のほうだけがかかるということになったということなのですか。そこのところ、すみません。","respondent":"松山障害者支援課長","answer":"相談事業の中でも、課税のものと非課税のものがあるです。非課税なものは幾つかあるのです、計画相談の事業所が複数ありますけれども、そちらのほうは特定相談支援事業に当たるので、非課税だということです。","id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問","question":"そうなのですか。分かりました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問","question":"遡れるのが５年までだということは承知したのですけれども、ある意味、みたいなことというのは特に話合いしたりとか言われたりはしていないのですか。怒るかなと思うのですが。","respondent":"松山障害者支援課長","answer":"先ほどの平成３０年度から令和４年度までという、その以前については時効となっております。現在、丁寧に話合いを進めておりますので、金額的な負担というよりは修正申告を税務署にしていただくというところをお願いしている次第です。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"質問","question":"つまり、この対象事業者３社に関しては一応事情を説明して、これは時効なのでお支払いできませんというような……、あと、ここの部分は課税分というかその消費税分の支払いができないというようなことは、話合いは進めていて、ある程度理解をされているというような状況でよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"失礼いたしました。少し説明不足でしたけれども、事業者にもその旨、事業者から税務署に対しまして時効となった分まで支払う必要はないということで伝えてあります。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほどの鈴木委員の質問の補足ですけれど、これはでは、全国的に一斉にこのような事案は、品川区だけとかではなくて起きているというような解釈でよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"そのような形で全国的にも複数の自治体が該当しておりまして、同様に、速やかに対応をしています。","id":"exchange-033"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"相談内容によって課税、非課税があるとは非常に分かりにくいなと思うので、これは別に国のことではあるのですけれども、区として要望を上げていただけたらな、などというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"}]},{"id":"topic-03","title":"品川区立杜松特別養護老人ホームおよび品川区立杜松地域密着型多機能ホーム指定管理者候補者の公募","agenda":"品川区立杜松特別養護老人ホームおよび品川区立杜松地域密着型多機能ホーム指定管理者候補者の公募","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"１０年、１０年間ずっと指定管理で、若竹大寿会のほうから申出があったということですよね。この理由は何なのかというのをまず、お聞かせほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"その手挙げをしない予定ということの理由としましては、こちらの若竹大寿会は、横浜市の中心に事業を展開している法人となっております。そして、さらに物価高騰や人件費高騰の中で…","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"私も何回か若竹大寿会のほうにお話を伺って、そういうところで言うと、介護の人材を確保するのは本当に大変な状況になっていると思うのです。これ指定管理者なので、区のほうからもっと支援をして、赤字を支援するという対応というのはできなかったのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"経済的支援とかといったお話だと思うのですが、収支改善を図る一次的な責任者は、指定管理者にはあるということが大前提となります。は看護小規模多機能については、生活相談支援業務といった名目の下、人件費補助等もさせていただいていたという次第となっております。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"質問","question":"大規模というか普通の１００前後の特別養護老人ホームに比べたら、若竹大寿会がこれだけ、様々努力したと思うのです。公募をして応募があるような、そういう対応はどういうふうに区としては取ることを考えられているのか、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"事業者を変更することになるのですけれども、区としては、さらに効率的で質の高い区民サービスの提供を目指していかなくてはなりません。具体的には、現事業者が継続しない理由というところで先ほども申し上げましたが…","id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこのところは、国にぜひそれを求めていただきたいと思うのですけれど、その点が１点。区としても思い切った支援を行っていくということが必要なのではないかなと思うのですけれど、まず、その点と２つお聞かせほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"これは全国的な問題というふうに今、おっしゃっておりましたが、介護報酬のほうも改定されて１.５９％になるというところでは聞いてはおります。どうすることが介護人材の確保になるかというのを区ができる支援の形を…","id":"exchange-038"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで要望も出してほしいと求めました。やりがいのある仕事を生活が成り立つ形で保障していくというところでの考え方で、ぜひ支援もお願いしたいということで要望をしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"ひがし委員","kind":"意見","question":"１年ない期間の中で、手を挙げる人がいなかった場合の対応はどうなるのかなというふうに思っていて、その対応について聞かせてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"新しい事業者がどういった形でこの施設を引き受けてくれるのかというところを検討しながら、選定作業も進めていきたいと考えています。万が一のときには、決してサービスが停止することがないようにというのは、努めていかなくてはいけない大前提だと考えています。","id":"exchange-040"},{"speaker":"ひがし委員","kind":"意見","question":"今、通われている方とかいらっしゃる方々が不安にならないかなというところが一番心配だったので、継続していけるということで安心をいたしました。指定管理者の選定と、もし、その点についてはしっかりと相談をしながら進めていっていただければなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほどちらっと、この若竹大寿会はそんなに大きい法人ではないというようなお話もありました……大きいですか、分かりました。どういうふうにしていけば、その辺は何かお話をしているとか、そういった取組みたいなご予定はありますか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"若竹大寿会との協議の中では、次回の公募については手を挙げないという方針は、若竹大寿会の中では固いのかなというふうには思っているところです。杜松が１拠点だけ少し飛び地というか離れた所にあるというところで…","id":"exchange-042"},{"speaker":"やなぎさわ委員","kind":"意見","question":"この１.５９というのは、この１.５９というのも、そういった声をぜひ国のほうに上げていただきたく思います。何か受け止めがあればお願いいたしますとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"しっかりとこの事業が継続できるように、安定して継続可能な施設となるように、区としては努めていかなくてはいけないと思っているところです。","id":"exchange-043"},{"speaker":"こんの委員","kind":"提案","question":"前向きに進めていただきたいなというところですけれども、だけどこういう提案をしますよ、みたいなことの考え方はあるのでしょうか。介護という事業の中での課題というのも、考えていかなければいけないのだろうと思うのですが、まずはこの２点についてのお考えを説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"業務の内容ということなのですけれども、こちら今回、３のところで指定管理者が行う業務というところで、現在の業務を出させてはいただいております。よりよい…","id":"exchange-044"},{"speaker":"こんの委員","kind":"提案","question":"ご提案をいただいたその事業によっては、事業者がやるのですか、事業を展開していただくというふうになるのですか。その辺もお考えをお聞きしたいと思いますとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"区が用途変更というか、区が責任を持って、そういったたたずまいに変えて運営をお願いするということになると思います。","id":"exchange-045"},{"speaker":"こんの委員","kind":"提案","question":"ご提案くださるその事業で、事業が展開できるように、前向きにこの公募を進めていただきたいなと思います。いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"その中で在宅生活を可能な限り追求していくというものなのですけれども、そういった在宅生活を支えていく大きな施設となっております。今後も、一緒になって、どういうことを改善したらこの施設がよりよいものになるかということは検討しながら進めていきたいと考えています。","id":"exchange-046"},{"speaker":"こしば副委員長","kind":"質問","question":"前提としてお聞きしたいのですけれども、サービスの利用者の方々には、この状況というのはお伝えされているのか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"こちら、１２月に事業者のほうから継続しないというようなお話をいただいた次第です。今日をもってこれ以降、伝えていくのではないかというところで、現在の若竹大寿会とは調整をしているところです。","id":"exchange-047"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"あくまでもサービスの利用者の方々が、やはりこれを聞いたときには不安に感じると思いますので、その不安解消のためにぜひ取り組んでいただきたいと。ぜひ取り組んでほしいと求めましたし、利用者の方々にもその辺はお伝えしてほしいと求めましたので、そのお考えありましたら説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"現事業者ともお話はしていますが、新たな事業者が選定されたときには、引継ぎを十分に行って、利用者様やその家族が安心してもらえる施設運営に努めていきたいと考えています。","id":"exchange-048"}]},{"id":"topic-04","title":"新型コロナウイルス感染症対策の検証と健康危機管理体制の基盤整備検討報告書","agenda":"新型コロナウイルス感染症対策の検証と健康危機管理体制の基盤整備検討報告書","exchanges":[{"speaker":"筒井委員","kind":"意見","question":"それとも何か国の指導とかあって、こうしたことをやろうということになったのか、その点説明を求めました。","respondent":"坂野保健予防課長、舩木生活衛生課長","answer":"国とか都からやりなさいみたいな指示は出ていません。 若干補足的な説明をしますと、やはりこういったコロナの様々な対応について、対応の記録であるとかということをまず。約１年間かけまして、今回、この場での報告書という形でまとめ上がったという状況です。","id":"exchange-049"},{"speaker":"筒井委員","kind":"質問","question":"すばらしい判断かと思います。ちなみになのですけれど、他の区とかでもこうしたことをやっているとかという情報というのは何か、状況把握されていますか尋ねました。","respondent":"坂野保健予防課長、秋山保健整備担当部長","answer":"全ての、東京ですと世田谷区がまとめている部分があるのですけれど、ただ、もうちょっとシンプルな感じかと。都外ですと神戸市とか大阪府とかが似たような感じでまとめているかなと思います。 ここまで体系的にしっかりまとめているところはないと思います。","id":"exchange-050"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今後のこのせっかくまとめた報告書の活用の仕方というところを１点確認していきたいというのと、あとは１枚目に書いてある、どの辺りまで公表していく予定なのかというところがもし分かれば教えていただきたいです。","respondent":"舩木生活衛生課長","answer":"しっかりこの辺り平時の対応、それから備えも含めて対応を取っていくという動きなのですけれど、報告書の３８ページをご覧いただきたいと思います。人を手配するというところは…","id":"exchange-051"},{"speaker":"ひがし委員","kind":"確認","question":"組織支援体制というところで新たな取組、体制をつくるというところまで取り組んでいただけているということが確認できたので、安心をしております。広めていくのかなというところで、何か今の時点で考えているところ、区民へ幅広く広めていくための方法などについて検討状況を説明を求めました。","respondent":"舩木生活衛生課長","answer":"品川区、しっかりこういうものをまとめたものをしっかりと今後に活かしていく用意をしているということを知っていただく方法を考えたいと思います。１点だけすみません、既に２００９年の新型インフルエンザのときに、区としても整えていくというふうに考えております。","id":"exchange-052"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この４２ページに書かれているように、更新をしていくというところなので、定期的に行ってくれるのではないかなというふうに認識をしております。一般の方々が読んでも分かるような内容というところにまとめるということも大切なのかなというふうに思いますので、その点については、要望とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"職員からもお話も伺いながら、多分平均でも１年半以上、多い方ですと２００時間を超えていたという状況が続いているということを伺っていましたし。クラスターが出たりとかいろいろ大変だったと思うのですが、介護の分野のところからはなぜ入らなかったのか、その点についても伺いたいと思います。","respondent":"舩木生活衛生課長","answer":"検討委員会の委員の構成につきましては、事務局は除きますけれども１５名の委員で、２回ほど検討委員会を実施いたしました。こういう検討体制で検討したということが、掲載については考えたいというか、整理したいというふうに思っています。","id":"exchange-054"},{"speaker":"鈴木委員","kind":"質問","question":"続けて伺いますけれど、３波、それぞれに何人だったのかという形でまとめていただいているような場所はどこかにあったでしょうか。少し知りたいなというか、感染の実態というのが分かる、その点についていかがか尋ねました。","respondent":"秋山保健整備担当部長","answer":"感染症のほうの対応なのですけれども、正直、あのさなかで記録を体系的に残すということができていないというのが、なかなか難しいところなのです。これは東京都ないしは自治体で感染症の対応をされた医師の方…","id":"exchange-055"},{"speaker":"鈴木委員","kind":"質問","question":"課ごとでも、５人以上のクラスターがこういう施設で何か所感染が起こったかとかというのは、課ごとでもなかなか分からないものなのでしょうか。そこのところも、そこら辺も見えるような形にならないかなと思ったのですが、その点についてはどうか尋ねました。","respondent":"坂野保健予防課長、阿部品川区保健所長","answer":"特にオミクロンのときとか２回目の方がすごく多かった印象があります。だから、肝心な人数は足し上げても出ない形にはなります。 ただ、医療のニーズにはきちんとお応えするという形でやってまいりましたので、その辺は確定しないということ。そういったことがありますので、患者の数の把握については…","id":"exchange-056"},{"speaker":"鈴木委員","kind":"質問・要望","question":"保健センターとかも含めて、これからは専門職として、専門職でなければできないような仕事ということで整理されていくのかということも伺いたい。ここの中にも、ぜひその保健師の増員というところもぜひ入れていただきたいなと思っているのですけれど、その点はいかがか尋ねました。","respondent":"阿部品川区保健所長","answer":"もちろん、今回の組織改正を踏まえた対策については検討してまいります。やはり本来事務でもできる仕事を忙しいのに保健師がやるということは避けてまいりますけれども、ある程度、そのように考えてまいりたいと思います。","id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"このコロナの対応について検証をして、次につなげていただきたいという区長要望もしたこともありますので、御礼申し上げます。その時々の対応していただきたい業務が、その引継ぎ事項とか、このマニュアルをつくっていくという理解でいいか尋ねました。","respondent":"舩木生活衛生課長","answer":"今回のいろいろな対応を踏まえて、もちろんこの報告書の中により盛り込まれていたほうが好ましいものというのは多々あると思うのです。区民の生命というか健康を守っていくというような…","id":"exchange-058"},{"speaker":"こんの委員","kind":"質問","question":"先ほども少しご説明あったのですけれども、そうすると、これは新たな計画を立てるということなのでしょうか。先ほど整合性を持たせながらといった、それはそれで、今回の検証により健康危機対処計画というものになるという理解でいいか尋ねました。","respondent":"坂野保健予防課長","answer":"感染症法が令和４年の４月に改正されたのです。それで今、各自治体動き出しているという状況です。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"例えば５２ページのところで、本当にここも緊急要望を上げてすぐに対応してくださって、その辺はこの検証から見てこの辺はどうなっているのかが１点。今後こういったことも考えられるのではないですかというところで、そこの何階ですか、このところはどんなふうに考えていらっしゃいますか尋ねました。","respondent":"濱中新型コロナウイルス予防接種担当課長、秋山保健整備担当部長","answer":"なかなかこのシステムに対応が難しい方、そういった方にも配慮した体制を、今後の臨時接種の体制について検討をしていく必要があるかと考えています。集団接種会場の設置については、今後整理して検討していく… ご質問１点目の、健康危機管理対処計画にはワクチンの中身は入ってございませんので、それは盛り込むということはありません。具体的に動くかどうかというのは、また…","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問・要望","question":"確かにそうですよね、感染症によってはそういう対応、ワクチンではない対応ということも考えられますね。その対応もぜひご検討いただけるように、盛り込んでおいていただけるとありがたいかなというところで、要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"やはり事業所も大分、それで要望に近いかもしれないのですけれども、私の管理者をしているデイサービスで職員がコロナ感染しました。恐らく今回のアンケートの中でそういった声があったのかどうか分からないのですけれど、去年の１２月に、臨時休業したのです。","respondent":"菅野高齢者福祉課長","answer":"まずは国の方針といったものにのっとって区のほうも対応してきたという経過もありますので、その辺りのところ、認識しておきたいとは思っております。予防の部分での支援などもさせていただいた経緯もありますので、いろいろ…","id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"確認","question":"そういったものを広く周知していただけると、いろいろな福祉事業所、介護事業所は心強いかなというふうには思います。これは少し確認なのですけれども、この第５波のとき含めて、もし分かるのであれば教えていただけますか。","respondent":"菅野高齢者福祉課長","answer":"例えば入所施設などは東京都のほうで週に１回、施設で多分週１回検査やっているというふうに、今年度中続いているとも聞いております。対応は何らかの形でいろいろと、どこかでそういう対応は取られたのかなと思うのですが、もう１回確認をさせてもらいますけれども。","id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"意見","question":"それが継続されているのかどうか、３０人ぐらい椅子並べてやっていたので、すみません。もし何かあればとの意見を述べました。","respondent":"阿部品川区保健所長、舩木生活衛生課長","answer":"時期と状況を考えますと、何とかその検査の場を捻出して検査を実施させていただいたというようなことではなかったかというように推測しております。都と区のほうで施設に対しては、必要に応じた検査ができるよう… 令和２年の５月から開設したものなのですが、そこに来られない方、その出張検査の一環としてやった可能性があるのかなというふうに推察いたします。区としては、そういう対応を取っております。","id":"exchange-064"},{"speaker":"やなぎさわ委員","kind":"意見","question":"資料編の８８ページのアンケートのところに、アンケートの中で「区議が色々な事業を手柄にしようと茶々入れてきたのを抑えてほしかった。感想で終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"おぎの委員","kind":"質問・要望","question":"そういった部分は東京都に働きかけて、一緒に意見を出して、ぜひ進めていっていただきたいと思っています。最後に１つだけ、アルコールや衛生用品の備蓄に関しては今、区のほうではどれぐらい持たれているのか尋ねました。","respondent":"舩木生活衛生課長","answer":"国とか東京都の方針に基づいて、地域にある資源の中でどういうふうに国や都からの方針を受け、そういったところも含めて対応していきたいというふうに考えております。","id":"exchange-066"}]},{"id":"topic-05","title":"令和５年陳情第５１号、心身障害者福祉会館の不適合箇所の早急な是正を求める陳情","agenda":"令和５年陳情第５１号、心身障害者福祉会館の不適合箇所の早急な是正を求める陳情","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"大きく２つの要望があるなと思いまして、指摘している不適合箇所の早急な是正を求めるという部分と、ほかの指摘箇所で改修工事の予定というのはないのか尋ねました。","respondent":"小林施設整備課長","answer":"所管のほうと調整しておりまして、今回、指摘上がっている中では、ガラスの改修工事、これにつきましては、今年度中に行う予定での計画を進めております。","id":"exchange-067"},{"speaker":"おぎの委員","kind":"質問","question":"できることからということですので、進めていっていただければとは思いますが、今回、能登半島の地震を見ましても、急に災害は起こるものですので、地震等の面で、今の状態で完全に避難ができる状態ではあるのか尋ねました。","respondent":"松山障害者支援課長","answer":"震度６から７の規模の地震に対するＩｓ値の評価につきましては０.６以上で、０.６以上あれば倒壊または崩壊する危険性が低いとされております。本施設のＩｓ値は０.９７というところで、耐震化というのは今回の指摘事項には上がってきておりません。","id":"exchange-068"},{"speaker":"おぎの委員","kind":"質問","question":"これは実際、そういった前回の本会議での発言の、自民党の発言された区議の意見なのでしょうか。それとも、品川区としても全く同じ見解ということか尋ねました。","respondent":"松山障害者支援課長","answer":"用地取得以外にも、既存の用地を活用するなど用地の確保の手法は、ほかにもあります。手法が用地の取得に限定されるものではないということで、区としては受け止めております。","id":"exchange-069"},{"speaker":"おぎの委員","kind":"質問","question":"そうしますと、用地確保と用地取得と、別のものであって、こちらは用地取得と書いてあるから逆に限定しているということなのか尋ねました。","respondent":"松山障害者支援課長","answer":"区といたしましては、そのようにおっしゃられたように受け止めております。必ずしも手法が取得だけに限定されるものではないということで受け止めております。","id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問","question":"２、３……９か所ぐらい、その点を伺いたい。それと、あともう一つ、前回９月のときに、この同じような陳情出されたではないか尋ねました。","respondent":"小林施設整備課長、松山障害者支援課長","answer":"２つの質問のうちの、前段のひび割れについては私のほうからご説明いたします。構造体に対する支障があるひび割れというふうには考えてございませんので、ひび割れの状況を判断した上で必要な対策を取っていくという考え方です。 結論を先に申し上げますと、まだ検討中ですので、特に何か具体的なものというのはございません。方法の一つとして、それが可能なのかどうかというような事前相談をさせていただいただけなので、必ずしも決定しているものではございませ…","id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ここの施設は、老朽化していて建て替えるというふうな方向というのは区としても出されているということなので、それはぜひもっと積極的に前に進めていただきたいということでお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"ひがし委員","kind":"質問・要望","question":"すごく大切なのでここ確認させていただきたいのですけれど、しっかりと品川区で修繕に向けて取り組んでくださるという理解でいいでしょうか。もう１点が、そこについて、具体的なところでエレベーターはざっくりでまとめないで教えていただければなというふうに思います。","respondent":"松山障害者支援課長、小林施設整備課長","answer":"区としても課題として認識しておりますので、できるところから改善を進めるという方針は変わりませんので、修繕はしてまいります。細かなところの詳細につきましては、施設整備課長からお答えします。 それにつきましては、様々運営上の課題があるというふうには聞いております。資料１の２ページ目になりますが、その次の３ページ目になりますが、調整を進めているところです。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"質問","question":"今２点、区画不成立のところと遮煙性能のところ聞かせていただきましたが、逆に出てこなかった、この戸開走行保護装置のところについては、現状だと難しいという判断なのか尋ねました。","respondent":"小林施設整備課長","answer":"先ほど申し上げましたとおり、全ての既存の不適格を解消するためには全てのエレベーターを新しいものに交換しなければなりません。この部分につきましては、今回の来年度、今予定している工事の中では対応が難しいというふうに考えてあります。","id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問","question":"現在お話ししていただいたところは、火災のところについては対応がしっかりできるのだなというふうに認識しております。予算のところについても、もし分かる範囲であれば教えていただければと思うのですが、いかがか尋ねました。","respondent":"小林施設整備課長","answer":"当然ながら、土曜日、日曜日については工事を休みますので、およそ２か月から３か月程度はエレベーターが使えない状況になるかなと思います。これらエレベーターにつきましてはオーダーメイド的なところもありますので、一概には幾らということはすぐに即答することはできません。","id":"exchange-075"},{"speaker":"ひがし委員","kind":"質問・要望","question":"何かしら計画を進めていっていただきたいなというふうに思いますので、その点については要望とします。何かありましたら。","respondent":"松山障害者支援課長","answer":"震災のときの避難経路なのですけれども、エレベーターというのはあまり想定がなくて、２階からちょうど階段の裏に配管の横を通っての横のスロープがありますので、そちらを使って外に避難するという形を今、想定しております。","id":"exchange-076"},{"speaker":"ひがし委員","kind":"意見","question":"そのときにというところで多分、法令が変わったのではないかなというふうに私も期待しているので、そこについての対応というところで考えていただければいいかなというふうに思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"筒井委員","kind":"確認","question":"確認で、先ほどご答弁あったかもしれないのですけれど、耐震性自体は問題ないということでよろしいか尋ねました。","respondent":"小林施設整備課長","answer":"先ほど所管課長からお話がありました、建物の耐震性でございまして、当然ながら、先ほど答弁したとおり、耐震制能につきましては関係法令に基づいて確保されたものです。","id":"exchange-078"},{"speaker":"こしば副委員長","kind":"質問","question":"エレベーターの戸開走行保護装置の設置だとか、そういったところもありましたけれども、やはりこのエレベーター自体の改修工事に約２か月間要すると。この２か月の期間によって多くのサービスの利用者にとって不利益を被るおそれがあるということもありまして、取組に期待をしていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問","question":"本日結論を出すでお願いしたいと思います。他の委員の質問で、この陳情については添い難いといったところで、結論を出します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ただ、現在の利用者様の利便性というところはもちろんなのですけれども、一番大切なのは安全の部分だと考えています。一刻も早く、災害が起こったときに安全が確保できるような整備を進めていただくように、そちらについては求めします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうことで言えば、この陳情者もずっと求めていますけれど、身障者会館を早くに改築をしていただきたいと。そういうところを早くに探して、そして具体的に積極的にそれを前に進めていただきたいという思いを込めまして、採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-082"},{"speaker":"筒井委員","kind":"質問・要望","question":"建物自体の耐震性も問題ないということから、不採択でお願いします。なるべくその既存不適格の箇所は早期に是正していっていただきたいということと、将来的な改築をぜひ早期に進めていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"おぎの委員","kind":"質問・要望","question":"既存不適格の部分もできるところから、真剣に予定してやっていただけるということですので、そちらのほうはぜひ進めてほしいと求めました。建て替えに関しても併せて真剣に取り組んでほしいと求めましたので、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"お話伺っていて、予算の要望をしているなど、区として進んでいるということを非常に感じているような雰囲気が出ていると思います。やはり能登半島の地震もありましたし、というところで、区の取組は十分評価しつつも、それを進めるという意味で、採択ということにします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"結構、障害者団体の皆さんから、こういう形で仕事がつくり出せるよというふうなところをやってほしいというような要望は受けていまして。これもずっと要望が上げられていて、就労でも使えるようにしてほしいということは、その３点伺いたいと思います。","respondent":"松山障害者支援課長","answer":"それから、同行援護のサービスにつきましては、詳細につきましては、ただいま検討しています。何とか可能な限りお応えができるような形で検討しています。","id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問・要望","question":"仕事をつくり出す、そういう視点で取り組んでいただくようにということで働きかけていただきたいということで、要望させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"ひがし委員","kind":"確認","question":"幾つか確認させてください。１か月から２か月ぐらいかかるというような話を聞いたのですが、ここのところの短縮とかで何か方法はないのかなと思うのですが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"令和４年度については７１％ということで、就労定着支援事業所の就労定着率の７割以上の割合というのは、まだ記載がされていないものになります。就労移行支援事業所とかで、やはりご利用いただきたいので、できるだけ早く受給者証の発行に努めているところです。","id":"exchange-088"},{"speaker":"ひがし委員","kind":"確認","question":"活動、やはり手順をしっかり踏まなければいけないというところで、その期間かかってしまうのはしようがないなというふうに思うのです。手続にかかるのは１か月だけれども、また、もしできないとしたらどういう課題があるのか教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"委員おっしゃる課題についてです。地域自立支援協議会等で就労支援部会というのがございまして、就労関係の事業所は集まって、こちらのほうで現実的に。","id":"exchange-089"},{"speaker":"ひがし委員","kind":"質問・要望","question":"利用したいと思ってすぐに始められるというようなところで、移行支援のところに利点も多いかなと思いますので、ぜひそこは前向きに検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-090"},{"speaker":"こんの委員","kind":"質問","question":"例えば就労継続支援Ｂのところで先ほども質問がありましたが、去年ですか、教えていただけますか尋ねました。","respondent":"松山障害者支援課長","answer":"就労移行支援事業所では実は、テレワークに対する訓練というのをオンラインで実施しているところも、非常に前向きに考えております。私たちも企業に実は出向いて、超短時間雇用の説明ですとか事業周知というのに、今まさに取り組んでいるところです。","id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"ほかにもこういった協力を得られるところはないのでしょうかと、そんなところはどんなふうに考えていらっしゃるのかといったところ。今度新庁舎を建てたときに、その中に障害者の方のそうしたショップなども考えられると思うのですが、その辺はどんなふうにお考えか尋ねました。","respondent":"松山障害者支援課長","answer":"臨海斎場ですと限定されてしまいますので、どこかほかのスペースがあればということで、今後検討していきたいと考えております。２点目の障害者の方の就労、今、新庁舎整備のほうもいろいろ検討を進めているところです。","id":"exchange-092"},{"speaker":"こんの委員","kind":"意見","question":"新庁舎のところでは、そのように進めてくださっているということですので、ぜひお願いしたいというふうに思います。何かございましたらとの意見を述べました。","respondent":"松山障害者支援課長","answer":"なかなか就労支援部会の中でも、販売ができるようなスペースがあるかどうか、そこを一緒にみんなで探していきたいと考えています。","id":"exchange-093"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"募集等はもう始まっていらっしゃるのでしょうか。今後のこういった対象になる方の流れ等を教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"今お尋ねの、募集の受付期間です。１月１７日から２月２９日までということになっておりまして、２月２９日の５時までに区役所に必着ということになっております。","id":"exchange-094"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814344?Template=document&Id=3682#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":80866,"voices":247}},{"id":"r06-20240122-8","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"建設委員会","time":"午後 １時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件整理しています。","topics":[{"id":"topic-01","title":"の順番を入れ替えまして、(3)令和６年２月都営住宅入居者募集","agenda":"の順番を入れ替えまして、(3)令和６年２月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"区営住宅のときにも求めましたけれども、いかがでしょうかということと、事業用が２４戸ということです。小規模の都営住宅が何戸か区に移管されてきたと思うのですけれども、そういったものはまだ残されているのかというところを伺いたいと思います。","respondent":"竹田住宅課長","answer":"倍率ですが、前回、令和５年１１月の平均の倍率が１９.７倍、それから前年の同時期の２月の募集が１９.０倍となっています。東京都から毎年同じ時期に意向の調査がありますけれども、移管の条件が非常に厳しい内容となっていますので、今のところ実現できていないところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ですので、そこはぜひ改善をしてほしいと求めましたが、いかがでしょうか。空き室の公表については、区営住宅のほうになってしまうのですけれども、区営住宅の空き室も公表したらどうかと思うのですが、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"それから、東京都から示されているのは、１棟当たり室数が１００戸以下のものを小規模ということで調査が来ております。様々な理由がありますので、区営住宅をご提供できる可能数を提示することによって、ご理解いただきたいと考えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは要望しておきたいと思います。やはり実績として倍率が高いというところで、これを減らさず、むしろ増やしていくということで進めていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"}]},{"id":"topic-02","title":"戸越６丁目地区における地区計画の変更","agenda":"戸越６丁目地区における地区計画の変更","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、先ほど、意見書での意見についてはご説明があったのですけれども、説明会では、どういった質疑や意見などがあったのかを伺いたいと思います。それと、現在の道路幅員が４.５ｍから８ｍということだと思うのですが、６ｍ以下になっている箇所はどこになるのか伺います。","respondent":"小川木密整備推進課長","answer":"防災まちづくりを検討していくという趣旨で、検討会から、より具体的な地区計画の案等を検討してきているところです。令和３年度には、これを受けて、地区計画を現在検討して導入を進めていこうと考えているところです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"拡大する経緯について、東地区でどういう効果があってなったとか、そういったことは特にないということなのかというところを伺えたらと思います。要望です。","respondent":"小川木密整備推進課長","answer":"この六丁目の西の場所だけというふうになっておりますので、そういった同じようなまちづくりをしていくといった意味でも、この東地区の地区計画を拡大してまちづくりを進めていきたいといったところで今回行うものです。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"戸越公園周辺の開発を今やっているところもあるので、その辺のご意見をお聞きしたいということと、防災生活道路の説明はきちんとしてほしいのです。そういうふうに受けたところがあるので、そこは丁寧にご説明ほしいと求めましたが、いかがか尋ねました。","respondent":"小川木密整備推進課長","answer":"２点目の分かりづらい、再開発等に関係する所管の都市開発課と連携して、ご説明ができるような機会をつくっていきたいというふうに考えてあります。防災生活道路に関する説明ですが、この間の西大井地区での説明会でもそうでしたが…","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"商店街がどうなるのか、品川区は多くなっているのですけれども、買物するときにどういうふうに不都合が出てくるのか。何かそういう利便性がよくなるのねという思いがあるのであれば、そちらも教えてあげたらいいのかなというふうに思いますが、いかがか尋ねました。","respondent":"小川木密整備推進課長","answer":"我々も年に２回、そういったものと合わせながら、取組状況についても周知していきたいと考えています。先ほど申しましたニュース等の中でもお伝えをして、広く周知をしていきたいと考えています。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"同じく防災生活道路に関連してお伺いしたいのですが、６ｍ以内のところは、この道路がどういう位置づけになってしまうのか。それまでの過程で、先にこれを迂回するようなルートでの道路設定にすることの関係性、どちらを優先するのかというところのご認識をお伺いしたいと。","respondent":"小川木密整備推進課長","answer":"２号、３号につきましては、真っすぐ通したいといったところで取組を行っていきたいというふうに考えてあります。関係性としましては、高架化に合わせて、まずは線形を整えていきたいといったところです。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"この部分も直線で線を引くということは、現状は難しいというか、できない。今の既存のルートの中においての拡幅を先に指定せざるを得ないということが現状なのか尋ねました。","respondent":"小川木密整備推進課長","answer":"現段階では、既存の道路を防災生活道路として指定するといったところですので、今の現状での線形で指定をさせていただいているといったところです。道路・交通管理者のほうに訴えて、線形の整備に当たっていきたいと考えています。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"ほとんどが６ｍ以上の区間なので、６ｍ未満のところだけを指定すればという考えもあるのかもしれないのですが、そこも含めて理解をします。そういった関連側道も６ｍにする必要があるのかどうかということもあるのですけれども、そこも１つ、お聞かせほしいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"説明会でもご説明しているのですけれども、６ｍを予定しておりまして、車が通れないような規制をかける予定にしております。どのようなしつらえになっていくかは今後の警察や関係機関との協議によるところではありますが、今のところはそういった予定で進めているところです。","id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"歩行者・自転車専用道路になると、防災生活道路の指定にはそぐわないというか、当たらないというところでしょうか。そこだけ確認をお願いします。","respondent":"大石まちづくり立体化担当課長","answer":"防災生活道路としては、基本的には位置づけは予定しておりません。アクセス、歩いて広域避難場所の戸越公園のほうに避難できるような形で、関連側道の部分の６ｍをしっかり活用していきたいと考えております。","id":"exchange-011"},{"speaker":"田中委員","kind":"意見","question":"関連側道も将来的には防災性向上の１つの大きな役割を果たしてくるだろうと思えるので、より理解が深まるのではないかと思いますので、ぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"}]},{"id":"topic-03","title":"ごみ分別アプリの導入","agenda":"ごみ分別アプリの導入","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"これからの展開の段階を伺えればと思います。アプリのダウンロード数だとか、数値目標があれば、併せてお知らせください。","respondent":"品川品川区清掃事務所長","answer":"こういったものでアプリの周知は進めていこうかと考えております。大体他区の導入率を見ると、１０％にいっていればかなり上出来なほうなので、まずは１０％ぐらいを目標にやっていきたいと考えております。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"意見","question":"これがやはり３か年計画だとかを立てて、そして、やはりそこでごみの分別の大事さを普及啓発するにはコストがかかっていいと思うのです。それもひっくるめて、来年度すぐというわけではないですが、今後やはり中長期的に考えた抱負を最後に説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"ただ、少しでも、いろいろな方法で周知できるようにということは考えております。いろいろエコルとごしなどとも連携しまして、そういったところで環境面全体として周知の方法を考えていきたいと考えています。","id":"exchange-014"},{"speaker":"西本委員","kind":"提案","question":"今の渡辺委員の提案、なかなかそこを越えられないとかということなのか、少しそこを教えてください。その違いなども、ここは分かるのかなとか、その辺を説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"独自でこのパッケージ商品を購入しているというような契機もありまして、変更については、ある程度は柔軟にできるかなというふうに思っております。自分のところの集積所とか、それから収集日とか…","id":"exchange-015"},{"speaker":"西本委員","kind":"意見","question":"もう１つ、いろいろご意見を聞くことは悪いことではないかなと思うのですが、その辺の対応はどうお考えになっていますかとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"現在のところは、情報を出す、発信するだけの機能になっていますので、収集する機能のほうについては、少し研究させていただきたいと考えています。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"それがあると、非常に意識も高まってくるし、活用しようではないかという思いもあるかと思うのです。情報発信ということであれば、やはりこういう問題がありました、どうぞこれから研究を深めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"まず１つは、ありとあらゆる資源を活用していただいて、徹底していただけるようにご努力いただけたらと思います。ぜひお願いしたいと思いますが、その辺も含め、ご意見をお聞かせいただきたいです。","respondent":"品川品川区清掃事務所長","answer":"対応が物すごい量になってしまったりとか、そういう例なども聞いたりしますので、その辺は少し慎重に進めていきたいと思います。対応力としてどうなのかとか、その辺もいろいろ考えながら、今後また研究していきたいと考えています。","id":"exchange-018"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"やはり見てくれているというか、ああいうのは本当にとてもすばらしい機能だと思っているので、そういうものは進めていただきたいと考えています。質問としては、そういうものも入っているのか、そこだけ確認させてください。","respondent":"品川品川区清掃事務所長","answer":"外国語対応が今はできていない状況ではありますので、〔同日後刻に「多言語対応をある程度やっている」と答弁訂正あり〕当然こういうものですから、外国語対応していくような形で進めていくべきですので。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"私も今のまつざわ副委員長の外国語対応、そこが一番聞きたくて、この事業の目的が、収集日とか、分別をしっかりやっていただきたいと。逆に言うと、こういうことはいろいろな声で、守りづらい方、守る環境がなかなかない方は、どのような方々なのか、まずお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"お仕事をずっとしていて、なかなか分別が困難な方とか、そういう方にも情報として知ってもらえると非常にいいかなと思います。こういう方については、アプリというのは非常に有効的ではないかなと考えております。","id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"そこが最初から対応できないということが分かれば、では、どうやって対応するか。粗大ごみはどういう形になるのかということと、せっかくのアプリなので、可能性があるのであれば取り組んでいただきたいです。","respondent":"品川品川区清掃事務所長","answer":"何かあるときには、そのパンフレットを持っていって身振り手振りで説明をしながら理解をしてもらうということが現状の対応なのですけれども。ただ、こちらのアプリで外国語対応というのは非常に重要なところでありますので…","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどご説明いただいた２６ページの言葉の関係性、まず見方が、これはどう見たらいいのかというところを伺いたいと思います。いかがでしょうかということと、いかがでしょうかということと、そこの区としての受け止めを伺いたいと思います。","respondent":"河西情報戦略担当課長、鈴木都市計画課長","answer":"区民の皆さんがどのように感じているのかを参考にしていただくための資料とご認識ください。ことばネットワークに関しては、参考にご提示させていただいたということでお答えします。 本日は概要版でのご説明ということで、本日お示ししながら概要版でご説明というところが一番よかったのかなですが、鋭意取り組んでいるところです。回答はいくつでもということで、やはり一番回答として多かったのが…","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"４４.５％いらっしゃるということは、私は重大な影響が出ていると思っているのですけれども、区の受け止めを伺いたいと思います。そうした結果を見ると、やはりこの羽田新ルートについて中止をすることが、結果を見ても一番ではないかなと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"ご説明いただいたように、４人に１人の方にお答えいただきまして、影響を受けているという回答。今、固定化回避検討会が鋭意進められているわけですが、当日の面談の中でも強く大臣のほうに区長から直接申入れをさせていただいたところです。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"約８万７,０００人もの方が答えていただいたということで、これまでこうしたアンケートは、区として行ってきたのかどうか伺いたいと思います。影響を受けている区民のより生々しい声が示されていると思いますが、これを受けて、何を要望するのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"羽田新飛行ルート運用開始前、あるいは運用開始後、こうした区としてのアンケートをこれまでに行ったことはございません。大臣に直接、要望書あるいは口頭で強く申入れをさせていただいたというところが、一番区としての姿勢をまずは示させていただいたです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、集計データをまとめて届けるということで、そのときにも恐らく何か要望するのかなと思うのですが、何を要望するのか、改めて伺います。","respondent":"鈴木都市計画課長","answer":"あるいは、中身によっては誹謗中傷みたいなところも、公開には適当でないところの最終精査を行っているところです。先ほど、このアンケートの目的の１つである区民負担の軽減につながる取組を国にしっかりお伝えする内容にしていきたいというふうに考えてあります。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"この集計データ、オープンデータと同じ中身がアップされるという考えでいいのかどうか、そこのところを確認させてほしいと求めました。この意見を区としては読んだのかどうか、都市計画課長も、自由意見を読んだかどうかということを聞かせていただきたい。","respondent":"河西情報戦略担当課長、鈴木都市計画課長","answer":"全ての回答いただいたデータ。ただし、個人を特定するようなデータは、黒塗りないしは削除させていただいたものを公開する予定です。 併せて、空港環境担当係長、係員が２名おりますが、そちらの職員の中でも目を通させていただいたです。アンケートの１つ１つの自由意見の結果については、区長にもお渡ししています。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"自由意見欄を読んだということですので、ぜひ課長の読んだ感想というか、受け止めを伺いたいと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"非常に膨大な数の意見を１つ１つ読んでいくというところで、結果で先ほどもご説明させていただきましたが、感想としてはそういうふうに感じたところです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"騒音の影響が大きいということで、そのためには、羽田新ルートは中止すべきだというふうに私は述べておきたいと思います。それはどういった対応を区としてされたのか伺いたいのと、直接申出があったわけですから、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"これはアンケート結果のことについてなので、ぜひ区民に説明してほしいということなのです。そうしたことをお願いしているのですが、ご答弁いただけるか尋ねました。","respondent":"鈴木都市計画課長","answer":"低く飛んでいるところ、音ですとか、そうしたところはしっかりとお示しさせていただいているところです。しっかり区のホームページ、あるいは東京都のホームページにも掲載して、しっかり広く公表していきたいです。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"直接申出があったわけですから、ぜひそうしたところも含めて説明をしていただきたいというふうに要望しておきたいと思います。も、ぜひ羽田新ルートはやめてほしいということで要望してほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"今、自由意見欄を含む最終的な取りまとめを行っている中で、国のほうに改めて直接届けるために、今、準備を進めているところですが、先ほどご答弁したとおり、区民負担軽減につながる取組を、全体版をお渡ししていく中でも、しっかり国のほうに求めていきたいです。","id":"exchange-030"},{"speaker":"西本委員","kind":"意見","question":"目的があって、何のためにこれをやったのか。その目的に対してゴールがあるのだろうと思うのですが、まずそこを説明を求めました。","respondent":"鈴木都市計画課長","answer":"区としては議会等でご説明していますが、目指すべきところということでスタートし、今回その方向で進めているところです。","id":"exchange-031"},{"speaker":"西本委員","kind":"確認","question":"これ、どうするのですか、このアンケートの結果。これからどう料理するのか尋ねました。","respondent":"鈴木都市計画課長","answer":"１２月１日に、国のほうにしっかり負担軽減につながる取組を行っていただきたいというところで、国にしっかり申入れをしたところです。これから全体をお持ちするところにおつけする文書についてもしっかり検討して、国のほうには改めてしっかり要望していきたいです。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問・要望","question":"でも、国交省の見解はどうなのでしょうか。そこを確認したのか尋ねました。","respondent":"鈴木都市計画課長","answer":"第１回の中でも、区民の影響の軽減に向けた取組を固定化回避検討会の中で一刻も早く示していただいて、具体的に実施していただきたいというところが。その中でも９割の方が「騒音」というところを回答いただいておりますし、集計の結果をして…","id":"exchange-033"},{"speaker":"西本委員","kind":"確認","question":"だから、それをずれていないような確認はいつやるのでしょうかということが１つ。どういう説明をするつもりなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"アンケートの結果を区長のほうからご説明をして、検討する」という回答、発言があったところです。正に建設委員会でこの概要版をご説明させていただいて、こちらは区民アンケートの全体、羽田も含めた全体版について説明をする予定になってあります。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"次、どうするのですかという話ではないですか。アンケートをやって、このアンケート結果を次にどう持っていくのか尋ねました。","respondent":"鈴木都市計画課長、河西情報戦略担当課長","answer":"１月３１日の記者会見では、羽田も含む概要版についての説明をするわけですけれども、改めて国のほうにしっかり直接届けていきたいです。やはり１つ１つ、先ほどご説明したように… こちらは何かといいますと、区民の方に回答いただいたアンケートの中で、量と質をまとめたものです。６７７件、回答いただいたアンケートのうち、この１４ページから見ていただければと思います。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"それが区民の方々に対して当たり前の報告ではないですか。せめてそこだけは示してもらいたいものだと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"その中で固定化回避の中で国がそうした検討会を立ち上げて、この固定化回避の中で検討し示していくというところは、あるいは申し入れていきたいです。選択肢と自由意見欄をセットで見ていただいて、しっかり区民の方にも公表…","id":"exchange-036"},{"speaker":"西本委員","kind":"確認","question":"補助金を出しますよとか、そういう話に持っていこうという話はないですよね、それを確認させてください。決してそれは区民の皆さんの総意ではないというふうに思っているので、そこは少し気をつけてほしいと思っていますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"当初１２の飛行方式の中から、２つの飛行方式に絞られて、それを改めて国のほうには強く申入れをしていきたいです。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"私もまだ１年たっていませんけれども、私は結論を出すべきとして言っていますが、継続審議にずっとなってしまっていました。やろうとしたときのきっかけを、皆様に区長から何かご指示なり、思いが伝えられたのか、そこが分かればお聞かせいただきたい。","respondent":"鈴木都市計画課長","answer":"区長が全区民アンケートを行いますですが、改めて区民にお聞きして、これは本会議の中でも区としてご答弁申し上げてきたところです。しかもルート下近傍について非常に顕著であったというところと、この軽減策を、１２月１日は直接訪問して強く申入れをしたです。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"政策としてどうあるべきかというものが一本筋が通った中で、それに対する考えがこうだからという、そういう観点の利用が本来あるべきかなと。品川区では、アンケート調査をしましたけれども、あるいは東京都としてアンケートをされているのかがもし分かれば教えてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"１つ１つの自由意見につきましても、そこからまたそれぞれの所管が、さらに継続した取組に活用していくというところになっていくのかなです。この港区の実施の仕方が、選択肢という形ではなくて、自由記述という形で回答いただいたということは聞いているところです。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"固定化回避を求めてアンケートをしたのでしょうけれども、伊丹もどうなのだとか、福岡は何とかしてくれないかとかということになると思うのです。区民負担軽減につながる取組を求めるということでありますが、見える見えないとかということをどうされようとしているのかが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"運用が開始されて、国の責任の下で実施されているものではありますが、さらなる安全対策ですとか。今正に固定化回避検討会の中で示していきますよと国は言っておりますので、今後もこのアンケートを基に強くしっかりと求めていきたいです。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"いけないと思いますし、これまでも、それ以上の成果を目指して再開発は進めてきたと思うのです。声は声としてしっかり承り、区長としての施策推進につなげていただきたいと考えていますので、これはぜひよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"様々な基準のところでこういったことはあまり聞いたことがないかなと思ったので伺いたいのと、この説明がどういうことなのかを伺いたいと思います。どういった手続というか、どうなっていくのか、不全になっている理由はどのようなことがあるのか伺います。","respondent":"竹田住宅課長","answer":"修繕積立金があるのか、あるいは、そういった計画が実施されているのか。修繕の計画的な実施が行われていないマンションが５２、それから同数で、修繕積立金を積み立てていないマンションが１６というような状況です。","id":"exchange-042"},{"speaker":"のだて委員","kind":"確認","question":"１つ、「ない」というところがあると思うのですけれども、あるかないかは恐らくどちらか必ずつくと思うのです。今、そういう説明になってしまっているのですが、そこはどういうことなのかというところの確認です。","respondent":"竹田住宅課長","answer":"その建物の維持管理をしていく上で重要な要素だと考えていますので、「ない」ということになれば、管理不全の兆候ありというふうに考えてあります。１つでも「ない」がつくと、管理不全です。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"７５棟が現在そうなっているということで、もう１つ必要なのかなと思うのですが、伺いたいと思います。居住支援事業のほうも伺いたいのですが、その登録件数、あるいは戸数が幾つになったのか伺いたいと思います。","respondent":"長尾建築課長、竹田住宅課長","answer":"マンションの耐震化支援に関わるご質問について、お答えいたします。区のほうでも、そういう使っていただける制度を併せてご案内しているところです。 それから、マンション管理士の派遣、相談等も定期的に開催しておりまして、様々なご相談に対応しています。今後、セーフティネット制度の家賃低廉化補助を通じて専用住宅を増やしていきたいと考えております。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"より使いやすく、要配慮者も住まいをしっかり見つけられるということになるのではないかと思うのですけれども、いかがでしょうか。それと併せて、ほかにも家賃補助をさらに広げていくということが私は必要だと思いますけれども、そこを併せて伺いたいと思います。","respondent":"竹田住宅課長","answer":"こちらは国のスキームですので、一自治体の判断で登録住宅も家賃を低廉化していくということは、なかなか難しいのかなというふうに考えてあります。それ以外の支援も広げてはというお話ですが、今後、検討していきたいと考えております。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"改めて答弁があれば伺いたいと思います。実際にあるかということは分からないのですけれども、仮に処分をしてしまった後に所有者が見つかった場合はどうなるのか伺いたいと思います。","respondent":"竹田住宅課長","answer":"そういったところで、まずは居住支援協議会にご参加いただいている不動産団体等のご協力を仰ぎながら家賃の低廉化制度が始まりましたので。ちょっと考えられないのですけれども、元所有者の方が見つかったとしても、効力は変わらないものだと考えています。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"１９倍という高倍率、以前の区営住宅のときには５０倍ということもあったと思うのですけれども、公営住宅の役割が求められていると思います。区としては区営住宅ということになると思いますが、ぜひ公営住宅の増設をすべきだと思うのですけれども、いかがか尋ねました。","respondent":"竹田住宅課長","answer":"２３区の状況をお話ししながらご説明したいのですが、今年度開始した区も含めまして、品川区を除いて８区あります。民間賃貸住宅を有効に活用しながら、活用できるセーフティネット制度を推し進めることによって支援を進めてまいりたいと考えております。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"７戸、６戸と、多くて一桁台。これは強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"その解釈の違いを教えてくださいということと、除却されたものが５４というのは、この９７の中の５４なのですか。それとも、不適正管理状態のものが９７足す５４という数値で見ればいいのか尋ねました。","respondent":"竹田住宅課長","answer":"何度も訪問して、対応策をご助言できるように支援していますので、こちらの７５を少しでも少なくしていきたいというふうに考えてあります。１０年後には必ず１０歳年をとるということで、本制度の課題として国も認識されておりまして、審議の経過を見守りたいと考えています。","id":"exchange-049"},{"speaker":"西本委員","kind":"質問・要望","question":"でも、この中で非常に危険度の高いところがどれぐらいあるのでしょうか。建て替えをしていただかなければいけないということだと思うのですけれども、それに対しては何か手だてはされているのか尋ねました。","respondent":"竹田住宅課長","answer":"そのうち１件は、昨年１２月でしたか、無事解体されて売却されました。最後の代執行という手段もありますので、そういったものも視野に入れながら、所有者の方とは粘り強く対応していきたいと考えております。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"その中に１人でも、そういう方を増やしていくという行動はぜひお願いしたいと思うのですけれども、周りも非常に心配だと思うのです。もう少し広く考えていただいて、いろいろな力を借りて説得をしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"その辺のご認識をお伺いしたいのと、併せて伺うと、セーフティネットは住宅を求めていて。そういう取組につながると思うのですけれども、そういったことも含め、今後の住宅政策の取組についてのお考えをお聞かせほしいと求めました。","respondent":"竹田住宅課長","answer":"最低７年に一度は計画を見直してくださいというところで、計画の内容を見直せば、修繕積立金の見直しも行わなければならない。今後も空き家の様々な活用について、支援、働きかけをしていきたいと考えております。","id":"exchange-052"},{"speaker":"若林委員","kind":"質問・要望","question":"2)をクリアしているわけですけれども、1)のほうで、この５件については確認をさせてほしいと求めました。１年でも早く立ち上げていただきたいということで、もっと品川区に頑張ってほしいとかという、お聞きしておきたいと思います。","respondent":"竹田住宅課長","answer":"東京都で支援法人を指定していますので、次回の居住支援協議会では、入居後の支援ということもご意見をいただこうと思っています。居住支援のお立場から、それぞれのお立場から入居後の支援のご意見をいただいて、今後の施策の参考にしていきたいと考えております。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問","question":"２番の居住支援（セーフティネット）のほうですが、どういう独自なのか、教えてください。〔「次の機会に」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"１月２日に発生した日本航空機と海上保安庁機の衝突事故について、少し伺いたいのですけれども、ありがとうあります。事故の原因について伺いたいのですけれども、この事故との因果関係について、報告を受けていることがあれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"運輸安全委員会で調査が進められていくところですが、１月９日に、そうした説明も受けております。有識者を入れた航空機衝突事故対策検討委員会、これは１９日に開かれておりますが、共有をさせていただいて説明を受けたところです。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、原因については、まだあまり説明を受けていないということですか。今、この原因が分かるまでは便数を減らして運行するということが必要ではないかなというふうに思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"今ご説明しました１月９日、ご説明を少し簡略化しますが、それからパイロットによる外部監視の徹底視覚支援。国としても対策検討委員会を立ち上げて、しっかり検討していきたいという中で、国が立ち上げた対策検討委員会については。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/463917?Template=document&Id=4398#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":65129,"voices":149}},{"id":"r06-20240122-9","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"文教委員会","time":"午後 １時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件整理しています。","topics":[{"id":"topic-01","title":"令和５年陳情第５２号、品川区の学校を子どもの安全に最大の配慮を行う「安全・安心で、楽しい学校」にするための陳情","agenda":"令和５年陳情第５２号、品川区の学校を子どもの安全に最大の配慮を行う「安全・安心で、楽しい学校」にするための陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"質疑を深めるためにも、質疑の前にぜひ意見陳述を受けて質疑をしていただきたいと要望いたします。皆様、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最初に、質疑から始めていただきたいと思っています。その後は、委員長のご判断で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"それだけで１時間やっていますということなのか、それが見えないのでお伺いしたいのが、項目１についての質問がまず１点です。担任の方が３０人から４０人の子どもを一人で指導するというのは本当にかなり大変な仕事だと思うのですが、それと、実態はどうなのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"２週間に１回ですとか、月に１回ですとか、そういったものは各校で設定して開かれております。は企画会議、職員連絡会に持ち込まれるという形で、それぞれの下部組織の中でそれぞれの教員が意見を出し合っているという現状です。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"提要が出された後に校則がどう変わったかという、私が伺ったのは、発出されてどうなったのですかというところなのです。指導援助というのですかね、このように持ってくださいみたいな、そういうのはないのですかというのを伺います。","respondent":"丸谷教育総合支援センター長","answer":"令和５年４月の段階では、現状、各校のホームページでも広く保護者や区民に向けての周知がされております。限られた時間の中で効率的に情報共有を行い、教員がそれぞれその中で活動できるような、そういった連絡会というものを開いているという状況です。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"１００％なのでしょうかということとか、４月からと考えても、何％ぐらいの学校がそういうのに携わったということを把握しておられますでしょうか。伺います。","respondent":"丸谷教育総合支援センター長","answer":"例えば、髪型についてはこういう表現に改めましたといったような変更点については、こちらでも把握に努めているところです。ホームページの公開内容についてですが、子どもたちに示しているものについては１００％公開をしているものです。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは絶対必要だと思うのですけれども、それを求めたいのですが、いかがでしょうか。どのように評価していて、今後区内の小・中学校の運営にどう活かしていくというお考えなのかというのを、改めてそちらも伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"教員向けの研修につきましては、国や都の動向も注視しながら、区として教員に適切に対応していきたいと考えております。全ての内容を限られた時間で説明することは難しいとは思いますけれども、機会を捉えながら、生徒指導提要のここの部分にこのように書いてあるので。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、これは時代の流れもありますし、国の方針も変わっているわけですから、ここは重要視して、軽視しないでいただきたいと私は思います。そして、どれぐらい拡大していくつもりなのかというのを伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"不登校の児童・生徒への教育の機会の確保、今後どうしていくかというところで、一つは校内別室指導支援員の拡充ということを考えております。予算のことも絡んでくる内容ですので、少なくとも今現状１校ですけれども、これを複数校…","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここについては最後の質問ですけれども、年に１回の校則の見直しの、システム化というのでしょうか。ですから、そこについても求めていきたいと思うのですが、それについての見解も最後にお伺いしまして。","respondent":"丸谷教育総合支援センター長","answer":"不登校のお子さんの民間施設を使ったときの支援についてですけれども、現在、東京都の事業で月２万円という形での支援がされております。こうした案内をしっかりと対象の児童・生徒のご家庭に届けることがまず大事だと考えております。","id":"exchange-008"},{"speaker":"吉田副委員長","kind":"質問","question":"いいことという言い方はどうでしょうか、生徒指導提要を先生たちがお互いに学び合うような機会というのをどれくらい持たれているのか。先生への教育という言い方がいいのかどうか分かりませんけれども、どれくらいされているのか、まず伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"各校には既に周知をされておりまして、校則の見直しの機会にその部分について書かれていることを説明しているところです。教育総合支援センターが受け持っておりますので、理解を深めていけるように、区教委としてはそういうところを努めていきたいと考えております。","id":"exchange-009"},{"speaker":"吉田副委員長","kind":"提案","question":"実態として、例えば、何年次研修のときには必ずその中身をきちんとみんなで共有しているというところまでは把握していないということなのでしょうか。校長会とか、そういうところであるのかないのか、その辺についても伺いたいと思いますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"いじめの相談ですとか不登校対応、そこに書かれていることを十分読んで活用するというような働きかけ、使い方というのはしています。そういったものを知っていただくものということが目的だと考えておりますので、各校の校則を並べて、そういったものは現在していないです。","id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"別の方法も検討していただきたいと思うのですけれども、低学年に向けてとか、どのように数を増やしていくのかということを検討されているのか。それから、マイスクールは、最終的にはやはり学校に戻すことを前提としておられるのか、その辺についても見解を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"マイスクールの今後の検討というところですけれども、４つ目のマイスクールができますが、必要なエリアに設置ができればと考えております。マイスクールに継続して通うお子さん、様々おりますので、一人一人に合わせて対応を進めているところです。","id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問","question":"分かりました。結構、品川区としてのそういうフリースクールに通われるお子さんたちへの支援というのを検討されているのか、その辺を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"フリースクール等に通われている児童・生徒への支援ということですけれども、今後の東京都の動きですとか保護者のニーズ等々、十分にこちらで把握をした上で検討していきたいと考えております。","id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"こういった品川の子どもたちの環境を心配して、陳情まで出され、そして、意見を陳述したいという積極的な区民の皆さんの議会への参加、歓迎すべきだと思いますし、ぜひ審議を深める意味でも、私はこの場で陳述を受けたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"意見","question":"意見陳述なのですけれども、この場では行わないということでお願いいたします。それを踏まえて質疑をしている場でありますので、そういう観点から、行わないということでお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり直接区民の皆さんからの意見を伺うという、私は納得いかないので、ぜひ皆さんにも意見陳述を受けることに賛同していただきたいという思いを改めて表明します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"議員から物すごく意地悪な質問が飛んでまいりますので。その制度は活用されるべきであると思いますので、ぜひ意見陳述をしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"理由は、先ほどこの陳情項目４つに関してセンター長からご説明あったとおりだと私は思っております。４番目の不登校児童生徒のマイスクールというのは、必要なエリアに応じてぜひ設置をしていただきたいということで、これは要望として述べします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"確認","question":"本日結論を出すで、態度は不採択でお願いします。品川区として、各項目について既に取組を進められているということを確認できましたし、今後とも対策を進めていくという姿勢も確認できましたので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"吉田副委員長","kind":"確認","question":"それぞれ陳情項目につきましては、今取り組まれている施策について確認をいたしました。会派の中で議論したところ、進んでいる施策について確認をしていこうということになりましたので、会派としての不採択を主張いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"それを踏まえて必要な対策を求めるものであり、私はこれを採択して、さらに安全・安心で楽しい学校にするために採択したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今進めていることが、しっかりと進めていただいているのですけれども、さらにここから発揮して進めていっていただきたいという気持ちが私はあります。ですから、かゆいところに手が届く、細かいところをしっかりとやっていっていただきたいという要望はします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"石田（し）委員","kind":"確認","question":"各陳情項目についてはそれぞれ対応されている、また、これからもしっかりと対応していくということは確認をいたしました。しかし、変えるべきところというのは変えていくという姿勢はしっかり持って、これからも取り組んでいただければと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]},{"id":"topic-02","title":"令和６年度新入学 学校選択の抽選結果","agenda":"令和６年度新入学 学校選択の抽選結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"前期、後期共に、抽選する割合と、あと、応募する方も減っていると思うのですが、この原因というのはどのように分析しているのか、説明を求めました。","respondent":"柏木学務課長","answer":"指導課が実施しております保護者、生徒では９割以上が肯定的な回答をしておりますので、ニーズとしてはあると。ただ、その上でご自分のお住まいの通学区域の学校を選択していただいていると考えています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"何でそういう通学区域の学校を選択している人が多くなっているのかという分析はしていないということなのですか。そこを伺いたかったのですけれども、お願いします。","respondent":"柏木学務課長","answer":"細かい分析をしているかというと、していない部分ではありますけれども、考えといたしましては、あえてほかの学校に行かなくても、自分が望む、または自分の子どもに適した教育が受けられるという判断があると考えています。","id":"exchange-024"},{"speaker":"ゆきた委員","kind":"質問","question":"４０人学級から３５人学級の普通教室の不足という厳しい中ですけれども、課題として手を打たれていくべきものではないかと思われます。ご説明できる範囲で、全体的な学級数の増加など、現段階での取組と、八潮学園についての取組等があれば、お聞きできればと思います。","respondent":"柏木学務課長","answer":"以前も説明をさせていただいたかと思うのですが、その上で空きがある場合に、通学区域外の方を受け入れるという制度です。対応するために前々年度に推計をいたしまして、前年度にそういうことが突然起きた場合も対応できるように、普通教室の整備等を行っているところです。","id":"exchange-025"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"厳しい状況というのは、私も確認させていただきました。もう少し枠を増やすとか、引き続き区民の要望が形にできるようにと思いますので、こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それから、もう一つは、城南小と浜川小は６クラスになる予定になっているのでしょうか。受入れ人数からするとそうなるのですかね、１６４人ですから。","respondent":"柏木学務課長","answer":"現在、抽選の結果で入れた方、人数につきましては、足したものがないので、すぐお答えはできません。浜川から通学区域外を希望している方の待機の状況がまだ、これからも動きがありますので、現時点で何学級というのはお答えできない状況です。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"確認","question":"学校選択で受け入れてもらえた方がこの人数だと７年生のほうが少ないのでしょうけれども、できない話題ですけれども、どういう感想をお持ちか。仮に６クラスとなったときにでも、きちんと影響なく児童が、教育活動ができるような体制の準備ができているのを確認したいと思います。","respondent":"柏木学務課長","answer":"どうなっていくかというのは、実際の人数を見ながら検討していくところです。逆に転入される方、この件はまだ読めない部分がありますので、そこは慎重に見ていきたいと考えています。","id":"exchange-028"}]},{"id":"topic-03","title":"令和４年度品川区立学校における体罰等の実態把握","agenda":"令和４年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"行き過ぎた指導が７人、暴言は５人ということでしたが、なかなかこの調査からは分からないところなのでしょうか。そこら辺についてもし分かっているところがありましたら、説明を求めました。","respondent":"中谷指導課長","answer":"このようなことをされたお子さんへの、その後の対応についてのご質問であるかと存じます。通常のスクールカウンセラーの方に加えて、少し頻繁に来てもらうような体制をつくることなどは、具体的にやっているところです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"お願いしたいのですが、今回の報告された１２件での、そこを最後お伺いしたいと思います。","respondent":"中谷指導課長","answer":"すぐに謝罪をして、そして、速やかに心のケアを行うと。ここに待ったなしで取り組んでいくというところかと捉えておりますので、そこは引き続き大事にしてまいりたいと考えています。","id":"exchange-030"},{"speaker":"吉田副委員長","kind":"質問","question":"調査について伺いたいと思うのですけれども、調査は令和４年１２月５日から１２月２２日までの間に調査をしたということですね。それはないでしょうと思っていたのですけれども、その辺、改善の状況とかがあったら伺いたいと思います。","respondent":"中谷指導課長","answer":"目的としましては、子どもたちが安心して取り組めるということをまず第一としまして、３つ変更しています。年間を通して子どもたちが書きたいと思ったときには書けるという環境に変更をさせていただいたというのがこの令和４年度になっておりまして、回答が。","id":"exchange-031"},{"speaker":"吉田副委員長","kind":"質問","question":"それで、年間を通してという場合、この調査期間は多分用紙を配られるのだと思うのですけれども、それ以外の期間の場合はどういう形で書くのか。それとも、何か別の方法で訴えることが用意されているのか、その辺を伺いたいと思います。","respondent":"中谷指導課長","answer":"例えば、教室の中に常時置いてあるような形になっておりまして、書きたいときに自分で取っていくというような形があるかと思います。","id":"exchange-032"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"その辺も子どもたちの意見を聞いたりすることが必要かと思いますけれども、ぜひそれはやってほしいと求めました。同じような進化といいますか、より当事者の子どもたちの意見が活かされるような改善がされているのか、その辺があれば伺いたいと思います。","respondent":"中谷指導課長","answer":"不適切な指導というのはあってはならないものなので、まず、この根絶を目指すということが大事であると思います。ただ、起きてしまったからには、再発は絶対にさせないというところでアプローチを取っていくというところが一番大事なところではないかと思います。","id":"exchange-033"},{"speaker":"吉田副委員長","kind":"確認","question":"そのような指導方法ということについてのカリキュラムがあるのですかというのを確認したところ、それから、児童心理とかはありますよね。何か最初にそのようなカリキュラムというのでしょうか、その点についてもしお答えになれることがあったら、お話を伺いたいと思います。","respondent":"中谷指導課長","answer":"やはり人権感覚というものをしっかり高めていくこと、この２つがかなり重要であると考えております。校長はそれをしっかり活用していただいて、時には教員にそれを勧めていくというような形をこれからも促進できるようにしてまいりたいと考えています。","id":"exchange-034"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"やはりなぜそれが現場の皆さんにうまく活用されていないのかということのご意見も伺いながら、教員の方たちにもお伝えいただけたらと思います。これは要望でとどめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"懲戒を含めた処分はされていないのかということが１つと、体罰等の「等」については、そういう懲戒はないのでしょうか。もう一つは、この７人、以前にこういった「等」に当たることをされた方がまた再び繰り返した方がいるのかどうかということをお尋ねします。","respondent":"中谷指導課長","answer":"今ご質問いただいた件につきましては、まず、不適切な指導、暴言共に、口頭注意という形で行っております。再び同じことをやった例はないかというところですけれども、同じ教員が同じことをやったという事例はございません。","id":"exchange-036"}]},{"id":"topic-04","title":"運動部活動の地域移行に係る協議会（第１回）および文化部活動の地域移行に係る協議会（第１回）の報告","agenda":"運動部活動の地域移行に係る協議会（第１回）および文化部活動の地域移行に係る協議会（第１回）の報告","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"待遇というのがどうなっているか、改めて伺いたいと思いますし、それは見通しが立っているのでしょうか。伺いたいと思います。","respondent":"中谷指導課長、丸谷教育総合支援センター長","answer":"それから、３点目ですけれども、ご意見いただいたところにつきましては、今、合同部活という形でやってあります。こちらの４種目全て、しっかりと把握をして、次年度につなげていきたいと考えています。 部活動指導員の身分ということですけれども、こちら、会計年度任用職員として任用を行っているものです。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"現在の活動は守ってほしいみたいな、あるいは、そこについてはきちんとそういった手続を踏まえていただけるのでしょうかということを伺います。どういう思いでこういう意見が出たのかというのをお伺いしたいと思います。","respondent":"中谷指導課長","answer":"今１５校においてそれぞれで教員が顧問となりながら、または部活動指導員、外部指導員がつきながら行っている部活動になっております。この双方向でもって、子どもたち一人一人のニーズに応えるような、持続可能な活動をしてまいりたいと考えています。","id":"exchange-038"},{"speaker":"ゆきた委員","kind":"質問","question":"１点、お聞きしたいと思います。参考資料の２ページのところの図面が書いてあるところで、令和６年度・令和７年度の図を見ると、この件についてお聞きできればと思います。","respondent":"中谷指導課長","answer":"ラグビーを最初に今年度開始したのですけれども、例えばラグビーが終わった後に、このような示しでつくらせていただいているものです。これをずっとやっていくというわけではなくて、改革推進期間が終わった後に、改めてそれぞれの活動について見直しを図ってまいりたいと思いま…","id":"exchange-039"},{"speaker":"ゆきた委員","kind":"意見","question":"ヒアリング等を継続してやっていきながら、そのニーズに合った形になるようにできればと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"大会への出場への弊害というのはないのか確認したいのと、４ページのアンケートの中で、ｅスポーツというのは一切出てこないわけですよね。でも、アンケートで、どのような種目の活動があればやってみたいですか、第１位がｅスポーツ。","respondent":"中谷指導課長","answer":"２つ目のｅスポーツの件ですけれども、まず、令和６年度から行う学校に民間委託をどう導入していくかといったところの検証を行いたかったため。１番ですと、新しいものというよりは、あえて学校の部活動にあるものを選ばせていただいたという経緯です。","id":"exchange-041"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やっていないで、品川が１番目に手を挙げて、だって、地元にそういう企業もあって、条件は整っているわけですよ。は教育委員会が覚悟を持って決断をして実行するかどうかだけだと思うので、これは要望にとどめておきますけれども、。","respondent":"中谷指導課長","answer":"把握している情報として、私立学校で今ｅスポーツ部活というのはございまして、こちらの動向はきちんと把握していきたいと思います。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"非常にどうしたらいいのかという疑問がすごく私はあるのですけれども、荏原五中は今そういう状態で、前からほぼほぼ女子しかいない部活動なのです。五中は部活動としてやっていただきたいと思っているのですが、検証含めて、分かっていることをお知らせほしいと求めました。","respondent":"中谷指導課長","answer":"バトミントン部は、今年度のみの教育委員会としての地域部活ということで、クローズする予定です。まず、教育委員会としてのバドミントン部というのは１年で終わりますけれども、そういったロードマップで進めてまいりたいと考えています。","id":"exchange-043"}]},{"id":"topic-05","title":"品川区いじめ防止対策推進基本方針の改訂","agenda":"品川区いじめ防止対策推進基本方針の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ですから、それをどう子ども主体で解決していける学校になるか、子どもたちの関係をどうつくるかというのがすごく大事だと思うのです。そういう基本方針の改訂が私は必要なのではないかと思うのですけれども、大きなところでざっくりなのですが、区教委の考えを伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"いじめはあってはならない、禁止するものだということで、基本方針でもうたっているところです。児童・生徒が主体でいじめについて考え、起こったときにどうしたらいいか、そういうものを考える授業というものを展開していきたいと考えております。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"新旧対照表の２ページとかには、これでも狭いというか、いじめが起こったときにどうするかという。先ほどの質問なのですけれども、そもそも方針に盛り込むべき分野ではないですということなのか、最後にお伺いします。","respondent":"丸谷教育総合支援センター長","answer":"ここにも赤字で幾つか追記をしておりまして、「いじめに関する授業」を意図的・計画的に年３回以上実施する。ここでは基本方針ですので、この方針を基に、児童・生徒への指導を行っていくというものです。","id":"exchange-045"},{"speaker":"ゆきた委員","kind":"質問","question":"複数なのか１人なのかというところも、そういったところも明記すべきではないのかと思いましたので、こちらについてもお聞きできればと思います。監視とか、そういった対応というようなところで、何か対策というのは載せられなかったのかというところでお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"調査をしないことが考えられるということではございませんので、調査方法を考えて実施すると捉えていただければと思います。防犯カメラの設置というところについてですけれども、基本方針の中でも、関係機関と連携した対応というところで。","id":"exchange-046"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"さらに追って改善とか検討をしながら、よりよいものをつくっていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"石田（し）委員","kind":"提案","question":"委員長に提案なのですけれども、所管事務調査のいじめ対策で、かぶってくるところがあると思うのです。質疑もまとめて所管事務調査のところでやれれば、かぶらないかと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"調査員の方は補充したわけですが、大体１事案どれぐらいを目標にして調査を終了すると考えていらっしゃるのか、伺いたいと思います。現在どうなっているのかというのをお伺いします。","respondent":"丸谷教育総合支援センター長","answer":"それを教育委員会にも諮りながら、一度検討していただいてご意見をいただいて、１２月１２日に了承を得たという流れで決定しております。区長部局の調査も８月に終了して、今回の基本方針の改訂や学校への指導を充実させていくということで、我々も動いているところです。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと見解というのは、当然もう教育長ではないわけですから聞いたことがないわけですが、やはり伺う機会を持つ必要があるのではないかと思います。そこからどうするかというのはいろいろあるかもしれませんが、議会としてなのか分かりませんが、現教育長のお考え方も伺えればと思います。","respondent":"丸谷教育総合支援センター長","answer":"２０２０年の重大事態の対応というところです。教育委員会組織で対応しておりますので、それ以降に起こった事案につきましても、組織として丁寧に対応していきたいと考えております。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区として独自教員を雇っているわけですから、３５人学級というのを直ちに広げるべきだと思いますが、それはいかがでしょうか。伺います。","respondent":"丸谷教育総合支援センター長","answer":"登校した児童・生徒のその日の調子を朝、簡単なアンケートを取って、学級全体の様子がデータで分かるような取組を現在検討しています。そうした取組が進むと教員の多忙化、一人ひとりの様子を観察するうえの多忙化というところも解消されるものだと考えています。","id":"exchange-051"},{"speaker":"安藤委員","kind":"提案","question":"やはり私が提案したいのは、やはり教育委員会が責任であるわけですから、そちらについてはどうでしょうか。逆に言うとこれまでのアンケートはあまり科学的根拠に基づいていなかったのでしょうかというふうにもなってしまわないかと思いますとの意見を述べました。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"あくまでも品川区の教育の中心的な担い手のために雇用しているものですので、いわゆる３５人学級で少人数学級の実施のための雇用ではございません。繰り返しになりますが、あくまでも標準法に基づいて学級編制はしていく考えです。 紙で丸をつけて、手作業で集計して、何かそこで気づいたところを教員が見て対応していくというようなことは繰り返し行ってまいりました。そういったものでデータに基づく対策ができるようになってくると考えております。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"こんな感じの３段階というのが、それぞれどのような研修を考えているのか、伺いたい。情報の一元管理というのは、具体的にはどういうことなのか、どういうふうにやるのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"学校管理職や生活指導主任、養護教諭等、いじめの相談を受けたり対応したり指示を出したりといった教員向けの研修を考えております。これは困難事例、または教育委員会の指導主事を含めた職員向けに行う研修で、３層の研修ということで考えているものです。","id":"exchange-053"},{"speaker":"石田（し）委員","kind":"質問","question":"何点かお伺いします。そこをお願いします。","respondent":"丸谷教育総合支援センター長","answer":"いずれの組織も常設のものになってあります。","id":"exchange-054"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もしあれば、教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"その上で、単純にそれだけではなくて、なぜいじめは起こるのかといったところも含めて指導していく予定です。組織的な対応をすることが何より大切だと思いますので、引き続き努めていきたいと考えております。","id":"exchange-055"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"品川区も例えばヤングケアラーで今、体験者の方たちに実際、取り組んでいただいて、推進していこうというのもあるではないですか。これは要望で終わりますので、ぜひ引き続き取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"ゆきた委員","kind":"質問","question":"所管事務調査のところからお聞きしたいのですけれども、まず目安箱について、「全校設置」と載っていますが、目安箱は学校のどこに設置されているか、教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"各学校の各学年の教室があるフロアに１つずつ設置しているというのが基本となっています。ただ、少し離れたところや少し陰になっているところに置いてある学校が多いかなです。","id":"exchange-057"},{"speaker":"ゆきた委員","kind":"質問","question":"アイシグナルもありますが、いじめの抑止力といったところでは、機能としてはどうしても弱いのではないかなと感じます。この抑止力という観点で、今後、品川区で何か取組とか考えなどがあれば、教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"教育委員会として今考えているのは、１人１台端末を使った子どもの観察といったものは今後も進めていく予定です。区長部局の対応として今新しく組織が設置されていますが、相談ツールを幾つか持っています。","id":"exchange-058"},{"speaker":"ゆきた委員","kind":"提案","question":"今確認させていただきまして、やはり視覚的なところの抑止力とか、先ほどもあったとおり、いじめは罪だと。具体的に提案というのはちょっとできていませんが、そういったところでさらに検討していただければなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"質問","question":"これは今まで生活指導の部というか、そういうことが起きたときに、これとこれとこれはみたいな形でやっていたのを明文化したのでしょうか。今回様々なことがあって、区長部局との連携が課題の一つではあったわけですから、そこは、なぜそれが載っていないのか。","respondent":"丸谷教育総合支援センター長","answer":"委員長は校長で、副校長、生活指導主任、学年主任、スクールカウンセラー、養護教諭が主立った構成メンバーとなっています。区長部局との連携が基本方針に盛り込まれていないのは、改めて基本方針については修正・改訂していくような考えです。","id":"exchange-060"},{"speaker":"高橋（し）委員","kind":"質問","question":"区長部局とそういう形で一体となってみたいなのをあえて入れないで、きちんと出てきた段階で改訂しようという今お答えでした。そうすると、近々区長部局との関係については、再改訂ではないですが追加が行われると受け取ってよろしいか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"そのとおりです。区長部局との連携については、再改訂という形で追記していくつもりです。","id":"exchange-061"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そのことを伺いたいと思います。その辺についても伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"区長部局との連携についてですが、今後基本方針をさらに改訂していく中で、必要な事項を盛り込んでいくことになると思います。法律の専門家も今後加わるというお話も伺っていますので、そうした観点からも、いじめへの対処について記述されるものと考えております。","id":"exchange-062"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これは要望しておきます。子どもたちの意見を入れながら検証するということを考えていただきたいのですが、その点についてだけご意見をほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"そういったものを各学校がしっかりと検討したうえで決めているものだと捉えております。そうしたところで子どもたちの活用というのはしっかりと進めていきたいと考えております。","id":"exchange-063"},{"speaker":"吉田副委員長","kind":"提案","question":"あ、もう週１回、全員この日は白紙でもいいから入れるという日をつくったらどうかという提案をさせていただいたと考えています。これは要望にとどめますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これから異動の時期になるわけではないですか。今後、どう考えておられるのかというのをお聞かせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"まず転入された先生方には、品川区の教育の中で、品川区のいじめ対策についてきちんと４月当初に説明してまいります。若手研修会が初任者の方は年間１０回ありますので、その中でいじめも一つのテーマとして据えながら、どのように学校で対応すればいいか。","id":"exchange-065"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今までもそういう研修等はあったと思ったのですが、今回は特別ないろいろな案件がありましたので、今まで以上に新任の先生には対策を講じてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"吉田副委員長","kind":"提案","question":"あっという間にみんなから、そうだ、あいつはいじめをするやつだという感じで、いじめられる側に回ってしまった事例を伺いました。これは、別に提案も何もないのですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"}]},{"id":"topic-07","title":"令和６年度品川区立学校における土曜授業の実施","agenda":"令和６年度品川区立学校における土曜授業の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"年８回にして、来年度で３年目に入るというわけですが、子どもや保護者あるいは地域からの反応というのはどんな感じでしょうか。私は減らしてよかったのではないかなと思っていますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"学校現場から聞く話ですと、体力的にも厳しいというお話が以前ございましたが、そういったものが大分軽減されたという話は伺っています。教職員につきましても、土曜授業の回数が減ったことで、働き方改革も含めて進んだというお話は伺っているところです。","id":"exchange-068"}]},{"id":"topic-08","title":"子ども・若者活動拠点の整備","agenda":"子ども・若者活動拠点の整備","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この基本構想の案の報告というのは、議会にあるのでしょうか。今、方向性ということでの報告でしたが、そういった報告をいただいたうえで意見を言える場が必要だと思いますが、いかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"子若のフリースペースが移るかというところですが、こちらには別のものと考えているところですが、検討段階なので何とも言えませんというところです。基本構想については今年度中に作成したいと考えておりますが、進捗状況を踏まえて、また検討したいと思います。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"こちらは何回で何人ぐらいだったのかというのをお伺いします。こちらは要望したいと思います。","respondent":"藤村子ども育成課長","answer":"フリースペースのワークショップは１回実施しておりまして、こちらは参加者１２名でした。","id":"exchange-070"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"これは要望としてあるので必要だと思いますが、やはり同じ若者が受け入れる側として寄り添っていけるような体制も必要ではないかと感じています。こういった施設の運営として人の魅力の発信という仕組みづくりといったところで、この辺についてお考えがあれば、お聞きできればと思います。","respondent":"藤村子ども育成課長","answer":"乳幼児担当の方と青少年担当の方といった形で寄り添って対応できる方を配置したいと考えています。例えば職員を置きつつ委託を置くなどいろいろな方法があると思いますので、様々検討したいと考えています。","id":"exchange-071"},{"speaker":"ゆきた委員","kind":"意見","question":"先ほど申し上げたところで、この発信についてです。この人だったら話してみようかなといったきっかけづくりになるような発信もぜひ検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"石田（し）委員","kind":"提案","question":"以前も提案していますが、自分たちで抱えて、弟子にするのは難しい。ここで言っている区内企業との連携というのはどういうことなのか、お知らせくださいとの意見を述べました。","respondent":"藤村子ども育成課長","answer":"こちらに書いた区内企業との連携というところが、伝統工芸の方とか、一つの職業へのきっかけになる場所にもなれたらいいかなと思っているところです。伝統工芸というくくりですと、子どもたちに伝統工芸のことを見ていただいて…","id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"こういった施設ができるときには、ぜひそういったところに力を入れながら進めていただきたいなと。これは要望で終わりますが、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"その点について伺いたいと思います。把握されていることがあったら伺いたいです。","respondent":"藤村子ども育成課長","answer":"まだ検討の最中ですが、何かしらご用意できればと考えています。それに似たような形で、女性の方が来ても気兼ねなく何もせず過ごせるような場所をご準備できればと考えております。","id":"exchange-075"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"女性だけと限ってしまうのはどうかなと思いつつ、これからも建設途中でいろいろ聴取する機会を持っていただけたらと思います。これは要望にとどめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"}]},{"id":"topic-09","title":"令和６年度 私立保育園および幼稚園の設置等","agenda":"令和６年度 私立保育園および幼稚園の設置等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そこら辺をお伺いしたいというのが１つです。転園先については心配ありませんということでしたが、どんな感じで手を打ったのかというのをちょっとお伺いしたいと思います。","respondent":"石井保育支援課長","answer":"設置者の変更に伴う保育内容の変更と、保護者への説明についてお答えいたします。保護者等への説明などを行いまして、例えば転園については２点加点による転園ですとか、あとは受入先の調整支援ということで。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"廃止というところの４つの園ですが、今の小規模等も含めて、廃止の理由というのですか。戸越幼稚園とがくどうえんが元いたところというのが、例の２９号線の道路事業にかかっているところだと思いますが、伺いたいと思います。","respondent":"石井保育支援課長","answer":"補助２９号線と直接関連して閉園するといったことではございません。戸越幼稚園に関しては、やはり次がいないという相談があったので、こちらも補助２９号線に関連してということではございません。","id":"exchange-078"},{"speaker":"安藤委員","kind":"確認","question":"戸越幼稚園は、では、東京都から、道路用地なので買いますけれど、売ってくださいという話は来ていないということでよろしいのでしょうか。そこを再度確認させてください。","respondent":"石井保育支援課長","answer":"私のところに来た相談というものは、あくまでも代替わりということです。例えば補助２９号線に伴う用地交渉の件につきましては、私のほうに相談が来ているものではございませんので、詳細については把握してはおりません。","id":"exchange-079"}]},{"id":"topic-10","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"こちらにいらっしゃいますけれど、検討してほしいとお申入れをしていただきたいと思うのですが、ぜひよろしくお願いしたいと。ぜひ委員長として、申し入れていただきたいと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"}]},{"id":"topic-11","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これは、文教委員は見学はできるのかということと、全国連絡協議会というのは、会員は何自治体あるのか説明を求めました。","respondent":"中谷指導課長","answer":"合わせて７４。昨年の１１月２０日現在ですが、そのような数となっております。","id":"exchange-081"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですからアスタリスクになってしまう。それはどうして起きたのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"教育総合支援センターが入試関係を行っておりますが、学務課とも連携しながらシステムを入れてもらっているところです。今後うまく都立高校との連携を進められるように、都教委とも連携しながら、システムとも連携していきたいと考えているところです。","id":"exchange-082"},{"speaker":"高橋（し）委員","kind":"確認","question":"そうすると、品川区の中学生の調査書だけが、都立高校の全受験校で担当の教員が手入力しているという現実があります。品川区教育委員会は、今年初めてそのフォントはスキャンできないということを聞いたというところをちょっと確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"昨年度は、そういったお話はセンターとしては把握しておりません。本年度はそういうことがあったということで、都立高校から品川区のは読み込めないというお話をいただいたところです。","id":"exchange-083"},{"speaker":"高橋（し）委員","kind":"質問","question":"一般入試に間に合わないでしょうか。間に合わないとそうなってしまうのですが、そこのところはいかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"一般入試に向けて、直せるのであれば、できる限り直ったもので出力してくださいというアナウンスはしていきたいというふうには考えております。まだはっきりとこの場では申し上げられないのですが、もし間に合えばそのような対応をしたいと思います。","id":"exchange-084"},{"speaker":"高橋（し）委員","kind":"意見","question":"品川区の中学から来た調査書だけがスキャンできないというのが広がっているわけなので、そこはいかんともしがたいというか何とも。どこを気をつけてどうすればいいかは、ちょっと仕組みが分かっていないので、そこをしっかりしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/435368?Template=document&Id=5120#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":81744,"voices":244}},{"id":"r06-20240122-5","meetingId":"r06-cm01","date":"2024年1月22日","dateIso":"2024-01-22","committee":"総務委員会","time":"午後 １時００分～午後 ５時０７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"先ほど申し上げたとおり取り上げる順番を変更して、初めに、(2)区民アンケート","agenda":"先ほど申し上げたとおり取り上げる順番を変更して、初めに、(2)区民アンケート","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"見たいというお話も伺っていますので、その自由記述は個人情報を除いて読むことができるのかという点を一つ確認させてください。年齢ごとでも何か特徴が見えてくるものがあるのかなと思ったのですが、その年齢とか年代ごとの分析の公表についてのお考えを伺いたいと思います。","respondent":"辻広報広聴課長","answer":"１点目の自由記述の公表についてですが、委員ご指摘のとおり、個人情報や人を誹謗中傷するようなものを除きまして、全て公表する予定です。そちらのほうで、年代別ですとか地域別のクロス集計というものも行って、そちらを掲載する予定です。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問・要望","question":"今後その回答率を上げるために、区として既に何か対策などを練られていらっしゃるのかと思いまして、もしありましたらぜひお聞かせいただきたいです。区民アンケートの定期的な継続をしてほしいという要望もこのアンケートの回答の中にあったのですけれども、併せてお聞かせほしいと求めました。","respondent":"辻広報広聴課長","answer":"ただ、数としては予定よりも少なくなってしまったのですけれども、この形でよろしいのかなというのが一つあります。郵送かインターネットで回答というようなことで、区民の意見をまた集めるような方法というのは引き続き考えていきたいと思っています。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"もう一つのリマインドをしていたというのは、世論調査のほうがリマインドをされていたのですか。例えば今後の区民アンケートでも、またそういう手法などを取り入れていただけたらいいのかなと思うのですが、いかがか尋ねました。","respondent":"辻広報広聴課長","answer":"そうですね。費用面と費用対効果、様々なことを考えながら、多くの方からご意見をいただけるような手法を考えていきたいと思います。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"本当に１年に一回でも、区民の意見を聞いて、そして区政に関心を持っていただくというようなことを今後も続けてほしいと私は思います。今回はいろいろご苦労さまでしたが、今後も品川区のことに区民がもっと関心を持っていただけるように努力してほしいと思います。","respondent":"辻広報広聴課長","answer":"全区民アンケートを毎年でも取ることについてです。それを１件ずつ目検で見ないと、やはり１人ずつに語りかけて、頭をひねっていきたいと思っています。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"今日は副区長もいらっしゃいます。企画課、財政課の理事者の皆さんもいらっしゃいますので、ぜひ、区政に関心を持っていただけるように、私は様々工夫をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"アンケートはアンケートで公約でもやったわけだから、じゃあ、これからどうするのかというのが、このままで終わるのかという話。どうやってフォローしていきますよということぐらいは言ってくれないと、と思っているので、そこら辺は何か一つだけでも聞きたいですとの意見を述べました。","respondent":"辻広報広聴課長","answer":"今回のアンケートで、羽田のほうは羽田のほうでどういう意見が出て、それを今後どうしていこうというのは考えます。今後の施策の参考にしていくというふうに考えておりますので、今後に生かす生きたデータとして、活用していきたいと考えています。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"それぐらいまでは来ているわけじゃないですか。結果が出たらもう一回渡すのも含めて、それをしっかり生かしてほしいということは、やはり全体で考えてほしいということだけお願いしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"}]},{"id":"topic-02","title":"請求書等の押印省略","agenda":"請求書等の押印省略","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ。２３区の動きがどうかということと、そこでの取扱いは現状どうなのかということと、今後どのように考えているのかもご説明ほしいと求めました。","respondent":"大串会計管理者","answer":"ただ、私のほうで知り得ているところで、請求書に関しての押印の見直しを行っているのは４区と伺っています。ただ、これも徐々に変更・変化していくものと考えているところです。","id":"exchange-008"},{"speaker":"須貝委員","kind":"確認","question":"確認ですが、そういうことをやるときに、押印することによって責任が誰だというふうに確定されるわけですね。それは今後、押印はしなくても、誰がこれを了解したのか、請求書を作ったのかというのは分かるようになっているのか尋ねました。","respondent":"大串会計管理者","answer":"もう一方、ここでも例外としてということで２番の2)に書かせていただきましたけれども、書類発行責任者等の記載ということを求めしています。これによって、この請求書は正当なものであるということを客観的に証明してもらって…","id":"exchange-009"}]},{"id":"topic-03","title":"「公共施設等総合計画改定（素案）」にかかるパブリックコメントの実施","agenda":"「公共施設等総合計画改定（素案）」にかかるパブリックコメントの実施","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"初めに、区民の暮らしに関わって必要な施設が統廃合されるものであってはならないと私は思っております。児童センターと区営住宅について伺いたいのですが、この施設については今後も同じか、それについて伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"こちらの計画は、全体計画あるいは個別の施設の計画のあり方をまとめさせていただいているものですけれども、先ほど統廃合というお話がございましたが、今後の人口動向、あるいは施設の老朽化状態、そういったものを含めまして、全体的に検討する事項だと考えております。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問は、区営住宅の部屋の数、戸数を減らす考えがあるのかということを伺いたいと思います。もちろん私は増やすべきだということをさんざん言っているわけですけれども、変える考えはないということでいいのか、ここだけ伺いたいと思います。","respondent":"せりざわ委員長、吉岡政策推進担当課長","answer":"総合計画なので、各課からおまとめいただいて今出ていると思うので、大分細かい議論になってきていますから、それは答えられないと思います。 集約化・複合化というのは、ある種の施設の維持、これもコストの軽減を図るというような一つの目的のところで書かせていただいております。先ほど申し上げたとおり、人口動向等…","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"物価上昇に見合っていないという現状もありますので、現状維持にとどまらず、増やすことを検討していただきたい。今度品川区も公営住宅で１０戸ほど協力するという発表がありましたけれども、重要な施設だと引き続き位置づけていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"各自治体、品川区は品川区でやっているわけで、国は品川区のことなど分からないのに、このような通知をなぜ自治体に出す意味があるのでしょうか。それを説明を求めました。","respondent":"吉岡政策推進担当課長","answer":"品川区が前回作ったのは平成２９年度ということで、総合実施計画、この間より大きく伸びているというところをお示しさせていただいているところです。いわゆる１０年計画の半分が過ぎたところで、こちらの改定をさせていただいたです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"そうではなくて、各自治体で、施設もこうして改修なりまたは新たに造っていくという方針をきちんと立てられてこれだけできているではないですか。このように見直しを実施するように通知をしてくること自体が、私は少し失礼な気もするのですが、違いますか。","respondent":"吉岡政策推進担当課長","answer":"国のほうも個別施設というところで、先ほど申し上げた学校ですとかそういったところの施設計画を立てなさいと。今まで、こういったもともと品川区のほうが平成２９年度に立てました総合計画につきましては、そういったところから見直しの要請が図られたです。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと今質問と答弁が合っていないのであれですけれども、質問はしませんけれども、なぜこのようなことを言ってくるのだと。このように通知をよこすなら、その分それなりの財源もくださいと言ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"品川区も、ずっと増えてきているものを区としてどう考えるのかというのは、どこかのタイミングでやはり考えていかないといけないと思っています。その観点から、今回の計画をまとめていくにあたって、区としてこの延床面積という点からはどのように考えていらっしゃるのか伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"やはり区民の方の数が増えているところもございまして、必要な施設の面積が確保できてきたというところがあります。今後の人口動態も含めまして、１人当たりのこういった面積というところは、一つ基準になるのだろうと捉えているところです。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問・要望","question":"やはりもう我々区民というのはどうしても要望する側なので、どんどん要望するとむしろ増やせ、目標は今持っていないということでありましたけれども。以上、意見です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"これはこれで品川区公共施設等総合計画改定（素案）だけれども、長期基本計画があったりいろいろなものがあるじゃないですか。それはちょっとどうかという感じです。","respondent":"吉岡政策推進担当課長","answer":"あるいはその施設を考える上でも一番の上位の計画とは考えてありますけれども、あるいは施設のあり方方針といったものも個別に存在するようなところでございまして、どうまとめていくかというのを検討していきたいと思います。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なぜこのようなことを言うかというと、区の思いというのがあるでしょう。後で能登の話があるから、多分あまりいいことではないと思うので、ぜひ品川区独自でいろいろ考えていただきたいということだけ言っておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-04","title":"令和６年能登半島地震に対する区の対応","agenda":"令和６年能登半島地震に対する区の対応","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、地震があったのが１月１日ということで、私は相当動いていたと思うのです。自治体職員ならではの使命感と公務員としての役割と、しかし正月ですからね。","respondent":"勝亦総務課長","answer":"中部地方での地震ですので、連携交流のある福井県坂井市につきましても震度５という情報がございましたので、被害状況を確認した状況です。それからそちらを通じまして、区長、副区長に情報を入れていたところです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"幸いにしてこの品川区は震度２ということで、大きな被害はなかったわけですけれども、私もテレビを見ておりました。今回の経験も踏まえて、さらに緊急対応をレベルアップしていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"品川区は井戸をやっていないじゃないですか。やらないの話ではないけれども、品川区でやるというのがあっていいような気がしているのだけれども、そこだけ聞きたいです。","respondent":"勝亦総務課長","answer":"被災地支援ですけれども、危機管理部門、総務部と防災まちづくり部等々の部門と連携していかなくてはいけない部分は多々あると感じてあります。そういった意味で引き続き、今回は被災地支援という形にはなっておりますけれども。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"意見","question":"ぜひ、よろしくお願いします。ネットは後でもいいけれども、そういう紙媒体を含めてやってもらったほうがありがたいと思うので、ぜひとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"澤田委員","kind":"質問","question":"１月４日から義援金の受け付けをされていて、今回１０７万円という金額が出ていますけれども、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"さらなるこの寄付へのモチベーションといいますか、意欲をお願いできると考えておりますので、そういったものについては継続的に情報発信していきたいと考えております。","id":"exchange-024"}]},{"id":"topic-05","title":"区長部局におけるいじめ相談窓口の設置","agenda":"区長部局におけるいじめ相談窓口の設置","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"相当深刻な状況に既になっているというふうに構えた上で、相手の話や状況を伺うという姿勢がまず大事だと思うのです。ここに電話をするその生徒・児童の気持ちをやはり十分踏まえて、命を守る取組みを優先していただきたいと願うわけですけれども、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"そこから様々な話をさらにたくさん聞いていけると考えています。お話を聞く姿勢としてしては、受容して共感していくところから入っていくのかなと考えています。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"事実関係を確認することに懸命になってしまって、事実関係を確認することはとても大事ですけれども、どうも後景に追いやられている気がするのです。そこを区長部局にも求めたいし、ぜひ教育委員会にもその専門性を生かして力を発揮していただきたいと、改めていかがか尋ねました。","respondent":"勝亦総務課長","answer":"早期に解決を図っていくということで、まずどうしたらその解決を図っていけるかというところを区として考えてあります。委員がおっしゃったように、ご本人のお気持ちも含め、学校ですとか保護者との対応を取っていくという考え方で対応を取っていきます。","id":"exchange-026"},{"speaker":"松本委員","kind":"質問・要望","question":"ホームページも拝見しながら質問させていただきたいのですが、やはりこれがどうなのかなということで、それでも今共働きの時代ですから。そこについて伺えればと思います。","respondent":"勝亦総務課長","answer":"やはり今、学校に行くのは少し心配だとか気持ちが前に向かないということであれば、ご希望に沿った形で区役所のほうで対応したいと考えています。時間につきましても、基本的には現在午前９時から午後５時という形で対応しています。","id":"exchange-027"},{"speaker":"松本委員","kind":"意見","question":"寝屋川市も９時から５時半で、それほど変わらないので、そういう意味では寝屋川市も十全かと言われると、私はどうかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"須貝委員","kind":"確認","question":"区長部局にその内容が届いて、それでそのいじめの内容を確認して、当事者に出向くという形が私はよりベターだと思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"}]},{"id":"topic-06","title":"（仮称）ジェンダー平等を推進するための条例に盛り込むべき考え方に関するパブリックコメントの結果等","agenda":"（仮称）ジェンダー平等を推進するための条例に盛り込むべき考え方に関するパブリックコメントの結果等","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"さっき区の立場の説明はありましたけれども、率直にこういうパブリックコメントをしてどう思ったかということを伺いたいと思います。品川区としては、今回のパブリックコメントの結果を受けて率直にどう思ったかというところを伺いたいと思います。","respondent":"加島人権啓発課長","answer":"パブリックコメントを実施しての、所管としての思いというところでお答え申し上げます。総括的なところが最初の説明で抜けてしまったのですが、今回パブリックコメントを実施した中で。","id":"exchange-030"},{"speaker":"中塚委員","kind":"提案","question":"現状ではまだ第１回品川区議会定例会に出すというところですから、今まで以上に理解を求めていく、ご意見を伺っていく。条例の提案に向けて、区民にさらに理解を広げていく取組みを強めていったらいかがかなと思うのですけれども、どうか尋ねました。","respondent":"加島人権啓発課長","answer":"品川区ジェンダー平等の推進に関する検討委員会を中心に検討を行っておりましたので、区ホームページ上で一部を除き全面的に公開しております。それに対して区のほうでどのような考え方を基に、また、誤解が解けるように対応してまいりたいと考えております。","id":"exchange-031"},{"speaker":"中塚委員","kind":"提案","question":"既に今日の総務委員会でも第１回品川区議会定例会に出すという報告はされているわけで、それは当然しっかりと必要な対応をしていただきたい。同時に区民に対してもこういう条例の提案を今準備しておりますというのは、理解を求め、意見を集めるというとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"須貝委員","kind":"提案","question":"今回、ジェンダー平等推進にかかる条例ですが、議会に提案されるというお話です。意見だけ言わせてくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"松本委員","kind":"質問","question":"ただ、まず２段階に分けてお伺いしたいのですが、例えば品川区というふうに明記されていないものもここに掲載されているのかというのが１点です。その点はいかがか尋ねました。","respondent":"加島人権啓発課長","answer":"６５件いただいたご意見のうち、住所の欄に品川区ないしは品川区の町名等以下、番地等も含めて記載があったご意見については、５１件ございました。ただ、どちらも品川区の町名については存在する町名であったと確認しております。","id":"exchange-034"},{"speaker":"松本委員","kind":"確認","question":"確認です。５１件ということは、１０件以上は品川区と明記されていないものがあったということでよろしいのか、１回確認させてください。","respondent":"加島人権啓発課長","answer":"６５件から５１件を差し引いた残りの件数につきましては、そもそも不明と明記されていたり、空欄というか匿名、それから区外の住所等が入っていたものについては、５１件の中にはカウントしておりません。","id":"exchange-035"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"これを採用した理由を聞きたいのと、どうしてもトランスジェンダーの方の制限、やはりどうしても最終的には難しくなってくるのだろうと思うのです。その懸念を払拭するような表現というのをぜひ求めたいと思っているのですが、その点についてというのが１つ。","respondent":"加島人権啓発課長","answer":"答申の中で、品川区ジェンダー平等の推進に関する検討委員会からも申し送られておりますように、変化への対応という項目があります。人権課題の変化に応じて、女性一人一人が互いの違いを認め合って…","id":"exchange-036"},{"speaker":"塚本副委員長","kind":"提案","question":"２３区の中では比較的最後のほうになってこういう条例を品川区が今回提案していくということなので、そういったところでは先進的な時代の先をしっかりと捉えたような形で、さすがにこれは今の時代に即しているというものになるようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-07","title":"，所管事務調査","agenda":"，所管事務調査","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それだけあるのだからいいのではないですかといって、それをまとめて要望するとか、この決算分析で終わってしまうような気がしてならないのです。ここら辺のところだけ説明、教えてほしいです。","respondent":"遠藤財政課長","answer":"これを変な話、２３区全てが出していろいろ積み上げて、こちらから言いたいことはきちんとエビデンスに基づいて説明すると。毎月話合いなどもやっておりますので、そういうところで一致協力して進めていければと思っているところです。","id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひそれを今の区長会の話が出るのなら、区長会でもう一回そこら辺はもう５回ぐらい話が出るくらい頼むというぐらい、ぜひそれはやってほしいです。この前どうかと言ったけれども、ホテルの支援というか旅館券みたいなものが出ているけれども、ああいうのを品川区は出せないのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"意見","question":"本当にこれはよく話が出るけれども、報告書にも書いてあるけれども、お金がかかっても何か採用するぐらいの話があってもいいような気がするのです。今、あまりに収入が少な過ぎるような気がしてならないので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"はっきり申し上げて別に東京都が何か特別な施策をやって収入増になっているわけではないのですから、特に固定資産税が増えている分を、壊せないのか。そのときに整備するのは各自治体ですから、２３区のほうでも財調算定に対して、出ていないのか説明を求めました。","respondent":"遠藤財政課長","answer":"一定程度までは見込めると思いますが、この部分はいろいろなところでやはり一般財源としては非常に大事なところだと考えていますので、これからも進めていきたいと思っています。","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"そこに住まわれる方、またはそこの建物云々に関して固定資産税がかかって、それが東京都の財源が増えていく一つの流れになっている。では２３区がどうなのかという話になったときに、私は大変なことになるのではないかと思いますので、区としても検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/837879?Template=document&Id=2288#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":48179,"voices":115}},{"id":"r06-20240123-14","meetingId":"r06-cm01","date":"2024年1月23日","dateIso":"2024-01-23","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"の１、特定事件調査","agenda":"の１、特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"建物の概要・外観計画について伺いたいのですが、いわゆる外観のみのご報告をされた趣旨は何なのかというところをお伺いしたいのと、これについてのご説明をお願いいたします。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"設計を一定進める中で、おおよその概要が固まりましたので、この段階で早く出していくという趣旨で今回お示しさせていただいたものになってあります。中の配置とか、その他のものにつきましては、今後検討が進み次第… 資料にあります行政機能、区民交流スペースというところの記載についてですけれども、こちらは基本計画で申しますところの区民協働・交流の機能の部分のスペースということで考えてあります。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"中のものが、先ほどのご答弁だとこれから決まっていくというお話ですけれども、それはまだ決まっていないということでよろしいのでしょうか。これは基本計画の何ページに、ほかの建物でつくるというところがあったのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"中の設計を進めているところではありますけれども、今の検討の中身といたしましては、そういうところの検討についてはこれからとなっています。その上に３階部分、４階部分として設定していくというところで、別棟の建物という形ではないというところで、補足説明します。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういうところのご説明があったのですが、そこについても速やかに、これについてはなるべく早く我々にも教えていただきたいということがあります。外だけなのか、外観だけなのかという印象が少しあったものですから、そういうことで質問させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"これは要望です。そういったところが普通とは異なるとは思うのですけれども、そこに対するコンセプトとかがあれば、教えてほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"コンセプトといたしましては３点ありまして、将来にわたって使い続けられる庁舎ということを具現化した形が、このような形となっています。周辺環境、目の前には広場があるというところの日射の低減化とか、そういう環境性能等々を踏まえて検討した結果の形となっているところで…","id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ、これから品川らしさ等の意見も反映して、さらによい外観となるよう、ご検討を進めてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"この暫定イメージ図を作成したのは、品川区が主体となって、このイメージを考えたということでよろしいのか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"２枚目の資料につきましては、新庁舎のイメージ等々の計画主体については、品川区になってあります。こちらを反映した結果が、お示しした２枚目の資料、また、単独で絵を描いたものが１枚目のイメージパースとなっています。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"計画に書いた３つのコンセプトというのは、具体的にはどれでしょうか。にぎわい都市の３つの基本理念というところか尋ねました。","respondent":"大友新庁舎建設担当課長","answer":"その３つの基本理念から、６つの基本方針が定められてあります。コンセプトとしてまとめたものが、基本理念から基本方針に下りて、基本方針からコンセプトにまとめたというものになってあります。","id":"exchange-007"},{"speaker":"筒井委員","kind":"確認","question":"その辺りはまた資料として、この委員会とかでお示しいただけると幸いですので、ぜひよろしくお願いします。このイメージ図は、専門の業者に委託して作成したものかということ、２点ほど確認したいと思います。","respondent":"大友新庁舎建設担当課長","answer":"おいおい固まり次第、逐一ご報告させていただきたいと考えているところです。今回受注している設計業者の中で専門の部隊がいますので、そちらで計画の設計図からイメージパースに変換して、少し分かりやすい形に整えたです。","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２ページ目のイメージパースなのですけれども、結構高層に見えるのですけれども、どうなのかということを教えてほしいと求めました。もう１点なのですけれども、設計するに当たって、躯体の考え方はどういうところなのかということを教えてほしいと求めました。","respondent":"大友新庁舎建設担当課長、黒田新庁舎整備担当部長","answer":"その陰に隠れて、２枚目のパースでは、区民交流スペースのところは見えない形となっています。２点目の公開スペースという形なのですけれども、３階部分等々、その部分については建物が来ないという場所が一部あります。 １枚目の資料ですと、都市計画手法により約６００％ということで、庁舎の一部に区民の方が使えるようなところがあるという形になっております。横が１４階建てとなっている中で、ほぼ外観等は固まってまいりますので…","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。１０ｍ超というか、１０ｍ高くなるというのは、屋上設備はどういうものを設置するのか教えていただきたいです。","respondent":"大友新庁舎建設担当課長","answer":"こちらにつきましては、空調設備などの設備機器が屋上に設置される形になります。","id":"exchange-010"},{"speaker":"まつざわ委員","kind":"質問","question":"そこで、まず３７１件、その他１５７件、このご意見の数という部分で、区としてこの数が、多い意見なのか、少なかったのか。トイレに随分意見が集中しているというのがありましたけれども、その辺の手応えというか、感覚はどうお思いなのか説明を求めました。","respondent":"山下新庁舎整備課長","answer":"今回、１か月かけず、３週間ぐらいの取組の中で、区内６か所、それぞれの地域で実施をしてまいりました。基本計画の素案の説明においては区施設を中心に実施をしてまいったところですけれども、実施をしたというところが、功を奏したのかなと考えています。","id":"exchange-011"},{"speaker":"えのした委員","kind":"質問","question":"本当に使える機能があるのかとか、不快に感じる部分を見つけてはいかがですかというご意見もあって、こちらはご意見として承りますと。ご意見よろしいか尋ねました。","respondent":"山下新庁舎整備課長","answer":"実験的な取組というのはできようかと考えてございまして、実施の形態等々、手法についても研究・検討を進めてまいりたいと考えています。２点目にございました、どのように取り組んでいけばいいのかという視点から、今回まとめることができたものと捉えてあります。","id":"exchange-012"},{"speaker":"えのした委員","kind":"質問・要望","question":"今後の設計・施工段階においても、様々なご意見、また見直し等があれば、その分、取り組んでほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"２ページ目の隣のビルのイメージとは全然違う形になっていて、これは、さっき言った３つのコンセプトというところなのか。今後どのぐらい、これはこれで、あくまで現段階のものですというところにとどめられる程度のものなのかということの感触をお知らせくださいとの意見を述べました。","respondent":"大友新庁舎建設担当課長","answer":"こちらの１ページ目、外観の形状といたしましては、おおむねこのような形になるのかなというところではあります。そこの材質等々、そういうものでイメージを変えていくという形になるかと考えております。","id":"exchange-014"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。一応、議会への説明のタイミングとかというのはどんなスケジュール感があるかというところで、分かる範囲でお知らせほしいと求めました。","respondent":"大友新庁舎建設担当課長","answer":"今後、中身につきましても、一定進んでいるところです。皆様にこのような場を通してご提示させていただきたいと考えておりますので、できるだけ最短のご提示ができるよう努めてまいりたいと考えております。","id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"今回、かなりイメージ図が出てきて、参考になりました。災害が起こったときのヘリコプターでの対応というのは、基本的には中央公園のヘリポートを使うという想定でいいのか、確認させてください。","respondent":"大友新庁舎建設担当課長","answer":"安全計画上、コスト上、合理的な計画となるということで計画をしています。大井消防署とも本協議をさせていただいてございまして、現時点では庁舎上には不要ではないかという状況で協議を進めているところです。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"そうすると、何か跡地活用を検討しようとするときに、ヘリポートというのは所与のもの、これは動かさないということで考えていらっしゃるのか。検討範囲の中に、ヘリポートは所与であるという記載とかは特になかったような気がするので、ここのバランスはどうなっているのか伺えればと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問・要望","question":"防犯カメラをつけてはどうかと思うのですが、これは１１ページだと書いていなかったので、どのような形で計画されているのかお知らせください。最後に、喫煙スペースはどうされるのか尋ねました。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"私から、アクセシビリティ整備の手引き、０４エスカレーターですとか、０５エレベーターについてお答え申し上げます。実際にエスカレーターを設置する段で… 広場１号につきましてなのですけれども、こちらの広場は、まだ運用について固まったというところでお聞きしている段階ではございません。続いて… 新庁舎整備基本計画におきましても、保健所・保健センター機能の導入というところで考えましたときに、少し難しさがあるのかなと捉えてあります。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問・要望","question":"モニターを設置していただいて、例えば品川区の広報にも活用できるのかなと思いますので、ぜひともお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１４階から１６階建てとか、１４階に落ち着いたのだというところで、その辺りの決まった経緯を教えていただきたいのが一つです。１ページ目の左下のところの外観イメージ、何か木材なのか、その辺りで教えていただけることがあれば説明を求めました。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"２点目の１４階に落ち着いたというところになるのですけれども、１５階から１９階程度になると想定して答弁をさせていただいて、ご説明をしています。２枚目の資料でご説明すると、先ほどお示しをさせていただいた議場の上に… １点だけ補足いたします。北東側と申しますか、そちらの部分の、少しくぼみになっているように映っているところが該当するものです。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問","question":"そのときに我々も若干、説明をしなければいけないものですから、議会部分についてはお話を伺いました。多分また、見ていればいろいろな疑問が出てくると思うので、それは個別にお伺いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"ワークショップや検討委員会の結果を踏まえた活用の基本的な考え方の案を、今後実施予定の区民アンケートにつきましてご説明を行ったところです。区民アンケートの実施結果や、その結果を踏まえました活用の基本的な考え方、お示しをしてまいります。","id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"すごく難しいというのは重々分かっているのですけれども、ある程度広い形で、子どもたちの声はぜひ聴いていただきたいと思うのが１点。体育館で対応できない場合はそういうところで避難ができるとか、何かそういう考え方も一ついいのかなと思っていまして、その２つだけ説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"防災の考え方、災害対応力の向上という形でお示しをさせていただいておりまして、少し検討を図ってまいりたいと考えています。２次避難所ですと、防災の部局とも調整をしながら検討してまいるところだと思いますので、連携を図りながら進めてまいりたいです。","id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"ぜひ、初めは近くで、そして幅広くというのを努力してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"参加した１６者で、参画に前向きな事業者が多いということも確認できたというところで、民間活用を前向きに進めていただきたいと。これは無作為抽出で２,５００名ということですが、無作為抽出以外での、幅広く区民の皆様の意見を聴く機会というのをつくるお考えはないかです。","respondent":"泉広町事業調整担当課長","answer":"先ほどご説明させていただいた第４回の検討委員会が３月２８日にございまして、また、それ以降も第５回の検討委員会ということで。今検討を行っていますけれども、区のホームページなどを活用いたしまして、意見をいただくようなところはつくっていきたいと考えています。","id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"併せて区内の方からも、意見を言える機会をつくっていただけるということでご検討を進めていただいているということで、非常にうれしく思います。ぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"えのした委員","kind":"質問・要望","question":"１６者（不動産事業者、そういったことをもし教えていただければ、または購入・借地のどちらでもよい。これは、業者がその建物や土地を購入・借地するという意味合いでいいのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"例えば２３区内で跡地を活用されて実施している事業者の方もいらっしゃいましたし、そういう意味では、様々なご意見を頂戴できたです。一方で、公有地ということで、その辺を鑑みまして、借地も考え得るというご回答が得られたというところのご説明です。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"総括で、どういうイメージがここに集約をされているのか、どういうイメージで皆さんがお考えになっているのか教えていただきたいというのが一つです。先ほどのサウンディング調査というのでしょうか、これは１６事業者が申し込んで、１６事業者から説明を聞いたということでよろしいのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"いずれにしても、先ほど申し上げた公有地というところも鑑みまして、借地でも対応ができるという形でのご回答が多かったです。参画を検討というところにございましては、「条件次第で参画を検討」としてございまして、ポテンシャルとしても非常に高いと認識したところです。","id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問","question":"１９ページに書いてありますが、そこで少し質問をしたというところですけれども、より関心が高いと判定するのかどうかというところが一つです。そこについて、これから先のスケジュールというか、その辺を教えてほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"今後検討を進めていかなければならないというところで認識してございまして、また、段階に応じてやっていったほうがいいというところもあります。今回の検討の委員会の中で、引き続き、段階的に対話型市場調査は行っていきたいというところで考えてあります。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"今は多分、区民の本当のニーズはすくい切れないのではないかというところがありまして、質問をさせていただきました。もし違ったら、また言ってください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうしたこともしっかりと意識していただきたいとは思っているのですけれども、こうしたまとめが１８ページに出てきたと。新庁舎整備に際して、具体的にどのような意見があったのか、お知らせください。","respondent":"泉広町事業調整担当課長","answer":"しっかり検討を進めていかなければいけない事項だというところで、一定程度ご理解をいただいた上でのご議論が成り立っているものと認識をしています。検討委員会の中ではなくて、ある程度この検討委員会の、しっかり周知を図られた上で進めているものというところで考えてありま…","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"結局、区としては、１６ページに掲載されていることを複合化した施設ということを考えていくということになるのでしょうか。その辺りを説明を求めました。","respondent":"泉広町事業調整担当課長","answer":"複合化をしなければならないというところは考えてございませんで、また、全て両立できるような視点での跡地活用ができればと考えているところです。それが両立できるだろうというご提案が多数あったということで…","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"最終的にどうするのかというのは大変かと思いますけれども、引き続き、区としても最終的な施設の形というのをお示しいただければと考えております。この調査を行って、今後具体的にどのぐらいの費用がかかりますとか、経済面の話というのはどの段階でお聞きするとかは決まっているのか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"金額についてのご回答は、先ほど具体的な金額の提示はなかったというところでお話をさせていただいたとおり、そのような形で進んだものです。そういったところを段階的に進める中で、今はまだこの段階では、いつ頃といったところのお話ができないというところになってあります。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118715?Template=document&Id=6162#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":32610,"voices":88}},{"id":"r06-20240124-19","meetingId":"r06-cm01","date":"2024年1月24日","dateIso":"2024-01-24","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ４時１０分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そのため、副委員長の私が委員長に代わって進めさせていただきたいと考えていますので、どうぞよろしくお願いいたします。最後に、会議時間が長時間にならないよう、簡潔かつ効率的なご質疑にご協力をどうぞ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"鈴木副委員長","kind":"意見","question":"ＳＤＧｓの取組について理事者よりご説明いただき、その後、委員の皆様には活発なご議論をしていただければと考えております。理事者よりご説明をお願いいたしますとの意見を述べました。","respondent":"河内環境課長","answer":"２点、連携協定によります区内事業者の再生可能エネルギー電力の導入支援およびマイボトル用給水機の利用促進に向けた今後の取組の２点につきまして。令和６年度入りますと、商業施設におけるマイボトル用給水機設置の段階と一緒に展開してまいりたいと考えているところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"そのようなところがどのような再エネの電力になっているのかということを伺いたいと思います。そのような面から考えると、再エネ事業者を広げていく、普及させていくということにつながるのかどうかということを伺いたいと思います。","respondent":"河内環境課長","answer":"ボリューム感といたしますと、全国２,２２８社の中から、何社かは参加されるです。このような仕組みをしっかり活かしながら、脱炭素、ＣＯ２の削減に向けてつなげていきたいと考えているところです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"確認","question":"水力発電などのようなものでいくと、事業者としてどのようなものが、どれだけあるのかというところも伺いたいと思います。事業者が続けていけるような契約ができる仕組みというものが、共同購入プロジェクトの中では何かあるのか、伺いたいと思います。","respondent":"河内環境課長","answer":"発電の形態などですが、やはり地域でのエネルギー資産もございまして、そのようなものも今後開発されるという報道も見聞きしています。そのようなところに制約を求めないというところが、やはり持続可能性につながると考えているところです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"仕組みのところでは、エナーバンク社のプロジェクト事務局のほうで、その対象になる事業者に呼びかけていくという形になるということなのですか。ある意味、全部の企業が参加対象、そのニーズに合ったところに呼びかけていくということなのかというところを確認させてほしいと求めました。","respondent":"河内環境課長","answer":"共同購入の流れについて、ご説明を詳しくさせていただきたいと思います。そのような４つの段階を踏んでまいりますので、そこは自動的にスクリーンにかかりますので、そのような懸念はご無用かと考えているところです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"改めて伺いたいと思うのですが、この証書については、区では取引はされているかどうかを伺いたいと思います。これをどれだけ削減できるというところ、料金とＣＯ２のところで、区の見込みを伺います。","respondent":"河内環境課長","answer":"我が区については、今のところまだ非常に難しいのではないかと解釈しています。目安になるかどうかは分かりませんが、削減の方向に向けて動くことは間違いないというところで運用していきたいと考えています。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"やはり広く知ってもらうためにも、内容を理解してもらうためにも説明会を開催すべきだと思うのですが、いかがでしょうか。この事業の説明を聞きに来た企業にもこうしたことを説明していただけたら、より理解が深まっていくのかと思うのですが、いかがか尋ねました。","respondent":"河内環境課長","answer":"この２つをもちまして、まずは進めてまいりたいと考えていますが、説明会なども検討していければというところに考えております。ＣＯ２の削減は喫緊の課題ですので、お互いにメリットがあることはしっかりご説明させていただきながら、周知に努めたいと考えているところです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"Ａ３資料のところの６の参考資料というところで、区では５４施設で、全部で何施設あるのかというところです。再エネの利用の導入については、ぜひ広げていっていただきたいと思うのですが、今後の区の展開について伺いたいと思います。","respondent":"河内環境課長","answer":"転用しながら全体のＣＯ２の削減にしっかりと結びつけ、２０３０年がゴールといいながらも、カーボンハーフはもう目前に迫っているところです。皆の課題として共有しつつ進めることが、区有施設や民間を併せまして、しっかりと推進していきたいと考えているところです。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"区の施設のほうでも、今、箇所数では１６％ぐらいだということですので、ぜひさらに広げていっていただきたいと要望しておきたいと思います。これだけではなく、ほかのところでも、ぜひ再エネ普及へ支援をしていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"地域事業者、法人や各事業所のＲＥ１００に向けて、ぜひＰＲの仕組み、仕方や取組に全力を注いでほしいと求めました。品川区でも今後の取組の工夫で考えられる工夫点など、もし紹介できるものがあれば、教えてほしいと求めました。","respondent":"河内環境課長","answer":"そのようなところで、銀行の情報などを併せまして展開することが、企業の一番のインセンティブになると考えているところです。そのようなものを含めまして、しっかり推進して、周知、ＰＲについて全力を尽くしたいと考えているところです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"ユーザーからすれば、やはり安い電力の供給を私はどうしても求めていくわけで、そちらにシフトしていくことが大きいのではないかと思います。各家庭もそうだと思うのですが、その辺についてご見解を説明を求めました。","respondent":"河内環境課長","answer":"も、なおかつ自身の経営あるいは社会への貢献のために環境に役立つことをしたく、そのようなものをやりたいという方もいらっしゃいます。ぜひ進めてまいりたいと思います。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"はそれぞれのユーザーが何を求めているのかということも考えながら、そのような値段のところのせめぎ合いもあると思うので、その辺は慎重に進めていただきたいと私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"中小企業といってもいろいろありますので、お一人、お二人でやっているような本当に小さい企業もあります。どのようなところを対象としていきたいと思っているのか、どれくらいの募集をしたいと思っているのか、お聞かせほしいと求めました。","respondent":"河内環境課長","answer":"ご説明したとおり、個人事業主の方でも、本当にご参加いただける仕組みです。この辺りの今後の進展が必要になってまいりまして、２０３０年には、やはりこの分野でもカーボンハーフを目指すべきだと考えております。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"紙ベースで知っていくということかと思うのですが、紙ベースの案内が来たときに、どうやったらその企業に関心を持ってもらえるか。まずはここの案内が大事かと思ったのですが、どのように進めていくのか、もう少し詳しくお知らせほしいと求めました。","respondent":"河内環境課長","answer":"チラシは大変重要なものであると認識しております。なかなか今この場ではお答えできなくて申し訳ないのですが、そのような考えの下にしっかり進めてまいりたいと考えております。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"相談連絡先をしっかりと、例えばこのようなことはどうなのですかという質問形式で載せていただくなり、また相談連絡先は。引き続き、環境に関する取組また強化もしっかりと進めていただきながらお願いをしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"確認","question":"大きな方向性の確認なのですけれども、ＳＤＧｓの取組で、大きな企業が再生可能エネルギーに切り替えた時期がありました。やはり次は事業者の取組を進めるべきではないかという方向で質問をした記憶があるのですけれども、その流れを、１回確認させてください。","respondent":"河内環境課長","answer":"ＣＯ２の排出係数についても、ぜひ検討していただきたいという中で、このようなものを新たにまた進めていただきたく提案させていただいたところです。品川区民の方は、環境意識も高いと認識しております。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"品川区のいろいろな施設でも、再生可能エネルギーでの電力契約が進んでいることは確認させていただいていて。５４か所となると、その後の契約書の確認が進んでいないのですけれども、その点についてはいかがか尋ねました。","respondent":"河内環境課長","answer":"そのようなムーブメントもうまく利用しながら、大幅な施設拡大に向けて、しっかりと発信していければと考えているところです。区全体のＣＯ２の削減に向けて、しっかり進めてまいりたいという考えはもちろんありますので、よろしくお願いいたします。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"それをみんなで確認するためにも、そのような資料は、ぜひ用意していただきたい。その辺のことも配慮して、私たちも一緒に確認しながら進めるというような資料の提供をぜひ進めてほしいと求めました。","respondent":"河内環境課長","answer":"それがＣＯ２の削減につながっているならば、是とするか、どうするか。バランスを取りながら、ぜひ進めて、やらせていただきたいと考えているところです。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、そのＣＯ２削減のための再生可能エネルギーを生み出す段階で、別のＣＯ２を発生させていたらしようがないわけではないですか。区議会としてもせっかくこのような委員会があるわけですから、そこで議論しながら、ぜひ今後その方向で進めていただけたらと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"ひがし委員","kind":"質問","question":"先ほどの質問に引き続きなのですけれども、ＰＲというところはとても重要だと思っていまして、この取組に品川区が参入するということ……。ほかに１０個の自治体はもう既にやられていると思うのですが、もし品川区が検討していることがあれば、併せて説明を求めました。","respondent":"河内環境課長","answer":"今、委員のおっしゃりたいこともよく伝わってまいりましたので、料金も下がりますというところで発信をしていきたいと考えています。万人の方にどう受け止めていただくかということはなかなか難しい課題とは思いますが、利用者の声も含めて、今後検討できればと思ったところです。","id":"exchange-020"},{"speaker":"ひがし委員","kind":"質問","question":"もし今回このプロジェクトを提携してやっていくのであれば、併せてその説明も少し言えるといいのかと思うのですが、そのようなことは検討されているのか尋ねました。","respondent":"河内環境課長","answer":"もちろん、その中でしっかりお伝えさせていただきたいと考えています。ぜひご利用くださいというところは、しっかり発信していきたいと考えております。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"マイボトル用給水機も質問していいですか。今、区でこのようにまた設置していこうということは、どのような意味合いでやっていくのかを説明を求めました。","respondent":"河内環境課長","answer":"重くてということもありまして、割と５００ccや７５０ccぐらいのマイボトルをお持ちになられると、すぐに空になるのです。地球環境などを考えつつ、こちらの大きな眼目になっておりますので、よろしくお願いいたします。","id":"exchange-022"},{"speaker":"須貝委員","kind":"提案","question":"ですから、そのようなところに、逆にその環境課で何かシールを貼らせていただく。そのようなこともすごくいいのかと思って、一応提案だけしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"鈴木副委員長","kind":"質問","question":"ほかにはいかがでしょうか。よろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"鈴木副委員長","kind":"確認","question":"報告が終わりました。本件に関しまして、ご確認等がございましたら、ご発言をお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"今回パブコメをやって、意見の件数が１３件ということで、この数について、区としての評価はどうされているのかというところを伺いたいと思います。この意見についての区の受け止めを伺いたいことと、単純にこれはパブコメの意見の３番のところで、そこを伺いたいと思っています。","respondent":"平原防災課長","answer":"別な機会でしっかりと説明していく、あるいは、しっかりと連携していくといったところは対応させていただきたいと思ってあります。そのようなことで対応させていただきました。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ説明会を実施していただいて、周知・啓発と住民の意見を聞いていただきたいと思うのですが、いかがでしょうか。やはりそのようなところをしっかり耐震化１００％の早期実現をしていくということを東京都に要望していただきたいと思うのですが、いかがか尋ねました。","respondent":"平原防災課長","answer":"こちらも、かつて委員会でご説明させていただきました被害想定でも、１０年間で被害発生率がかなり低減したというような成果で現れております。今後もそのようなものが進むように、東京都と歩調を合わせながらしっかり連携して進めさせていただければと考えています。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"在宅避難されているという方もいらっしゃるというところで、在宅避難への支援がさらに求められてくるのかと思うのですが、いかがでしょうか。寒さでもやはりかなりこたえるということになってくるので、段ボールベッドなどが必要になってくるのかと思うのですが、いかがか尋ねました。","respondent":"平原防災課長","answer":"東京都がかなり工学的手法で被害想定を出しておりますので、そのようなところに基づいて、しっかりと対応していくことが第一だと考えています。そのようなところが継続して在宅避難が可能となるように…","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"分析はこれからということですので、今回の教訓も踏まえて、震災関連死などもないように、未然に予防をしていくということも含めて、取り組んでいただきたいと要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"在宅避難体制に持っていきたいという表れがあるならば、備蓄なり、何なり対応を考えてほしいと私は思います。今回は結果についてですから、意見だけで終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"新妻委員","kind":"質問・要望","question":"この中にも明記していただきました令和６年度に各戸配布を予定している『しながわ防災ハンドブック』の改訂版でしょうか。具体的にどうしていったらいいのかということを、この中に反映をしてほしいと求めましたが、区のお考えを説明を求めました。","respondent":"平原防災課長","answer":"続きまして、令和６年度に配布予定のハンドブックのところです。今、感じているところでは、まず、もともと私どもがやろうとしていたことをしっかりと対応をしていくということが大事だろう。","id":"exchange-031"},{"speaker":"澤田委員","kind":"質問","question":"私からは、No.１１の4)についての質問です。福祉避難所の中で、非常用エレベーターが普通のエレベーター以外にもついているという施設はあるのでしょうかということが、まず１点。","respondent":"平原防災課長","answer":"今ご質問の福祉避難所に非常用エレベーターが通常のエレベーターと別にといったところです。私ども区役所内で共通認識として考えているところですので、そのようなところはしっかり施設側とも話し合ってまいりたいとは考えてあります。","id":"exchange-032"},{"speaker":"澤田委員","kind":"質問・要望","question":"高齢の方、車椅子の方などが避難する際に大事だと思うので、ぜひそちらの検討もしてほしいと求めました。福祉避難所ということを想定して、非常用エレベーターの設置などもぜひご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"平原防災課長","answer":"支援員などの考えをしっかりとして、どのような状況でも、しっかりとその方を保護できるように対応を考えてまいりたいと考えています。私どもとも協議がありますので、そのような中で、しっかりとお声を伝えてまいりたいと考えています。","id":"exchange-033"},{"speaker":"こしば委員","kind":"確認","question":"私からは、パブコメの３ページ、１１番の3)「防災区民組織の育成・強化や防災広場の整備について」お伺いします。確認なのですけれども、これはあくまでも町会や自治会の中での防災区民組織の強化を意味しているのかどうかをお答えください。","respondent":"平原防災課長","answer":"私どもは、もともと防災区民組織は、東京都の震災対策条例という、区でいう防災区民組織ですけれども、町会・自治会を母体としたといったところは何ら変わりございませんので、従来どおりの考え方の下での育成です。","id":"exchange-034"},{"speaker":"こしば委員","kind":"質問","question":"例えば地域センターを２つに分けるような、また隣同士の町会で、うまく補完し合うようなことも必要かとも思います。もう少し柔軟に組織・地域を今の状況に合わせて考えていくこともどうかと思うのですけれども、その辺りのお考えを説明を求めました。","respondent":"平原防災課長","answer":"今回の地域防災計画の一つの考え方の中に、前回の１１月９日の委員会で、ポイントの一つとしてご説明させていただきました。お話合いを進めながら、地域の問題点とそれに対する課題解決策を共に考えていただけるように、私どもはご支援してまいりたいと考えています。","id":"exchange-035"},{"speaker":"こしば委員","kind":"質問","question":"最小限の向こう３軒両隣のような本当に最小限の地域の交流といいますか、救助された方を見ていますと、事例としてはたくさん出ていると思います。そのようなことも是非お示しをいただければと思うのですけれども、それに対して、またお考えがありましたら教えてほしいと求めました。","respondent":"平原防災課長","answer":"欠かすことができないというか、地域の中核であると考えているところは、全く変わりはございません。小さな声かけから、それが共助の防災区民組織につながり、区民の命が守られるような体制をしっかりとつくってまいりたいと考えています。","id":"exchange-036"},{"speaker":"吉田委員","kind":"確認","question":"先ほどもご質問が出ていましたけれども、ご意見としては、福祉避難所の設置を急いでほしいということだけがシンプルに書かれています。庁内での福祉避難所が適切に機能するかどうかについての検討などということは、どのようにされているのかを確認させてください。","respondent":"平原防災課長","answer":"福祉部が所管して、そちらのところで施設の確認、あるいは施設管理者との話合いといったところを進めしています。私ども防災課は、意見を求められた際など、あるいは協議対象としてという形で入っていくというような関係性で進めしています。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"福祉計画の策定のときには、防災課は参加されていないではないですか。何か具体的に年に何回かは、そのようないろいろなところが連携した会議を持っているとか、そのようなことがあるのか伺いたいと思います。","respondent":"平原防災課長","answer":"福祉部が福祉部の所管として進めているようなことで防災に関することを、福祉面でも反映してほしいなどということを、そこですり合わせいく。ある程度検討を進めて、そのようなところでは、福祉部と私どもはしっかりと連携体制をつくっているところです。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"私の知識が全然足りなくて、そこまで確認できなかったなと、すごく反省した覚えがあるのです。既存の施設について、もし震災が起きたときのエレベーターの状況、防災課としてはその辺のことも把握されているのかを伺いたいと思います。","respondent":"平原防災課長","answer":"今ご質問の件につきましては、防災課ではなくて福祉部で把握するような形でやってあります。エレベーター協会とのつなぎであるなどの対応でという形になりますので、通常の部のほうで行わせていただくような形になってあります。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"今がどうあれ、しかも福祉避難所の場合、そこが福祉避難所としてのエレベーターの管理などをしなければいけないということがあるではないですか。具体的にどうなのかは、もう少し具体的な説明ができるように図っていっていただきたいのですけれども、その点についてお考えを伺いたいと思います。","respondent":"平原防災課長","answer":"ただ、先ほどご答弁を申し上げたとおり、施設設置に当たっては、今、私どもも話合いに参加するようになっております。平常時にできることはしっかり対応しますけれども、災害時の対応はそのときはそのときで、柔軟に対応させていただこうと考えています。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"障害者各団体から、災害のときについては、それぞれの障害種別によっていろいろな配慮を求められることのご要望が、各会派へ来ているかと思います。これは要望でとどめておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望です。私はやってほしいと思うのですが、１か所に集中することなく、その辺は検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"つる委員","kind":"質問・要望","question":"在宅避難に関連して、備蓄物資がしっかりとそのようなところに届くのかどうかということをまず教えていただきたい。区として、既にそのようなオフロード対応の車両等があるのかどうかも併せて説明を求めました。","respondent":"平原防災課長","answer":"在宅避難者は単純に考えても３０万人弱ということが見込める中で、率直に申し上げまして、現実的ではございません。様々なルートを考えまして、そのようなものに入れていただく等々のそのような連携をさせていただいて、構築しています。","id":"exchange-043"},{"speaker":"つる委員","kind":"質問・要望","question":"ただ、２０２２年の９月には、これは自衛隊ではない別のヘリで訓練をしたということがあると思います。そのような訓練が、来年度などを含めて、現状、考えの中に訓練そのものがあるかどうかということを一つ説明を求めました。","respondent":"伊藤災害対策担当課長","answer":"令和４年度に実施した東京都と品川区の総合防災訓練等々、今後そのような状況になりましたら、活用させいただければと考えています。孤立地域の活用がメインになってくるということもありますので、今のところ品川で考えられているところは、ほぼほぼないかというような状況です。","id":"exchange-044"},{"speaker":"つる委員","kind":"質問","question":"品川区でそれを使える場所というのは、今、何か所あるのでしょうか。品川区が確保できているヘリポートと臨時救助スペースについて把握していれば説明を求めました。","respondent":"平原防災課長","answer":"直ちには数字が手元にないもので、お答えは難しいのですけれども、複数は確保しています。たしか地域防災計画にその旨はしっかり記載しているかと思います。","id":"exchange-045"},{"speaker":"つる委員","kind":"質問・要望","question":"これは２００８年に、その状況を確認して、品川区に残っているかと思います。夜間や悪天候のときに、よく見えるのかどうかというその確認です。","respondent":"平原防災課長","answer":"防災課ではございません。施設によって若干違いがあると聞いてありますけれども、視認性に優れた素材を使うという形で聞いてあります。","id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"やはり７都県の基準に基づいて、蛍光のものなど、いろいろあろうかと思います。それは今言ったように教育委員会の所管で管理しているというところなので、そのような改善については、別の機会で求めていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"もしなければ、ぜひ今後検討していただきたいと、これは要望です。現状あるかどうかを説明を求めました。","respondent":"平原防災課長","answer":"自衛隊の練馬にあります第１普通科連隊、第１中隊が私どもの所管をしていただくということで、皆さんと様々な場面で顔を合わせる機会はあります。しっかりと連携を取らせていただいているつもりです。","id":"exchange-048"},{"speaker":"鈴木副委員長","kind":"質問","question":"よろしいですか。ほかにはいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"鈴木副委員長","kind":"確認","question":"報告が終わりました。本件に関しまして、ご確認等がございましたら、ご発言をお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"西村委員","kind":"提案","question":"訓練内容を共有する機会があれば伺いたいことと、訓練内容をご提案するような、紹介するような機会はあるのかを伺いたいと思っています。今はお隣の区などにいらして、そのような職員の方々が…","respondent":"伊藤災害対策担当課長、平原防災課長","answer":"この訓練の実施日に併せまして、防災備蓄ですとか、防災関係装備を説明するというようないわゆるカリキュラムをつくっていただきまして。先ほど説明をさせていただきました２月９日にあります連絡会におきましても… 例えば隣の区であっても、基本は６キロメートルという考え方で、参集できるかできないかという発想があります。ただ、なるべく継続性を持たせたいということが学校参集職員ですので、特段の事情がない限り…","id":"exchange-051"},{"speaker":"澤田委員","kind":"質問・要望","question":"共助は本当に大切だと思うので、共助の観点からも、ぜひ推し進めていただけたらという要望です。一緒に訓練できるように動いていくことが大切なのではないかと思うのですが、その点についてはどう思われますか。","respondent":"伊藤災害対策担当課長","answer":"今回の夏から秋にかけまして実施をしました地区の総合防災訓練につきましては、訓練場所には手話通訳ができる方を配置してございました。私が把握している限りではそのような方が参加されていて、少しずつ増えていってくれればいいと考えている次第です。","id":"exchange-052"},{"speaker":"澤田委員","kind":"質問","question":"そうしましたら、例えば指さしのプレートを用意するなどという工夫も今後ご検討してほしいと求めました。いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"今回、手話通訳だけではなくて、外国の方も参加されていたりしまして、少し準備が足りないというところもございましたので、例えばボードで多言語ができるものなどといったところも併せて用意をさせていただければと考えています。","id":"exchange-053"},{"speaker":"ひがし委員","kind":"質問","question":"今、把握できている範囲で２名ほど参加されているということだったのですけれども、なかなか行けなくてというところのご意見がありました。まだ１回目だから、ぜひ幅広く参加していただいたほうがいいのかと思うので、その点について何かお答えがあれば説明を求めました。","respondent":"伊藤災害対策担当課長","answer":"障害者支援課のほうとも連携をいたしまして、今回は、私のほうでは２名の方が参加されるということで対応をさせていただきました。次回以降につきましても、関係する課と連携をさせていただきまして、できる限り多くの方が参加できるように準備を進めていきたいと考えています。","id":"exchange-054"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この結果を見てみて驚いたのですけれども、５０歳未満の方々が９％ということで、１割にも満たないということ。子どもは参加しているけれども、そこについての課題や取組は何かされているところがぜひ教えていただきたいと思うのですが、いかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"親子世代だとか、そのような方が参加できるような何かイベントではないですけれども、人を引きつけるような訓練。そもそも少し厳しめのものなのかもしれませんが、少し人を集められるようなものをできるように、今後も検討してまいりたいと考えております。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"「訓練に参加していない方にどうやって伝えていくか」ということと、「若い人にもっと参加してほしい」ということで書いてありました。一番多いところで豊葉の杜学園で１,０２４人ということで、訓練内容などはどのような訓練されたのかというところも伺いたいと思います。","respondent":"伊藤災害対策担当課長、平原防災課長","answer":"このようなものを取り入れたほうがいいなど、もちろんできる、できないということはあります。今回の児童が参加したところについては、少し多めに人数が出ているのかと考えています。 その中で、最初の頃は町会の方々だけでどのように支援計画つくっていこうかという話合いだったのですけれども、一緒に。今後もそのような取組を広めながら、顔合わせといったところを進めてまいりたいと考えています。","id":"exchange-056"},{"speaker":"新妻委員","kind":"質問・要望","question":"今もお話がありましたけれども、いただいたお声に関してはしっかりと反映をしていくということの認識でよろしいのでしょうか。乳幼児向けのものがあるといいのではないかとか、このようなことを具体的に反映していただけるのかどうかお伺いをいたします。","respondent":"平原防災課長","answer":"もう１点、備蓄物資の件です。どのようなものを拡充していくか、強化していくかといったところのしっかりと基礎資料とさせていただければと思ってあります。","id":"exchange-057"},{"speaker":"新妻委員","kind":"質問・要望","question":"１回１回の訓練が非常に大事でありますし、本当にその地域に合った、実のある訓練を今後もやっていかないといけないのではないかとも思います。本当に命を守るために避難ができる訓練をぜひ心がけてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"吉田委員","kind":"提案","question":"私個人的な意見としては、町会以外でも何人かグループになったら、ぜひ講師派遣をお願いしたいということをいつもお願いしています。町会が参加されているわけですから、提案されるということは、実際そのようなことはされているのかを伺いたいと思いますとの意見を述べました。","respondent":"伊藤災害対策担当課長","answer":"やはり地域特性というものもあろうかと思いますし、やはり町会のほうで、ここの区でやりたいというような要望もあると思います。そのようなところを活用して、訓練の内容につきましては決定をして、よりよい訓練ができるように進めてまいりたいと考えています。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"図上訓練の１個になると思うのですけれども、図上訓練ですから、可能なわけです。このようなものはどうですかといっても、そのまま実現するかどうか分かりませんけれども、もし何かお考えがあったら伺いたいと思います。","respondent":"伊藤災害対策担当課長","answer":"積極的に訓練のほうには行けると思いますので、ご要望があれば、検討させていただければと思います。見直しのほうは、検討させていただければと考えております。","id":"exchange-060"},{"speaker":"吉田委員","kind":"提案","question":"提案の強さはどの程度、もし提案があれば参加するという心積もりになっているのであれば、今後ぜひ有効に活かしてほしいと求めました。これは要望でとどめますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"何点か端的にお伺いします。ほかの学校では、駄目なのですかというような圧というとあれですけれども、ここの濃淡を埋めたほうがいいと思うのです。","respondent":"伊藤災害対策担当課長","answer":"どのようなメニューになるかということを含めて、さらに検討をさせていただければと思います。２年に一遍しか参加できない訓練ですので、しっかりと地域の町会の皆様と連携をして、未来の品川区を支えていただく。","id":"exchange-062"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"動ける人たちが基本ですから、所管を超えないと難しい部分もあるのだと思うのですが、ぜひこれもやってみてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"須貝委員","kind":"質問","question":"ですから、そのような方たちに何とか来ていただくような手法を取る。これは意見だけなので、してくれとは言いづらいので、一応意見だけを言わせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"鈴木副委員長","kind":"質問","question":"ほかにはご意見いかがでしょうか。よろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"鈴木副委員長","kind":"意見","question":"次回２月２９日の委員会における特定事件調査は、災害廃棄物処理計画を取り上げることで調整をしていますことをお伝えいたします。○午後 ４時１０分閉会との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/949666?Template=document&Id=6648#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":65645,"voices":144}},{"id":"r06-20240125-10","meetingId":"r06-cm01","date":"2024年1月25日","dateIso":"2024-01-25","committee":"議会運営委員会","time":"午後 １時００分～午後 １時４４分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"今、継続して検討中で、まだ結論が出ていないです。やはり前回も申し上げたように、二次被害を防ぐという観点からどうなのかというところで今継続して検討中で、今の時点ではそんな状況ですとの意見を述べました。","respondent":"渡辺議長","answer":"そういったことで、今、副議長とも私たちがどういう対応をすればいいかを相談しているところです。それに関して、ご意見があれば承りたいと思うのですが、そういう意見をいただきながら正副議長で対応を協議していきたいと思っています。","id":"exchange-001"},{"speaker":"須貝委員","kind":"意見","question":"ただ、今、議長からもお話のあったとおり、中塚議員の真意というのはどうなのだということ。議長のほうから本人に真意を尋ねていただいて、やはりそれなりの対応は取らせていただきますと明確にお話ししたほうがいいのではないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"塚本委員","kind":"提案","question":"議長のご提案である中塚氏からお話を聞くというのは、なされるべきだと思います。ここは当事者からの話を聞く場面というのがないと、バランスが悪いというところもありますし、そのような形で進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"やはり一方から聞いて、一方から聞かないというのは問題になりかねませんので、しっかり聞いていただきたいというのがまず１点。多分、そういう会議体をわざわざルールとしてつくっていないのだろうと思うので、そこも含めて正副議長に一任をしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"松永委員","kind":"意見","question":"私どもも、先ほど須貝委員、公明党、自民党がおっしゃったように、まず早期に議会としてしっかりやっていかないといけないと考えています。共産党は共産党で進めていただくほうがいいのかと思っておりまして、そこに関しては、正副議長と正副委員長にお任せしたいと思いますとの意見を述べました。","respondent":"渡辺議長","answer":"先ほど、須貝委員もおっしゃっていたように、やはり放置するのではなく、議会としての速やかな対応をまず第一に意識しながら進めたいと思います。１点だけ、特に辞職を求めるというところが見出しになっていたかと思うので、その辺の変更点はないわけですよね。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"本当に重ね重ね、あってはならないことで、こんな事態になってしまったということは申し訳ないと思うのですけれども、辞職すべきだし、私たちも辞職を求めてきたという前提では、前回の見解と何ら変わりがないです。","respondent":"あくつ副議長","answer":"冒頭、二次被害というところを考慮してご検討中だというお話がありましたが、このご発言があってから１か月が経過をしました。この点について、ご検討というのはいつぐらいまでにされるのか。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"辞職するべきようなことではないということになって、反省していないということになりますので、当然それは許されないと被害者の方も思っているです。これ以上は、見解以上のことは述べないという立場ですので、控えさせてほしいと求めました。","respondent":"渡辺議長","answer":"皆さんも含めてなのですが、まず看過できない内容であるということで、速やかな対応をとる。ちなみにこの対応は何かといったら、まず事実確認をしなければと。 ご一任という話もあったのですが、やはりこれは議会全体のことと捉え、議長・副議長でまず窓口を一本化して対応をしていきたいと思います。対応の内容、どんな場がふさわしいかとか、あと…","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"これに対して共産党は議員辞職を求めたということで、我々はその事態、その事象に対してどうあるべきかということでいいのではないですか。突っ込んだ話になると、やった事象に対して議員辞職を求めたということを我々は素直に受け止めて持っていけばいいのではないかと思います。","respondent":"渡辺議長","answer":"今のご指摘も踏まえて、まず、議会の範囲内というのが、これは私も限界だと思います。いろいろな意味で限界もありますが、まず責任を持てる議会の範囲内で、第一歩、対応をしていきたいと考えています。","id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"せっかく今回提案いただいたので、一応会派でも話し合いたいと思うのですけれども、今はそう思っています。代わりにペットボトルが並ぶとなると、これは区民の理解を得られないと思うので、そこら辺は目線を考慮したほうがいいのかと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"須貝委員","kind":"提案","question":"議長の提案は、私はすばらしい提案だと考えています。私は議長の提案はすばらしいと思うので、ぜひ、いい方向に進んでいただければいいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"こんの委員","kind":"提案","question":"細かいことで大変恐縮なのですが、確認です。今後、予算特別委員会から実施されたらどうかというご提案なので、その辺のイメージを確認させてくださいとの意見を述べました。","respondent":"渡辺議長","answer":"まず、議会運営委員会でお諮りして、議会運営全般の共通認識をもって進められたらと思います。今日はそのための、まず、今日段階でのヒアリングをいただければという感じです。","id":"exchange-011"},{"speaker":"山本委員","kind":"提案","question":"当会派としても、いい提案だと思っておりまして、基本方針としては進めていただきたいと考えています。は、そういう細かなところについては適切な形で進めていただきたいと思っているところで、進めることについて賛成ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"せりざわ委員","kind":"提案","question":"ご提案いただいたところは全て賛成ですので、ぜひ進めていただきたいというところと、どんどんしっかり水分補給してくださいというような空気づくりを議会で進めていただければと考えていますとの意見を述べました。","respondent":"渡辺議長","answer":"進め方のところだけ、安藤委員からもありましたように、今日拙速に結論を出すのではなく、一回持ち帰る形にしたいと思います。そして、よろしいでしょうかというのを委員長に確認いただいて、私の発言は終わります。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=5534#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":14617,"voices":65}},{"id":"r06-20240219-10","meetingId":"r06-cm02","date":"2024年2月19日","dateIso":"2024-02-19","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"令和６年第１回定例会","agenda":"令和６年第１回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"新庁舎について１点だけお伺いしますけれども、先日の議員対象の説明会でも実際の工事の着手時期は来年、２０２５年の半ばくらいと示されていたと思うのですが、この位置条例をなぜ今回の第１回定例会に提出するのかという理由だけ伺いたいと思います。","respondent":"桑村副区長","answer":"先日は、いわゆる非公式の場ですけれども、ご説明をさせていただきました。令和６年度は実施設計に入るという、非常に細かい中身の設計に入ってまいりますので、ぜひお願いを申し上げるものです。","id":"exchange-001"}]},{"id":"topic-02","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"お願いというか、一つは、意見表明の原稿提出の締切なのですけれども、３月２１日ではないですか。何かあればぜひご見解をいただきたいです。","respondent":"大澤区議会事務局長","answer":"原稿提出につきましては、事務局と正副委員長とでまた検討させていただければと存じます。","id":"exchange-002"}]},{"id":"topic-03","title":"品川区議会委員会条例","agenda":"品川区議会委員会条例","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"賛否の態度は別の機会になると思うのですけれども、私たちとしては、組織改正条例に反対した立場上、提案者になるかどうかということも含めて、また検討させていただきたいと考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"どうしたのだ、議会のほうでいろいろ本人に確認したりして対応を進めていますということで話をしたら、どうもそういうようなことで。できれば、議員辞職勧告決議案を出すべきではないかなと私は思いますので、その方向で進めていただければありがたいなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"事実関係はいろいろ確認できたとはいえども、今後の進め方について、ぜひご意見をいただきたいなと思っています。考えを全く聞かずして、やりましょうという話にはなり得ないかなと思いますので、まずはこの場で共産党のご意向を教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"２月８日の意見聴取の場では、これを行ったということを全て認める発言を、そうした皆さんの前で改めて行ったということでした。共産党としては、ぜひ議会全体で議員辞職勧告を行うということで検討を進めていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"確かに辞職勧告を求めるというような事案に当たるかもしれないということもあるとは思いますが、まだはっきりしていないというのが実情です。確認しなければいけない分からないことというのが多過ぎるというところがあるので、ここはやはり共産党から出していただくということが。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"松永委員","kind":"質問","question":"中塚議員のご説明をいろいろお聞きした中で、議会全体で辞職勧告を出すというのは、私たちの会派はちょっと難しいかなと思います。そのときはぜひ共産党から提出いただいたほうがいいかなという結論に至っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"共産党としては、議会全体で決議を出していただきたいというお話だったと思います。これは要望として、終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"どうだということよりも、これは議会として一緒に出そうということになれば、ぜひ出していただきたいなと。よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"延ばせば延ばすほど、我々はそのことに対して何も対応していないのではないかと見られるのが、これはやはり区民の感情ではないですか。区民の皆さんからやはり信用を今までとっているのですから、決して裏切るような行動はしていないにしても、そう見られてしまう。","respondent":"渡辺議長","answer":"オール議会という形で進める案件だと思っています。共産党とともに須貝委員のほうで案文作成にご協力いただけると、ただ今のご発言のように速やかな展開に移れるかなと思いますが、いかがでしょうか。","id":"exchange-011"},{"speaker":"須貝委員","kind":"意見","question":"そういうことを議長が認めるということを前例として残していいならば、そういうふうにしたいと思います。すみません、つくっていいということを議会運営委員の皆さんが承認されるなら、そういうふうにさせていただければありがたいと思いますとの意見を述べました。","respondent":"渡辺議長","answer":"前例というものがあまりないケースなので、フォーマットなどというよりは、事実に基づいて作成を。あくまでも案文ですから、それを皆さんにまたご意見を伺うということで、それが大きな一歩になると思いますので、ぜひともお願いいたします。","id":"exchange-012"},{"speaker":"須貝委員","kind":"提案","question":"議長から、飲料の持込みについて実にいいご提案がありました。それはすごくいいことなのかなと思う反面、費用の面もあるので、設備とか、その辺についてご検討くださるかどうか、提案しますとの意見を述べました。","respondent":"渡辺議長","answer":"とても前向きなご提案なので、大事に受け止めまして、相手のある話ですが、ぜひ交渉したいと思います。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=5536#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":17312,"voices":70}},{"id":"r06-20240220-10","meetingId":"r06-cm02","date":"2024年2月20日","dateIso":"2024-02-20","committee":"議会運営委員会","time":"午後 ０時３０分～午後 ０時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=5538#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":1524,"voices":12}},{"id":"r06-20240222-3","meetingId":"r06-c-budget","date":"2024年2月22日","dateIso":"2024-02-22","committee":"予算特別委員会","time":"午前１１時５２分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664001?Template=document&Id=6683#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":1949,"voices":17}},{"id":"r06-20240226-6","meetingId":"r06-cm02","date":"2024年2月26日","dateIso":"2024-02-26","committee":"区民委員会","time":"午前１０時００分～午後 ０時５６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件整理しています。","topics":[{"id":"topic-01","title":"第１７号議案、品川区手数料条例の一部を改正する条例","agenda":"第１７号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"幾つか確認をさせてください。少し見てみたのですが、調べきれなかったのですけれども、なぜ３月１日からの法令改正なのかということです。","respondent":"吉野戸籍住民課長","answer":"３月１日なのですけれども、これは国からの説明はなかったのですけれども、その前にこの施行をという形になったかと思われます。こちらは以前ご説明したパスワードみたいなものなのですけれども、今まで戸籍証明書、添付せずに済むというようなものになります。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"前段の部分は国のことだから、恐らくそういうことなのかなとは思うのですが、私もちょっと調べきれなかったので伺いました。これには例えば期限みたいなものがあるのかどうか、例えば具体例としてどのようなものがあるのかということだけ少し確認させてください。","respondent":"吉野戸籍住民課長","answer":"その前のままの戸籍を参照することになってしまいますので、やはりその都度、識別符号は発行し直したほうがよろしいかと考えています。それ以外のものについての連携のためのものになりますので、こういったところで戸籍証明書の連携を図るというような仕様になっています。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"一例で、何かパスポートに添付するようなものにもこの戸籍電子証明書識別符号が使えるというようなお話もあったと思うのですが、これはいつ頃の運用になるかというのは、国から情報が来ていますか尋ねました。","respondent":"吉野戸籍住民課長","answer":"これは各省庁のシステム改修によるものみたいで、法務省では既に準備ができてはいるのですけれども、今おっしゃったパスポートであったりとか、そういったもののシステム改修次第になります。","id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"新旧対照表の５ページから７ページに書いてある部分の確認なのですけれども、手数料は無料ということでよろしいのでしょうか。マイナポータル経由で申請される場合も無料になるということなのですけれども、品川区も同じような形でよろしいのか、その辺りを確認させてください。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおりでして、例えば紙と電子とを発行した場合には、いわゆる電子のほうは無料になります。マイナポータルを使っての申請の場合も、今現在は改修中なのですけれども、こちらのほうも無料になる予定です。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"委員長に質問なのですが、建築課長の説明というのはこれからあるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"建築課長に質問しますが、都市環境部関係の（５）の説明で、今日この区民委員会に出席してくださっていると思うのです。この「等」の部分が一番の変更だと思うのですけれども、この「等」の部分について説明していただけますか。","respondent":"長尾建築課長","answer":"改正された法令名称の中で変わっている部分は、おっしゃるとおり「等」というところが追記された部分だけになります。今後は創エネ、その発電、創エネの部分も含めるために「等」が追加されたということになっております。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問","question":"今、発電という話でしたけれども、その発電というのは具体的には、例えば太陽光パネルとかそういうふうに考えてよろしいのか尋ねました。","respondent":"長尾建築課長","answer":"おっしゃるとおりです。太陽光発電、あと太陽熱の利用とか、そういったものが想定されております。","id":"exchange-007"},{"speaker":"山本委員","kind":"質問","question":"私からも１点質問させてください。３月１日から改正されて、事前にどのように周知されて、職員の皆様に認識していただいているかということについて説明を求めました。","respondent":"吉野戸籍住民課長","answer":"今回、広域交付というのは新たなシステムになりますので、もう大分前から地域センターを含めてシステムの研修をやっているところです。はこの料金の部分での設定も、今進めているところです。","id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"新しいこういった大きな変化、それから手数料をいただくですので、くれぐれも、遺漏のないように進めていただきたいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-02","title":"令和６年陳情第１８号、デジタルアプリをクリエイターに支援するための陳情","agenda":"令和６年陳情第１８号、デジタルアプリをクリエイターに支援するための陳情","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"その辺についていかがでしょうか、というのがまず商業・ものづくり課長への質問です。文化観光課長、ぜひ教えていただきたいのですが、「映画産業が集中」と陳情に書いてあるのだけれども、実際に映画産業が集中しているのか尋ねました。","respondent":"小林商業・ものづくり課長、篠田文化観光課長","answer":"ソフトウエアが値上がりした部分について、５万円は例示だとは思いますが、支援を求めるご意見と認識しております。ＤＸを更に推進するような動きであれば、それに対応した補助金がありますので… それに関係する映像会社があってというのが映画産業なのかなと捉えると、そういった産業が五反田に集中しているという認識はございません。ただ、五反田バレーの中で様々映像に関わる企業がいろいろと出てきているというのは…","id":"exchange-010"},{"speaker":"藤原委員","kind":"意見","question":"これは行政という言い方はおかしいかもしれないけれども、やはり資金を入れていって支援してすごく大きくなったというのがあるのです。２０４５年はシンギュラリティが来ると言われている中で、品川区を特徴とする大きい産業となっていくと思うので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"せらく委員","kind":"意見","question":"今回個々で助成を行うのは、行政として支援するのは難しいところがあると感じておりまして、ただ、物価高騰・エネルギー価格高騰の支援として、今、銭湯や運送業への支援をしていると思うのですけれども…","respondent":"小林商業・ものづくり課長","answer":"エネルギーについて冒頭の説明で申し上げましたけれども、業種全般に幅広く影響を受けているというところを考えております。区が中小事業者や個人事業主の方が資金調達される際の援助をするといった対応により事業者負担の軽減も合わせ技でやっているところです。","id":"exchange-012"},{"speaker":"えのした委員","kind":"質問","question":"映画産業がどこまでとか、集中は認識していないというお話があって、この陳情の「クリエイターを生業にしている小規模事業者の区民は現在でも多い」というのは、区としてはこの小規模事業者のクリエイターの方が何名程度いるのかというのは把握していらっしゃるのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"産業分類において、このクリエイターが個別に何人いるかというのはちょっと難しいですけれども、区内には全体的に約２万の事業者がいる中で、こういった個人事業主、特にクリエイターという方も最近デジタルの取組が増えている中で一定程度いらっしゃるのかなと考えています。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"こちらを利用している事業者の方々の業種というのは主にどういったところが多いのでしょうか。そして、そのデジタル関連の事業者の方がどのぐらい利用しているかというのがお分かりでしたら、教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"建設業まで、特に業種を特定のところに絞ってというものではございませんので、幅広くいろいろな業界の方に使っていただいているです。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点ほど確認させてください。しかも企業同士のやり取りですから、その中に陳情に例示があるようなアプリというものも含まれるという認識でいいのか。","respondent":"小林商業・ものづくり課長","answer":"１点目、この陳情に出ている、人件費などいろいろなものも含まれる中で値上がりの動きが出てきているのかなという認識を示したものです。区として五反田バレー支援ですとか、スタートアップ支援といったときに、五反田バレーを支援していく中で。","id":"exchange-015"},{"speaker":"横山委員","kind":"確認","question":"先ほどＳＨＩＰで一部アプリの操作指導をやっているということだったのですけれども、どういったアプリの操作指導等をやっているのかというところを確認させてください。","respondent":"小林商業・ものづくり課長","answer":"先ほどの私の説明の中で、ソフトウエアの操作指導というお話を申し上げました。ＳＨＩＰによるものづくり・製造業の支援の過程で、いわゆるクリエイター支援という必ずしもダイレクトではないのですけれども。","id":"exchange-016"},{"speaker":"あくつ委員","kind":"確認","question":"先ほども確認させていただきましたが、品川区として税金投入をして支援をするというのには、やはり理由が必要であろうというところ。ＩＴのことについて力を入れていくというのは今の質疑の中で確認をさせていただいて、なかなか現時点では、ちょっとなかなか厳しいのかなです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"それぞれの支援策については、クリエイターの皆様にもっと使っていただけるように周知していただきたいと要望したいと思います。これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"藤原委員","kind":"意見","question":"採択と言うと５万円出してくださいというふうになってしまうのだけれども、だから５万円となってしまうと、という思いはあるのです。ですので、趣旨採択しますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"せらく委員","kind":"質問・要望","question":"そういった相談などニーズを把握する上でも、クリエイターや個人事業主の皆様にいろいろな支援の提供をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"私は、豊かな文化芸術活動が区民のウェルビーイングにつながっていくと考えています。都、そうした問合せがあった際には情報提供をお願いしたいと思っていますので、お一人おひとりのご事情に寄り添った対応を引き続きお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"}]},{"id":"topic-03","title":"児童見守りシステム（まもるっち）のリプレイス","agenda":"児童見守りシステム（まもるっち）のリプレイス","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"その予備期間として、入学式がたしか８日でしょうか、そこだけ少し余裕をもって期間を設けられているのかなというところ。まもるっちがない期間なので、特に周知を行ってほしいという、これは希望ですけれども、こちらをお聞かせ願えますか尋ねました。","respondent":"河合生活安全担当課長","answer":"各ご家庭で事前にどう対応するかを検討していただくために学校経由の連絡網で周知しているとともに、私立・国公立関係、周知を行っております。ホームページにも載せて、各ご家庭で対応していただけるように、事前に早めに準備しています。","id":"exchange-022"},{"speaker":"えのした委員","kind":"質問","question":"もう周知されているということで、安心しました。先ほどの１点、２日の午前７時半以降から入学式までの、その間で対応ができるということでよろしいのか尋ねました。","respondent":"河合生活安全担当課長","answer":"やはり速やかに対応するというところで、その期間、安全・安心確保に向けて努める予定になっています。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"何点か確認をさせてください。これにはどういう背景があるのか、既存のこの契約期間がちょうど満期を迎えてのリプレイスの対応なのかという背景を教えていただきたいです。","respondent":"河合生活安全担当課長","answer":"この３点柱を解消するにはどうしたらいいかというところでシステムベンダー等を含めて検討した結果、この形でシステム改修をするという経緯です。５年契約でこの２,６００万円というところのペイというところでは考えていなくて…","id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"コストの点については、それ以外の付帯効果があるので十分メリットが取れるということで理解をいたしました。しっかりとこれを進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"せらく委員","kind":"質問","question":"システム移行に伴うサービスの一時停止については、ホームページというのはどこのホームページで公開をするのかという点をお聞きしたいです。新１年生になると、その手続きの際に、保護者が何かしていくことが今後出てくるのかどうかをお聞きしたいです。","respondent":"河合生活安全担当課長","answer":"学校連絡会のほうで既に説明会が始まっておりまして、区立学校につきましては学校から配布されるという形になっております。私立・国公立関係の方は個別で区役所に来ていただくような形で、申込みと配布を行うというところで周知をしています。","id":"exchange-026"},{"speaker":"せらく委員","kind":"質問","question":"新規契約の部分では、これまでになかった手続きを新たに踏まなければならないというような状況にはならないという理解でよろしいでしょうか。新規契約の部分だけご答弁をお願いします。","respondent":"河合生活安全担当課長","answer":"新規契約の手続きにつきましてはまだ新年度前になりまして、新たな手続きというのは発生いたしません。学校側には最後のそういった取りまとめといいますか、新年度前ですので、そういった申込みの手続きは学校側にお願いしているところになっております。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"今日この場で数字がどうだということは伺わないのですけれども、担当課として、そこはしっかり押さえておいていただきたいと思うのです。その辺についてはいかがか尋ねました。","respondent":"河合生活安全担当課長","answer":"委員ご指摘のとおり、予算も大きな配分になっておりまして、その効果はしっかり把握しなくてはいけないということは私も認識しております。危険な事態があったときにどのように使われているかとか…","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"誤作動があったとか、そういうことをちゃんとつかんで、これだけ効果があるのですということは把握しているのですねということを伺ったのです。コストダウンしましたではなくて、コストがかかるものはかかるのだから、だからそれは議会にかけて予算をつけて承認していくわけですから。","respondent":"河合生活安全担当課長","answer":"緊急で児童の安全を確保する必要があるということで対応したのが、そこから事案に応じて、全体のシステムから対応しているのですけれども。やはりシステム上のそういったところでずっと惰性で行くことはありませんので…","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"８万件というのはすごい数字ではないですか。その辺の思いを最後に伺いたいと思います。","respondent":"河合生活安全担当課長","answer":"私も事案が入るたびに指揮をしておりますけれども、そこは事案対応する指揮者としては引き続きしっかりやっていきたいと考えております。システムがよくても事案にどう対応するかで全然違いますので、指揮者としてしっかりやっていきたいと考えております。","id":"exchange-030"},{"speaker":"横山委員","kind":"質問・要望","question":"今、もし何かそういった追加のスケジュール等がありましたら、その辺りの確認をさせていただきたいと思いました。まもるっちが停止する期間、どのような体制で子どもたちの安心・安全を確保されるのか、その辺りの体制について確認させてください。","respondent":"河合生活安全担当課長","answer":"ちょっと説明が不足しましたけれども、従来の新１年生の手続き、学校の協力をいただきまして行うという形になっております。まもるっちがその間使えないというところになりますので、そういったところの警戒もお願いする形で、連携しながら対応したいと考えております。","id":"exchange-031"}]},{"id":"topic-04","title":"令和５年度八潮地区まちづくり事業の進捗状況","agenda":"令和５年度八潮地区まちづくり事業の進捗状況","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"これが品川区でやられているのか、それとも他区の事例なのか、それを教えていただきたい。これは先ほど大学生のグループが活動されているというお話でしたけれども、やはり２０代・３０代の方は現状少ないのかというのを説明を求めました。","respondent":"中西八潮まちづくり担当課長","answer":"ＬＩＮＥですが、これは八潮で取組を進めているものでございまして、注意喚起をするというような形を取組として始めているといったものです。ただ、今おまつりですとかイベントを通じて少しずつ関係性ができてきた方がいますので…","id":"exchange-032"},{"speaker":"えのした委員","kind":"質問・要望","question":"たしか防災タブレットの活用が八潮のほうはかなり活発だというお話を以前伺ったことがありまして、また先ほどのまもるっちのお話に戻りますけれども。そういった情報が地域の方に届くというシステムの取組をお考えいただければと、これは私の要望ですけれども、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"最後に、先ほど２０代・３０代の方々に声をかけて、その大学生の方たちは八潮に住んでいるということなのでしょうか。それとも、住んではいないけれども、ふるさととして何か参画をしているということなのか、四つお伺いいたします。","respondent":"中西八潮まちづくり担当課長","answer":"今後進めていく中で、参加者として入っていただこうかというふうに考えているところです。私の説明が曖昧で申し訳なかったのですが、今も八潮団地に住んでいる学生で、大学の仲間に声をかけてくれて出店してくれたといったのが実情です。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"確認","question":"築４０年ですから地場のマンション等を見ていても、今後の流れがスムーズなのかなというところで質問させていただきました。ガイドラインの中でどう反映されているのか、それを最後に確認させてください。","respondent":"中西八潮まちづくり担当課長","answer":"ガイドラインを見ると、ワークショップをやった中でも、やはり夜が暗い部分があるとか、そういったご意見は出されているという記載があります。こういうふうに変えていきましょうといったところまでは行き着いていないという認識を私は持ってありますので…","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問・要望","question":"防犯について伺いたいのですけれども、八潮地区における防犯カメラの設置はどうなっているのでしょうか。資料の１、「人口の高齢化等により、地域ニーズが変化・多様化している」とあるではないか尋ねました。","respondent":"中西八潮まちづくり担当課長","answer":"すごくたくさんつけていらっしゃる自治会、管理組合の号棟もありますし、まだまだつけ切れていないような号棟もあるかなという認識はしています。つけていただくですとか、あとは自治会を通して区のほうに補助の申請をしていただくという形で…","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"よかったです。なぜなら八潮の住民ですからね。","respondent":"中西八潮まちづくり担当課長","answer":"そのＪＫＫの建物であれ、そこに自治会がありますので、そこのメンバーに八潮みらい懇談会に入っていただいております。地域住民の方に関しては入っていただいております。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"八潮という意味と、せっかくお隣に生活安全担当課長が座っているわけですから、やはりこれは防犯という意味でやっていかないとと思っています。それと橋等の防犯カメラの連続性、その辺についてはどのように考えるか説明を求めました。","respondent":"河合生活安全担当課長","answer":"八潮団地に入るところに、まだちょっとその八潮地区で自治会連合会、その地域でというところではそういったことが難しい状況であります。自治会連合会での設置はちょっと難しそうなところもありますので、区としても研究していく必要があるかなというところはあります。","id":"exchange-038"}]},{"id":"topic-05","title":"住民基本台帳事務における特定個人情報保護評価の実施結果","agenda":"住民基本台帳事務における特定個人情報保護評価の実施結果","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"構成員の方が３名いらっしゃって、私も調べたら弁護士の方で、これは公表されているのでしょうか。言ってしまっていいのか尋ねました。","respondent":"吉野戸籍住民課長","answer":"大丈夫です。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"別紙２の最初のところの、これは多分問いとしては、印鑑登録事務というのは住民基本台帳法に定められた事務ではないですよと。どうなのでしょうかと聞かれていることに対して、その読み取れるところを見ると、もう少し説明していただいてもよろしいか尋ねました。","respondent":"吉野戸籍住民課長","answer":"その中で、これは住民基本台帳法に基づいてやっているものなのだけれども、なぜ印鑑登録がこの評価書に記載されているのかというようなご質問でした。これに関しましては、それで印鑑のそういったシステムを記載させていただいたという次第です。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"例えばコンビニ等でマイナンバーカードで印鑑証明が取れるというのは印鑑登録証としての機能があるからということで、その印鑑登録証の機能というのは住民基本台帳事務に関わるそのデータを使っているから、評価をしていただいて結構なのですよということでよかったか尋ねました。","respondent":"吉野戸籍住民課長","answer":"委員のご認識のとおりです。","id":"exchange-041"}]},{"id":"topic-06","title":"臨海部広域斎場組合施設整備基本方針（案）","agenda":"臨海部広域斎場組合施設整備基本方針（案）","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、逆に教えていただきたいです。なぜ２０６０年から２０６４年が火葬需要が最も高まる年度なのかという根拠を説明を求めました。","respondent":"吉野戸籍住民課長","answer":"こちらの資料なのですけれども、３ページに人口ビジョン数値に基づいて推計した数になります。委員のご指摘のとおり、人口ビジョン数値に基づいた結果では、２０６０年になるというふうに結果が出ている次第です。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"だけど、人口ビジョンでそう出ているのですからね。私も１００歳を越えられるなという思いを楽しみつつ、この質問はこれで終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"これは炉については１０基というところで、もうこれ以上は増やさないということなのですか。その辺りを説明を求めました。","respondent":"吉野戸籍住民課長","answer":"今回の増設は、今の敷地の中の駐車場を使って増やしますので、これ以上増やす予定は今のところありませんが、あと１０基、要は計２０基になれば、先ほどご質問いただきましたが、この一番の死亡率が多いところは全て対応できるというような試算になっております。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"確認","question":"もう一回確認なのですけれども、最初のところのまとめのところでは１０基増設し、合計２０基とするとあるのですけれども、今回に関しては、これは２０基になるということでよかったのでしたか。","respondent":"吉野戸籍住民課長","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"ではこれで余裕をもつということですか。ここの待合室の増設で、それによって待機時間が短くなるという、そういった理解でよろしかったか尋ねました。","respondent":"吉野戸籍住民課長","answer":"委員のご認識のとおりで間違いありません。","id":"exchange-046"},{"speaker":"横山委員","kind":"確認","question":"現状どういう形でこのように記載されているのかを確認させてください。普段は１９基を稼働して、予備炉は何かあったときにという形の運用になっていくという考え方でよろしいのかどうか、まずそこから説明を求めました。","respondent":"吉野戸籍住民課長","answer":"今、炉の回転数を３.５回転で計算しているのですけれども、非常時には４回転、５回転というような対応も可能であると聞いております。それから二つ目のお伺いですけれども、２０基のうち１基、これは運用予備炉として、１９基で動かすという計算になります。","id":"exchange-047"},{"speaker":"横山委員","kind":"確認","question":"１９ページなのですけれども、こちらも私が勉強不足の部分があるのですが、斎場の耐用年数は４０年間という形なのでしょうか。こちらは２０４４年まで、次の２０ページに計画が記載されているかと思うのですけれども、その辺りを確認させてください。","respondent":"吉野戸籍住民課長","answer":"こちらは令和２年度に一度作成されているのですけれども、令和５年度に新たに見直して作っております。ですので、現時点ではこの年度までになっておりますけれども、また修繕などを見極めて見直しをしていくと聞いております。","id":"exchange-048"},{"speaker":"えのした委員","kind":"質問","question":"４基増えて庫数が４庫だけというと、これは１０基だと比率で言うと２６庫ぐらいとなるのかなと、数字上の問題なのです。これはどのように試算されて、４庫増えて２０庫になったのかというのをお知らせ願えるか尋ねました。","respondent":"吉野戸籍住民課長","answer":"今、お葬式ができずに長く使っているという方はやはり１週間いらっしゃいまして、火葬をすぐに行う方も若干いらっしゃいます。ですので、先ほどの式場を少し使えることになれば、この保冷庫の数も利用する時間帯も短くなるのではないかと想定しています。","id":"exchange-049"},{"speaker":"山本委員","kind":"質問","question":"足元の見通しを踏まえて１０基の増設にしていただいたということで、前向きに柔軟に増やしていただいていると受け止めております。都市計画交付金で火葬場部分の９割はやられるというところですと、その残りの１０％のところはどういう見通しなのか尋ねました。","respondent":"吉野戸籍住民課長","answer":"そちらの１０％は、施設整備基金から取り崩すような形になると思います。","id":"exchange-050"},{"speaker":"山本委員","kind":"確認","question":"では、１５億円増えるけれども、資金計画的にはもう見通しが立っていて問題ないというのが今の考えでいいでしょうかという念のための確認です。これは長期にわたって利用料が今の水準でも、この設備更新が大規模修繕も含めてやっていけそうなのかどうか、そういうところも併せて説明を求めました。","respondent":"吉野戸籍住民課長","answer":"負担金などがこの試算結果によって新たに発生しないというふうに、臨海部広域斎場組合から聞いております。先ほど言った式場を開設しますので、その部分の利用料収入も今後は見込まれるだろうというところで、この利用料収入という記載になっております。","id":"exchange-051"},{"speaker":"山本委員","kind":"質問","question":"収入増を見込んでいるということなのですけれども、単価としては特に上がるとかそういうことではなく、引き続き同じような水準で使えるという前提でよろしいか尋ねました。","respondent":"吉野戸籍住民課長","answer":"式場自体が５万６,０００円なのですけれども、それよりも若干下がりまして３万５,０００円ぐらいで想定しておりまして、今よりもアップするという試算にはなってございません。","id":"exchange-052"}]},{"id":"topic-07","title":"しながわシティランの開催","agenda":"しながわシティランの開催","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"ただその当時はやはり予算的になかなか限られているものですから、今回とても楽しみにしております。体育館はやはり雨のときに滑ったりとかすることもあるので、安心・安全に開催できるように、こちらは要望とします。","respondent":"三井スポーツ推進課長","answer":"今後のかけっこ教室等なのですが、今年度についてはこれで以上なのですが、来年度については実行委員会の中で考えていくような形、まだちょっとそこまで考えられていないのが現状にはなりますが、今後の検討課題とさせていただければと思います。","id":"exchange-053"},{"speaker":"山本委員","kind":"質問・要望","question":"質問は、今回大会要項を示されたということなので固まってきたことで、定員と申込方法のところで一部確認させていただきたいです。特に小学生・中学生などは割と多く参加したいとなると、限られた定員になってしまうのかなと少し思って、お聞きする次第です。","respondent":"三井スポーツ推進課長","answer":"プレ大会を実施しますが、今回４００名ほど申込みが来ておりますので、それ以上のものは来るかなと想定しております。ただ、区民の方優先にするかとか、そういうところも踏まえて検討していきたいと考えております。","id":"exchange-054"},{"speaker":"山本委員","kind":"質問・要望","question":"今まさに検討中ということと、あと、ファミリーのところは人気だということで理解いたしました。やはり、ご検討いただきたいということと、人数が多かったときにはやはり抽選のような平等になるような形での検討を要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"それについて、これを聞いてみてほしいと話をしたのですが、そういう意見はまず実行委員会や課長の耳に入っていらっしゃるのか。今後何かそういう検討の余地、警察の意見等も含めてお考えの余地があるのかどうか、その辺りを説明を求めました。","respondent":"三井スポーツ推進課長","answer":"実行委員会の中でコースの説明した際に、まず旧東海道を北上していった後に、今回のコースだったというところが一つあります。それが持続可能な大会になるかどうかという命運を左右するということを私たちは認識していますので、このコースでやっていきたいと考えております。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問","question":"その方から、いわゆる車いす参加の是非についてのご意見というのは特になかったのですか。そういったご意見が出るとか出ないとかということについて、出ているのか出ていないのかというところも含めて、最後に説明を求めました。","respondent":"三井スポーツ推進課長","answer":"現在、実行委員会の中にはそういった団体の方は入っておりませんで、実際に車いすの参加についての声というのを聞けていないような現状です。ただ、今回のコースについて言いますと、安全の対策でいうとなかなか難しいのかなと考えております。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"意見","question":"そういった特に身体障害のある方についての今回のこの要項については、しっかり説明をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"先ほどの臨海部広域斎場組合施設整備基本方針（案）の９ページにまさにそのことが書いてあって、「一方、近隣の公営斎場の稼働率は高くない」と。なぎさ会館の在り方というか使用について、何か今検討していることがあるのであれば、それについて教えてほしいと求めました。","respondent":"吉野戸籍住民課長","answer":"なぎさ会館自体のところが今ちょうど再開発なども入っているところがありますので、いろいろと今後検討していかなければいけないことはたくさんあるかなと考えています。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332921?Template=document&Id=2982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":54359,"voices":176}}]);
